import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { useParams } from 'react-router-dom';
import { valueMaps } from 'api';
import { errorMessage } from 'api/client';
import LayoutContainer from 'shared/LayoutContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import ConfirmModal from 'shared/ConfirmModal';
import DataTable from 'shared/DataTable';
import useActiveProject, { projectCrumbs } from 'shared/hooks/useActiveProject';
import useAsync from 'shared/hooks/useAsync';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import ValueMapModal from './ValueMapModal';
import { t } from 'i18n';

const ValueMaps = () => {
  const { projectId } = useParams();
  const dispatch = useDispatch();
  const { project } = useActiveProject(projectId);
  const { data, reload } = useAsync(() => valueMaps.list(projectId), [projectId]);
  const [editing, setEditing] = useState(null);
  const [deleting, setDeleting] = useState(null);

  const remove = async () => {
    try {
      await valueMaps.remove(projectId, deleting.id);
      dispatch(setSnackbarSuccess(t('valueMapDeleted')));
      setDeleting(null);
      reload();
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    }
  };

  return (
    <LayoutContainer
      heading={t('valueMapsPageHeader')}
      breadcrumbs={projectCrumbs(project, { title: t('valueMapsPageHeader') })}
    >
      <div className="pr-3">
        <p className="text-secondary">{t('valueMapsIntro')}</p>
        <ActionButton title={t('addButton')} onClickAction={() => setEditing({})} />
        <DataTable
          caption={t('valueMapsPageHeader')}
          rows={data || []}
          rowKey={(row) => row.id}
          emptyText={t('noValueMaps')}
          onRowClick={setEditing}
          columns={[
            { key: 'name', header: t('valueMapName'), render: (m) => <code>{m.name}</code> },
            { key: 'description', header: t('sourceDescription') },
            { key: 'entries', header: t('entries'), className: 'num', render: (m) => m.entries.length },
            {
              key: 'delete',
              header: '',
              render: (m) => (
                <button type="button" className="btn btn-link btn-sm p-0" onClick={(e) => { e.stopPropagation(); setDeleting(m); }}>{t('deleteButton')}</button>
              ),
            },
          ]}
        />
      </div>
      {editing && (
        <ValueMapModal
          projectId={projectId}
          map={editing}
          sourceSystem={project?.sourceSystemName || ''}
          targetSystem={project?.targetSystemName || ''}
          onClose={() => setEditing(null)}
          onSaved={() => { setEditing(null); reload(); }}
        />
      )}
      <ConfirmModal
        open={Boolean(deleting)}
        danger
        title={t('deleteValueMapHeader')}
        message={t('deleteValueMapMessage', { name: deleting?.name })}
        confirmLabel={t('deleteButton')}
        onConfirm={remove}
        onCancel={() => setDeleting(null)}
      />
    </LayoutContainer>
  );
};

export default ValueMaps;
