import React, { useEffect, useRef, useState } from 'react';
import { useDispatch } from 'react-redux';
import { sourceLayout, sources } from 'api';
import { errorMessage } from 'api/client';
import ActionButton from 'shared/Buttons/ActionButton';
import { CheckField, TextField } from 'shared/Form';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import { apiFormFromConfig, toSourceRequest } from './apiConfig';
import { COLUMN_TYPES, duplicateNames, emptyColumn, sameLayout, toForm, toRequest } from './layout';
import { t } from 'i18n';

/**
 * The layout of the files a source expects: which sheet, which row holds the titles, and each column's name, type and
 * date format. Uploads are checked against it. It can be typed in or detected from a sample file.
 */
const FileLayoutEditor = ({ projectId, source, loadedColumns, onSaved }) => {
  const isFile = source.kind === 'upload';
  const dispatch = useDispatch();
  const fileInput = useRef(null);
  const [form, setForm] = useState(() => toForm(source.layout));
  const [busy, setBusy] = useState(false);
  const [detected, setDetected] = useState(null);

  useEffect(() => setForm(toForm(source.layout)), [source.layout]);

  const saved = toForm(source.layout);
  const dirty = !sameLayout(form, saved);
  const duplicates = duplicateNames(form);

  const setColumn = (index, patch) => setForm((f) => ({ ...f, columns: f.columns.map((c, i) => (i === index ? { ...c, ...patch } : c)) }));
  const removeColumn = (index) => setForm((f) => ({ ...f, columns: f.columns.filter((_, i) => i !== index) }));

  const save = async () => {
    setBusy(true);
    try {
      const request = {
        ...toSourceRequest({ name: source.name, description: source.description || '', kind: source.kind, api: apiFormFromConfig(source.apiConfig), expected: '' }),
        layout: toRequest(form),
      };
      delete request.expectedColumns;
      await sources.update(projectId, source.id, request);
      dispatch(setSnackbarSuccess(t('layoutSaved')));
      onSaved();
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    } finally {
      setBusy(false);
    }
  };

  const detect = async (event) => {
    const file = event.target.files[0];
    event.target.value = '';
    if (!file) return;
    setBusy(true);
    try {
      const result = await sourceLayout.infer(projectId, source.id, file, { sheet: form.sheet, headerRow: form.headerRow });
      setForm((f) => ({ ...toForm(result.layout), strict: f.strict }));
      setDetected({ name: file.name, rows: result.rowCount, columns: result.layout.columns.length });
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    } finally {
      setBusy(false);
    }
  };

  const useLoaded = () => setForm((f) => ({
    ...f,
    columns: loadedColumns.map((name) => f.columns.find((c) => c.name.toLowerCase() === name.toLowerCase()) || { ...emptyColumn(), name }),
  }));

  return (
    <div className="panel">
      <div className="d-flex flex-wrap align-items-start">
        <div className="mr-auto">
          <h2>{t('fileLayoutHeader')}</h2>
          <div className="panel-help">{t('fileLayoutHelp')}</div>
        </div>
        <div>
          <input ref={fileInput} type="file" accept=".xlsx,.xls,.csv,.txt" className="d-none" onChange={detect} aria-label={t('detectFromFile')} />
          {isFile && <ActionButton title={t('detectFromFile')} classes="btn-sm mr-2" disabled={busy} onClickAction={() => fileInput.current.click()} />}
          {loadedColumns && loadedColumns.length > 0 && <ActionButton title={t('useLoadColumns')} classes="btn-sm" disabled={busy} onClickAction={useLoaded} />}
        </div>
      </div>

      {detected && <p className="text-secondary">{t('layoutDetected', { file: detected.name, rows: detected.rows, columns: detected.columns })}</p>}

      {isFile && (
        <>
          <div className="layout-options">
            <TextField label={t('sheet')} value={form.sheet} onChange={(v) => setForm((f) => ({ ...f, sheet: v }))} hint={t('layoutSheetHint')} style={{ maxWidth: '14rem' }} />
            <TextField label={t('headerRow')} type="number" min={1} value={form.headerRow} onChange={(v) => setForm((f) => ({ ...f, headerRow: v }))} style={{ maxWidth: '7rem' }} hint={t('headerRowHint')} />
            <CheckField label={t('layoutStrict')} checked={form.strict} onChange={(v) => setForm((f) => ({ ...f, strict: v }))} className="mb-4" />
          </div>
          {form.strict && <p className="text-secondary">{t('layoutStrictHelp')}</p>}
        </>
      )}

      {form.columns.length === 0 ? (
        <div className="text-secondary mb-2">{t('layoutNoColumns')}</div>
      ) : (
        <div className="dm-table-wrapper">
          <table className="layout-grid">
            <thead>
              <tr>
                <th scope="col">{t('columnName')}</th>
                <th scope="col">{t('columnType')}</th>
                <th scope="col">{t('dateFormat')}</th>
                <th scope="col" className="narrow">{t('columnRequired')}</th>
                <th scope="col">{t('sourceDescription')}</th>
                <th scope="col"><span className="sr-only">{t('removeButton')}</span></th>
              </tr>
            </thead>
            <tbody>
              {form.columns.map((column, index) => (
                <tr key={index}>
                  <td><input type="text" aria-label={t('columnName')} value={column.name} onChange={(e) => setColumn(index, { name: e.target.value })} /></td>
                  <td>
                    <select aria-label={t('columnType')} value={column.type} onChange={(e) => setColumn(index, { type: e.target.value })}>
                      {COLUMN_TYPES.map((type) => <option key={type} value={type}>{t(`columnType_${type}`)}</option>)}
                    </select>
                  </td>
                  <td>
                    {column.type === 'date'
                      ? <input type="text" aria-label={t('dateFormat')} placeholder="dd/MM/yyyy|yyyy-MM-dd" value={column.format} onChange={(e) => setColumn(index, { format: e.target.value })} />
                      : <span className="text-secondary">—</span>}
                  </td>
                  <td className="narrow"><input type="checkbox" aria-label={t('columnRequired')} checked={column.required} onChange={(e) => setColumn(index, { required: e.target.checked })} /></td>
                  <td><input type="text" aria-label={t('sourceDescription')} value={column.description} onChange={(e) => setColumn(index, { description: e.target.value })} /></td>
                  <td><button type="button" className="btn btn-link btn-sm p-0" onClick={() => removeColumn(index)}>{t('removeButton')}</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {duplicates.length > 0 && <ul className="issue-list mt-2"><li className="warning">{t('layoutDuplicates', { names: duplicates.join(', ') })}</li></ul>}

      <div className="mt-3">
        <ActionButton title={t('addColumn')} classes="mr-2" onClickAction={() => setForm((f) => ({ ...f, columns: [...f.columns, emptyColumn()] }))} />
        <ActionButton title={t('saveLayout')} outline={false} disabled={busy || !dirty || duplicates.length > 0} onClickAction={save} />
        {dirty && <ActionButton title={t('discardChanges')} buttonColor="secondary" classes="ml-2" onClickAction={() => { setForm(saved); setDetected(null); }} />}
      </div>
    </div>
  );
};

export default FileLayoutEditor;
