import { useSelector } from 'react-redux';

const LEVEL = { viewer: 1, editor: 2, approver: 3, administrator: 4 };

/**
 * What the signed-in user may do. The server decides and enforces this; the screens only use it to avoid offering
 * buttons that would be refused. `projectRole` is the `myRole` the API returns with a project.
 */
export const permissions = (projectRole, isAdministrator) => {
  const level = isAdministrator ? LEVEL.administrator : (LEVEL[projectRole] || 0);
  return {
    isAdministrator: Boolean(isAdministrator),
    canEdit: level >= LEVEL.editor,
    canApprove: level >= LEVEL.approver,
  };
};

const useProjectRole = (project) => {
  const isAdministrator = useSelector(({ account }) => account.loginUser?.isAdministrator);
  return permissions(project?.myRole, isAdministrator);
};

export default useProjectRole;
