import React from 'react';
import { t } from 'i18n';

const RowTools = ({ index, count, onMove, onRemove }) => (
  <span className="row-tools">
    <button type="button" disabled={index === 0} onClick={() => onMove(-1)} aria-label={t('moveUp')} title={t('moveUp')}>↑</button>
    <button type="button" disabled={index === count - 1} onClick={() => onMove(1)} aria-label={t('moveDown')} title={t('moveDown')}>↓</button>
    <button type="button" className="danger" onClick={onRemove} aria-label={t('removeButton')} title={t('removeButton')}>✕</button>
  </span>
);

export default RowTools;
