import { useMemo, useState } from 'react';
import { transactionTypes } from 'api';
import useAsync from './useAsync';

export const SAMPLE = 'sample';

/**
 * Which data a routine's page is showing: one of its live loads, or the sample. Shared by the data preview and
 * reconciliation pages so they always agree on what "the current data" is.
 */
const useRunSelection = (projectId, typeId, logicVersion) => {
  const runState = useAsync(
      () => (typeId ? transactionTypes.runs(projectId, typeId) : Promise.resolve(null)),
      [projectId, typeId, logicVersion],
  );
  const runs = useMemo(() => runState.data || [], [runState.data]);
  const [choice, setChoice] = useState(''); // '' = the newest live load, SAMPLE = the sample, otherwise a live dataset id

  const useSample = choice === SAMPLE || (choice === '' && runs.length === 0);
  const currentRun = useSample ? null : (runs.find((r) => r.datasetId === choice) || runs[0]);

  return {
    runState,
    runs,
    loaded: Boolean(runState.data),
    useSample,
    currentRun,
    datasetId: currentRun?.datasetId,
    purpose: useSample ? 'sample' : 'live',
    selectedValue: useSample ? SAMPLE : (currentRun?.datasetId || ''),
    choose: setChoice,
  };
};

export default useRunSelection;
