import client from './client';

const data = (promise) => promise.then((response) => response.data);

export const auth = {
  login: (email, password) => data(client.post('/api/auth/login', { email, password })),
};

export const users = {
  list: () => data(client.get('/api/users')),
  create: (user) => data(client.post('/api/users', user)),
  update: (id, user) => data(client.put(`/api/users/${id}`, user)),
  resetPassword: (id, password) => data(client.post(`/api/users/${id}/reset-password`, { password })),
};

export const projects = {
  list: (includeArchived = false) => data(client.get('/api/projects', { params: { includeArchived } })),
  get: (id) => data(client.get(`/api/projects/${id}`)),
  create: (project) => data(client.post('/api/projects', project)),
  update: (id, project) => data(client.put(`/api/projects/${id}`, project)),
  archive: (id, archived) => data(client.post(`/api/projects/${id}/archive`, null, { params: { archived } })),
  remove: (id) => data(client.delete(`/api/projects/${id}`)),
};

export const sources = {
  list: (projectId) => data(client.get(`/api/projects/${projectId}/sources`)),
  get: (projectId, id) => data(client.get(`/api/projects/${projectId}/sources/${id}`)),
  create: (projectId, source) => data(client.post(`/api/projects/${projectId}/sources`, source)),
  update: (projectId, id, source) => data(client.put(`/api/projects/${projectId}/sources/${id}`, source)),
  remove: (projectId, id) => data(client.delete(`/api/projects/${projectId}/sources/${id}`)),
  test: (projectId, id, unsaved) => data(client.post(`/api/projects/${projectId}/sources/${id}/test`, unsaved || null)),
  extract: (projectId, id, purpose = 'live') => data(client.post(`/api/projects/${projectId}/sources/${id}/extract`, null, { params: { purpose } })),
  upload: (projectId, id, file, { sheet, headerRow, purpose = 'live' } = {}) => {
    const form = new FormData();
    form.append('file', file);
    if (sheet) form.append('sheet', sheet);
    if (headerRow) form.append('headerRow', headerRow);
    form.append('purpose', purpose);
    return data(client.post(`/api/projects/${projectId}/sources/${id}/upload`, form, { headers: { 'Content-Type': 'multipart/form-data' } }));
  },
  datasets: (projectId, id) => data(client.get(`/api/projects/${projectId}/sources/${id}/datasets`)),
};

export const datasets = {
  rows: (projectId, id, skip, take) => data(client.get(`/api/projects/${projectId}/datasets/${id}/rows`, { params: { skip, take } })),
  remove: (projectId, id) => data(client.delete(`/api/projects/${projectId}/datasets/${id}`)),
};

const typeUrl = (projectId, id = '') => `/api/projects/${projectId}/transaction-types${id ? `/${id}` : ''}`;

export const transactionTypes = {
  list: (projectId) => data(client.get(typeUrl(projectId))),
  get: (projectId, id) => data(client.get(typeUrl(projectId, id))),
  create: (projectId, type) => data(client.post(typeUrl(projectId), type)),
  update: (projectId, id, type) => data(client.put(typeUrl(projectId, id), type)),
  remove: (projectId, id) => data(client.delete(typeUrl(projectId, id))),
  saveDefinition: (projectId, id, body) => data(client.put(`${typeUrl(projectId, id)}/definition`, body)),
  versions: (projectId, id) => data(client.get(`${typeUrl(projectId, id)}/versions`)),
  validate: (projectId, id, body, config) => data(client.post(`${typeUrl(projectId, id)}/validate`, body, config)),
  preview: (projectId, id, body, config) => data(client.post(`${typeUrl(projectId, id)}/preview`, body, config)),
  reconciliation: (projectId, id, body) => data(client.post(`${typeUrl(projectId, id)}/reconciliation`, body)),
  signOff: (projectId, id, body) => data(client.post(`${typeUrl(projectId, id)}/signoff`, body)),
  changeLog: (projectId, id) => data(client.get(`${typeUrl(projectId, id)}/changelog`)),
  runs: (projectId, id) => data(client.get(`${typeUrl(projectId, id)}/runs`)),
  reviewRun: (projectId, id, datasetId, body) => data(client.post(`${typeUrl(projectId, id)}/runs/${datasetId}/review`, body)),
  export: (projectId, id, params) => client.get(`${typeUrl(projectId, id)}/export`, { params, responseType: 'blob' }),
};

export const projectMembers = {
  list: (projectId) => data(client.get(`/api/projects/${projectId}/members`)),
  set: (projectId, member) => data(client.put(`/api/projects/${projectId}/members`, member)),
  remove: (projectId, userId) => data(client.delete(`/api/projects/${projectId}/members/${userId}`)),
};

export const sourceLayout = {
  infer: (projectId, id, file, { sheet, headerRow } = {}) => {
    const form = new FormData();
    form.append('file', file);
    if (sheet) form.append('sheet', sheet);
    if (headerRow) form.append('headerRow', headerRow);
    return data(client.post(`/api/projects/${projectId}/sources/${id}/infer-layout`, form, { headers: { 'Content-Type': 'multipart/form-data' } }));
  },
};

/** Every data source, transformation routine and lookup table across projects, for the Configuration area. */
export const configuration = {
  sources: () => data(client.get('/api/configuration/sources')),
  routines: () => data(client.get('/api/configuration/routines')),
  lookups: () => data(client.get('/api/configuration/lookups')),
};

export const targetOutput = {
  outputs: (projectId) => data(client.get(`/api/projects/${projectId}/export/outputs`)),
};

export const valueMaps = {
  list: (projectId) => data(client.get(`/api/projects/${projectId}/value-maps`)),
  create: (projectId, map) => data(client.post(`/api/projects/${projectId}/value-maps`, map)),
  update: (projectId, id, map) => data(client.put(`/api/projects/${projectId}/value-maps/${id}`, map)),
  remove: (projectId, id) => data(client.delete(`/api/projects/${projectId}/value-maps/${id}`)),
};

export const expression = {
  functions: () => data(client.get('/api/expression/functions')),
};

export const projectExport = (projectId) =>
  client.get(`/api/projects/${projectId}/export`, { responseType: 'blob' });
