import React, { useMemo, useState } from 'react';
import { useExpressionContext } from './ExpressionContext';
import { t } from 'i18n';

const quoteColumn = (name) => `[${name.replace(/]/g, ']]')}]`;

const Chip = ({ children, title, onClick }) => (
  <button type="button" className="chip" title={title} onClick={onClick}>{children}</button>
);

/**
 * Reference beside the editor: what can be typed, and a click inserts it. Shows the source columns,
 * the working values defined so far, the project's value maps and the function list.
 */
const HelpPanel = ({ columns, variables, valueMapNames, functions, repeating, sourceSystem }) => {
  const context = useExpressionContext();
  const [search, setSearch] = useState('');
  const [open, setOpen] = useState(null);

  const insert = (text) => context && context.insert(text);

  const filtered = useMemo(() => {
    const term = search.trim().toLowerCase();
    return (functions || []).filter((f) => !term || f.name.toLowerCase().includes(term) || f.description.toLowerCase().includes(term) || f.category.toLowerCase().includes(term));
  }, [functions, search]);

  const byCategory = useMemo(() => {
    const groups = {};
    filtered.forEach((f) => (groups[f.category] = groups[f.category] || []).push(f));
    return groups;
  }, [filtered]);

  return (
    <aside className="help-panel" aria-label={t('helpPanel')}>
      <div className="help-section">
        <div className="help-title">{t('helpColumns', { system: sourceSystem })}</div>
        <div className="chips">
          {columns.length === 0 && <span className="text-secondary">{t('helpNoColumns')}</span>}
          {columns.map((column) => <Chip key={column} title={t('helpInsert')} onClick={() => insert(quoteColumn(column))}>{column}</Chip>)}
        </div>
      </div>

      <div className="help-section">
        <div className="help-title">{t('helpVariables')}</div>
        <div className="chips">
          {variables.filter((v) => v.name).map((v) => <Chip key={v.name} onClick={() => insert(`$${v.name}`)}>{`$${v.name}`}</Chip>)}
          {repeating && (
            <>
              <Chip title={t('helpIndexTitle')} onClick={() => insert('$index')}>$index</Chip>
              <Chip title={t('helpCountTitle')} onClick={() => insert('$count')}>$count</Chip>
            </>
          )}
          {variables.filter((v) => v.name).length === 0 && !repeating && <span className="text-secondary">{t('helpNoVariables')}</span>}
        </div>
      </div>

      {valueMapNames.length > 0 && (
        <div className="help-section">
          <div className="help-title">{t('helpValueMaps')}</div>
          <div className="chips">
            {valueMapNames.map((name) => <Chip key={name} onClick={() => insert(`LOOKUP('${name.replace(/'/g, "''")}', )`)}>{name}</Chip>)}
          </div>
        </div>
      )}

      <div className="help-section">
        <div className="help-title">{t('helpFunctions')}</div>
        <input
          type="search"
          className="form-control form-control-sm mb-2"
          placeholder={t('helpSearch')}
          aria-label={t('helpSearch')}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <div className="fn-list">
          {Object.keys(byCategory).map((category) => (
            <div key={category}>
              <div className="fn-category">{category}</div>
              {byCategory[category].map((fn) => (
                <div key={fn.name} className="fn">
                  <button type="button" className="fn-name" onClick={() => setOpen(open === fn.name ? null : fn.name)} aria-expanded={open === fn.name}>
                    <code>{fn.signature}</code>
                  </button>
                  {open === fn.name && (
                    <div className="fn-detail">
                      <p>{fn.description}</p>
                      <code className="fn-example">{fn.example}</code>
                      <div>
                        <button type="button" className="btn btn-link btn-sm p-0 mr-3" onClick={() => insert(`${fn.name}()`)}>{t('helpInsertFunction')}</button>
                        <button type="button" className="btn btn-link btn-sm p-0" onClick={() => insert(fn.example)}>{t('helpInsertExample')}</button>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          ))}
          {filtered.length === 0 && <span className="text-secondary">{t('helpNoFunctions')}</span>}
        </div>
      </div>

      <div className="help-section">
        <div className="help-title">{t('helpSyntax')}</div>
        <ul className="syntax">
          <li><code>[Column name]</code> {t('helpSyntaxColumn')}</li>
          <li><code>$name</code> {t('helpSyntaxVariable')}</li>
          <li><code>'text'</code> {t('helpSyntaxText')}</li>
          <li><code>&amp;</code> {t('helpSyntaxJoin')}</li>
          <li><code>== != &lt; &gt; AND OR NOT</code></li>
        </ul>
      </div>
    </aside>
  );
};

export default HelpPanel;
