export const appRoutes = {
  login: '/',
  home: '/dashboard',
  users: '/users',

  // Configuration: the building blocks, across all projects
  configSources: '/configuration/data-sources',
  configTransformations: '/configuration/transformations',
  configLookups: '/configuration/lookup-tables',

  projects: '/projects',

  // Inside a project
  project: (projectId) => `/projects/${projectId}`,
  sources: (projectId) => `/projects/${projectId}/sources`,
  source: (projectId, sourceId) => `/projects/${projectId}/sources/${sourceId}`,
  transactionTypes: (projectId) => `/projects/${projectId}/transaction-types`,
  logic: (projectId, typeId) => `/projects/${projectId}/transaction-types/${typeId}`,
  changeLog: (projectId, typeId) => `/projects/${projectId}/transaction-types/${typeId}/changelog`,
  valueMaps: (projectId) => `/projects/${projectId}/value-maps`,
  preview: (projectId, typeId = '') => `/projects/${projectId}/data-preview${typeId ? `/${typeId}` : ''}`,
  reconciliation: (projectId, typeId = '') => `/projects/${projectId}/reconciliation${typeId ? `/${typeId}` : ''}`,
  output: (projectId) => `/projects/${projectId}/target-output`,
};
