import React, { useState } from 'react';
import { useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { projects } from 'api';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import DataTable from 'shared/DataTable';
import { CheckField } from 'shared/Form';
import useAsync from 'shared/hooks/useAsync';
import { formatDateTime } from 'utils/format';
import ProjectModal from './ProjectModal';
import { t } from 'i18n';

const Projects = () => {
  const { loginUser } = useSelector(({ account }) => account);
  const navigate = useNavigate();
  const [showArchived, setShowArchived] = useState(false);
  const [adding, setAdding] = useState(false);
  const { data } = useAsync(() => projects.list(showArchived), [showArchived]);

  return (
    <LayoutContainer
      heading={t('projectsPageHeader')}
      breadcrumbs={[
        { title: t('homePageHeader'), isActive: false, to: appRoutes.home },
        { title: t('projectsPageHeader'), isActive: true },
      ]}
    >
      <div className="pr-3">
        <p className="text-secondary">{t('projectsIntro')}</p>
        <div className="toolbar">
          {loginUser?.isAdministrator && <ActionButton title={t('addProjectButton')} onClickAction={() => setAdding(true)} />}
          <CheckField label={t('showArchived')} checked={showArchived} onChange={setShowArchived} className="mb-2" />
        </div>
        <DataTable
          caption={t('projectsPageHeader')}
          rows={data || []}
          rowKey={(row) => row.id}
          onRowClick={(row) => navigate(appRoutes.project(row.id))}
          columns={[
            { key: 'name', header: t('projectName'), render: (p) => `${p.name}${p.archived ? ` ${t('archivedSuffix')}` : ''}` },
            { key: 'systems', header: t('migrationPath'), render: (p) => `${p.sourceSystemName} → ${p.targetSystemName}` },
            { key: 'dataSourceCount', header: t('sourcesPageHeader'), className: 'num' },
            { key: 'transactionTypeCount', header: t('transactionTypesPageHeader'), className: 'num' },
            { key: 'approved', header: t('approvedCount'), className: 'num', render: (p) => `${p.approvedTransactionTypeCount} / ${p.transactionTypeCount}` },
            { key: 'updatedUtc', header: t('lastUpdated'), render: (p) => formatDateTime(p.updatedUtc) },
          ]}
        />
      </div>
      {adding && <ProjectModal onClose={() => setAdding(false)} onSaved={(project) => navigate(appRoutes.project(project.id))} />}
    </LayoutContainer>
  );
};

export default Projects;
