import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { projects } from 'api';
import { errorMessage } from 'api/client';
import ModalContainer from 'shared/ModalContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import { CheckField, TextAreaField, TextField } from 'shared/Form';
import useProjectRole from 'shared/hooks/useProjectRole';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import { t } from 'i18n';

const ProjectModal = ({ project, onClose, onSaved }) => {
  const dispatch = useDispatch();
  const access = useProjectRole(project);
  const [form, setForm] = useState({
    name: project?.name || '',
    description: project?.description || '',
    sourceSystemName: project?.sourceSystemName || 'Source system',
    targetSystemName: project?.targetSystemName || 'Target system',
    projectManager: project?.projectManager || '',
    projectManagerContact: project?.projectManagerContact || '',
    logicBuilder: project?.logicBuilder || '',
    signOffOwner: project?.signOffOwner || '',
    signOffContact: project?.signOffContact || '',
    clientContact: project?.clientContact || '',
    migrationDate: project?.migrationDate || '',
    governanceNotes: project?.governanceNotes || '',
    requireIndependentApproval: Boolean(project?.requireIndependentApproval),
  });
  const [errors, setErrors] = useState({});
  const [busy, setBusy] = useState(false);
  const set = (field) => (value) => setForm((f) => ({ ...f, [field]: value }));

  const save = async () => {
    const found = {};
    ['name', 'sourceSystemName', 'targetSystemName'].forEach((field) => {
      if (!form[field].trim()) found[field] = t('requiredField');
    });
    setErrors(found);
    if (Object.keys(found).length) return;

    setBusy(true);
    try {
      const body = { ...project, ...form, migrationDate: form.migrationDate || null };
      const saved = project?.id ? await projects.update(project.id, body) : await projects.create(body);
      dispatch(setSnackbarSuccess(t('projectSaved')));
      onSaved(saved);
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    } finally {
      setBusy(false);
    }
  };

  return (
    <ModalContainer
      modal
      toggleModal={onClose}
      header={project?.id ? t('editProjectHeader') : t('addProjectHeader')}
      subHeader={t('projectModalIntro')}
      modalFooterContent={(
        <>
          <ActionButton title={t('cancelButton')} buttonColor="secondary" classes="mb-0" onClickAction={onClose} />
          <ActionButton title={t('saveButton')} outline={false} classes="mb-0" disabled={busy} onClickAction={save} />
        </>
      )}
    >
      <TextField label={t('projectName')} placeholder={t('projectNamePlaceholder')} value={form.name} onChange={set('name')} error={errors.name} required autoFocus />
      <TextAreaField label={t('projectDescription')} value={form.description} onChange={set('description')} />
      <div className="d-flex">
        <TextField className="mr-2" label={t('sourceSystem')} value={form.sourceSystemName} onChange={set('sourceSystemName')} error={errors.sourceSystemName} required />
        <TextField label={t('targetSystem')} value={form.targetSystemName} onChange={set('targetSystemName')} error={errors.targetSystemName} required />
      </div>
      <div className="section-label">{t('governanceSection')}</div>
      <div className="d-flex">
        <TextField className="mr-2 flex-fill" label={t('projectManager')} value={form.projectManager} onChange={set('projectManager')} />
        <TextField className="flex-fill" label={t('projectManagerContact')} value={form.projectManagerContact} onChange={set('projectManagerContact')} />
      </div>
      <TextField label={t('logicBuilder')} value={form.logicBuilder} onChange={set('logicBuilder')} />
      <div className="d-flex">
        <TextField className="mr-2 flex-fill" label={t('signOffOwner')} value={form.signOffOwner} onChange={set('signOffOwner')} />
        <TextField className="flex-fill" label={t('signOffContact')} value={form.signOffContact} onChange={set('signOffContact')} />
      </div>
      <div className="d-flex">
        <TextField className="mr-2 flex-fill" label={t('clientContact')} value={form.clientContact} onChange={set('clientContact')} />
        <TextField className="flex-fill" label={t('migrationDate')} type="date" value={form.migrationDate} onChange={set('migrationDate')} />
      </div>
      {(access.isAdministrator || !project?.id) && (
        <>
          <CheckField label={t('requireIndependentApproval')} checked={form.requireIndependentApproval} onChange={set('requireIndependentApproval')} />
          <div className="field-hint mb-2">{t('requireIndependentApprovalHint')}</div>
        </>
      )}
      <TextAreaField label={t('governanceNotes')} rows={2} value={form.governanceNotes} onChange={set('governanceNotes')} />
    </ModalContainer>
  );
};

export default ProjectModal;
