// Pure helpers for editing a transformation definition in the UI.

let counter = 0;
export const newId = (prefix) => {
  counter += 1;
  return `${prefix}${Date.now().toString(36)}${counter.toString(36)}${Math.random().toString(36).slice(2, 5)}`;
};

export const newField = (overrides = {}) => ({
  target: '',
  expression: '',
  type: 'text',
  required: false,
  decimals: null,
  format: null,
  description: null,
  ...overrides,
});

export const newOutput = (overrides = {}) => ({
  id: newId('out'),
  name: '',
  description: null,
  condition: null,
  repeatCount: null,
  uniqueKey: [],
  fields: [newField()],
  ...overrides,
});

export const newControl = (overrides = {}) => ({ id: newId('ctl'), name: '', sourceExpression: '', outputId: '', field: '', tolerance: 0, ...overrides });

export const newVariable = (overrides = {}) => ({ name: '', expression: '', description: null, ...overrides });

export const emptyDefinition = () => ({ fillDown: [], groupBy: null, filter: null, variables: [], outputs: [], controls: [] });

/** Moves item `index` by `delta` places (-1 up, +1 down); returns a new array. */
export const moveItem = (list, index, delta) => {
  const target = index + delta;
  if (target < 0 || target >= list.length) return list;
  const copy = list.slice();
  const [item] = copy.splice(index, 1);
  copy.splice(target, 0, item);
  return copy;
};

export const replaceAt = (list, index, value) => list.map((item, i) => (i === index ? value : item));

export const removeAt = (list, index) => list.filter((_, i) => i !== index);

/** Column names referenced as [Column] (a literal ] is written ]]) anywhere in the definition's expressions. */
export const referencedColumns = (definition) => {
  const used = new Set();
  const scan = (text) => {
    if (!text) return;
    const pattern = /\[((?:[^\]]|\]\])+)\]/g;
    let match = pattern.exec(text);
    while (match) {
      used.add(match[1].replace(/\]\]/g, ']').trim().toLowerCase());
      match = pattern.exec(text);
    }
  };
  scan(definition.filter);
  scan(definition.groupBy);
  (definition.fillDown || []).forEach((name) => used.add(String(name).trim().toLowerCase()));
  (definition.variables || []).forEach((v) => scan(v.expression));
  (definition.controls || []).forEach((c) => scan(c.sourceExpression));
  (definition.outputs || []).forEach((o) => {
    scan(o.condition);
    scan(o.repeatCount);
    (o.fields || []).forEach((f) => scan(f.expression));
  });
  return used;
};

/** Issues whose path is exactly `path`, or (with prefix = true) starts with it. */
export const issuesAt = (issues, path, prefix = false) =>
  (issues || []).filter((i) => (prefix ? i.path === path || i.path.startsWith(`${path}.`) || i.path.startsWith(`${path}[`) : i.path === path));

/** Strips empty strings to null so the saved JSON is tidy and unchanged logic compares equal. */
export const normaliseDefinition = (definition) => {
  const blank = (value) => (value === undefined || value === null || String(value).trim() === '' ? null : value);
  return {
    fillDown: (definition.fillDown || []).map((c) => c.trim()).filter(Boolean),
    groupBy: blank(definition.groupBy),
    filter: blank(definition.filter),
    variables: (definition.variables || []).map((v) => ({ name: v.name.trim(), expression: v.expression, description: blank(v.description) })),
    outputs: (definition.outputs || []).map((o) => ({
      id: o.id,
      name: o.name.trim(),
      description: blank(o.description),
      condition: blank(o.condition),
      repeatCount: blank(o.repeatCount),
      uniqueKey: o.uniqueKey || [],
      fields: (o.fields || []).map((f) => ({
        target: f.target.trim(),
        expression: f.expression,
        type: f.type,
        required: Boolean(f.required),
        decimals: f.type === 'number' && f.decimals !== '' && f.decimals !== null && f.decimals !== undefined ? Number(f.decimals) : null,
        format: f.type === 'date' ? blank(f.format) : null,
        description: blank(f.description),
      })),
    })),
    controls: (definition.controls || []).map((c) => ({
      id: c.id,
      name: c.name.trim(),
      sourceExpression: c.sourceExpression,
      outputId: c.outputId,
      field: c.field,
      tolerance: Number(c.tolerance) || 0,
    })),
  };
};

export const sameDefinition = (a, b) => JSON.stringify(normaliseDefinition(a)) === JSON.stringify(normaliseDefinition(b));

/** The column when an expression is nothing but one column reference, e.g. `[TRX_TYPE]`; otherwise null. */
export const directColumn = (expression) => {
  const match = /^\s*\[((?:[^\]]|\]\])+)\]\s*$/.exec(expression || '');
  return match ? match[1].replace(/\]\]/g, ']').trim() : null;
};

export const columnReference = (column) => `[${column.replace(/\]/g, ']]')}]`;

const columnsIn = (text) => {
  const found = [];
  const pattern = /\[((?:[^\]]|\]\])+)\]/g;
  let match = pattern.exec(text || '');
  while (match) {
    found.push(match[1].replace(/\]\]/g, ']').trim());
    match = pattern.exec(text || '');
  }
  return found;
};

const variablesIn = (text) => [...(text || '').matchAll(/\$([A-Za-z_][A-Za-z0-9_]*)/g)].map((m) => m[1].toLowerCase());

/** Source columns an expression depends on, following $variables to the columns they use. */
export const sourceColumnsOf = (expression, variables) => {
  const byName = new Map((variables || []).map((v) => [v.name.trim().toLowerCase(), v.expression]));
  const columns = new Set();
  const seen = new Set();
  const walk = (text) => {
    columnsIn(text).forEach((c) => columns.add(c));
    variablesIn(text).forEach((name) => {
      if (seen.has(name) || !byName.has(name)) return;
      seen.add(name);
      walk(byName.get(name));
    });
  };
  walk(expression);
  return [...columns];
};

/**
 * The column mapping of a definition: for each source column (lower case), the destination columns it feeds.
 * `direct` is true when the destination is a plain copy of the column, false when it is derived through an expression.
 */
export const buildMapping = (definition) => {
  const mapping = new Map();
  (definition.outputs || []).forEach((output) => {
    (output.fields || []).forEach((field) => {
      if (!field.target.trim()) return;
      const direct = directColumn(field.expression);
      sourceColumnsOf(field.expression, definition.variables).forEach((column) => {
        const key = column.toLowerCase();
        if (!mapping.has(key)) mapping.set(key, []);
        mapping.get(key).push({ outputId: output.id, table: output.name, target: field.target, direct: Boolean(direct) });
      });
    });
  });
  return mapping;
};

/** Adds a destination column, a plain copy, for every source column the output does not already copy. */
export const withAllSourceColumns = (output, columns) => {
  const copied = new Set((output.fields || []).map((f) => (directColumn(f.expression) || '').toLowerCase()));
  const named = new Set((output.fields || []).map((f) => f.target.trim().toLowerCase()));
  const blank = (output.fields || []).filter((f) => !f.target.trim() && !f.expression.trim());
  const fields = (output.fields || []).filter((f) => !blank.includes(f));
  columns.forEach((column) => {
    if (copied.has(column.toLowerCase()) || named.has(column.toLowerCase())) return;
    fields.push(newField({ target: column, expression: columnReference(column) }));
  });
  return { ...output, fields };
};
