import { useCallback, useEffect, useRef, useState } from 'react';
import { useDispatch } from 'react-redux';
import { errorMessage } from 'api/client';
import { setSnackbarError } from 'shared/redux';

/**
 * Runs an API call when the page opens (and whenever deps change) and keeps the result.
 * `reload()` runs it again. Failures show in the snackbar and are also returned as `error`.
 */
const useAsync = (load, deps = []) => {
  const dispatch = useDispatch();
  const [state, setState] = useState({ data: null, loading: true, error: null });
  const latest = useRef(0);
  const loadRef = useRef(load);
  loadRef.current = load;

  const run = useCallback(() => {
    const ticket = ++latest.current;
    setState((s) => ({ ...s, loading: true, error: null }));
    return Promise.resolve()
        .then(() => loadRef.current())
        .then((data) => {
          if (ticket === latest.current) setState({ data, loading: false, error: null });
          return data;
        })
        .catch((error) => {
          if (ticket !== latest.current) return null;
          const message = errorMessage(error);
          setState((s) => ({ ...s, loading: false, error: message }));
          if (message) dispatch(setSnackbarError(message));
          return null;
        });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);

  useEffect(() => {
    run();
    return () => {
      latest.current += 1; // ignore a response that arrives after the page has gone
    };
  }, [run]);

  return { ...state, reload: run };
};

export default useAsync;
