import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { NavLink, useNavigate } from 'react-router-dom';
import { appRoutes } from 'app/routes';
import { signOut } from 'shared/account';
import ActionButton from 'shared/Buttons/ActionButton';
import 'assets/styles/index.scss';
import 'assets/styles/navMenu.scss';
import { t } from 'i18n';

const SideNavBar = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { loginUser, activeProject } = useSelector(({ account }) => account);

  const handleLogout = () => {
    dispatch(signOut());
    navigate(appRoutes.login);
  };

  const projectId = activeProject?.id;

  return (
    <div className="d-flex">
      <nav className="side-menu" aria-label={t('mainNavigation')}>
        <div className="list pl-1">
          <div className="list-section first">{t('configurationHeader')}</div>
          <NavLink end to={appRoutes.projects} className="list-item" id="projectsMenu">{t('projectsPageHeader')}</NavLink>
          <NavLink to={appRoutes.configSources} className="list-item" id="configSourcesMenu">{t('dataSourcesPageHeader')}</NavLink>
          <NavLink to={appRoutes.configTransformations} className="list-item" id="configTransformationsMenu">{t('transformationsPageHeader')}</NavLink>
          <NavLink to={appRoutes.configLookups} className="list-item" id="configLookupsMenu">{t('lookupsPageHeader')}</NavLink>

          {projectId && (
            <>
              <div className="list-section">{activeProject.name}</div>
              <NavLink end to={appRoutes.project(projectId)} className="list-item">{t('projectOverviewPageHeader')}</NavLink>
              <div className="list-subsection">{t('menuSetUp')}</div>
              <NavLink to={appRoutes.sources(projectId)} className="list-item">{t('sourceFilesPageHeader')}</NavLink>
              <NavLink to={appRoutes.valueMaps(projectId)} className="list-item">{t('valueMapsPageHeader')}</NavLink>
              <NavLink to={appRoutes.transactionTypes(projectId)} className="list-item">{t('transactionTypesPageHeader')}</NavLink>
              <div className="list-subsection">{t('menuRun')}</div>
              <NavLink to={appRoutes.preview(projectId)} className="list-item">{t('previewPageHeader')}</NavLink>
              <NavLink to={appRoutes.reconciliation(projectId)} className="list-item">{t('reconciliationPageHeader')}</NavLink>
              <NavLink to={appRoutes.output(projectId)} className="list-item">{t('outputMenu')}</NavLink>
            </>
          )}

          {loginUser?.isAdministrator && (
            <>
              <div className="list-section">{t('administrationHeader')}</div>
              <NavLink to={appRoutes.users} className="list-item" id="usersMenu">{t('usersPageHeader')}</NavLink>
            </>
          )}
        </div>
        <div className="btn-log-out">
          <p className="mb-0">{`${t('loggedInAsUser')}: ${loginUser?.name || ''}`}</p>
          <p>{`${t('selectedProject')}: ${activeProject?.name || ''}`}</p>
          <ActionButton outline buttonColor="danger" title={t('logoutButton')} classes="w-100" onClickAction={handleLogout} />
        </div>
      </nav>
    </div>
  );
};

export default SideNavBar;
