import React from 'react';
import { Card, CardBody } from 'reactstrap';
import { NavLink } from 'react-router-dom';
import { icons } from 'assets/images';

const MenuCard = ({ menuIcon, header, description, navigateTo }) => (
  <Card className={`menu-card ${navigateTo ? 'cursor-pointer' : ''}`}>
    <NavLink to={navigateTo || '#'}>
      <CardBody>
        <img src={icons[menuIcon]} alt="" width={40} className="mb-2" />
        <div className="menu-card-text">
          <div className="mb-0">{header}</div>
          {description && <div className="text-secondary mt-1">{description}</div>}
        </div>
      </CardBody>
    </NavLink>
  </Card>
);

export default MenuCard;
