import React from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';

const ModalContainer = ({
  modal,
  toggleModal,
  header,
  subHeader,
  children,
  modalFooterContent,
  modalBodyClasses = '',
  size,
}) => (
  <Modal isOpen={modal} toggle={toggleModal} zIndex={10001} keyboard={false} size={size} backdrop="static">
    <ModalHeader toggle={toggleModal}>
      <div className="w-100">{header}</div>
      {subHeader && <div className="text-secondary w-100">{subHeader}</div>}
    </ModalHeader>
    <ModalBody className={modalBodyClasses}>{children}</ModalBody>
    {modalFooterContent && <ModalFooter>{modalFooterContent}</ModalFooter>}
  </Modal>
);

export default ModalContainer;
