const dateTime = new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });

/** API timestamps are UTC but serialised without a zone. */
export const formatDateTime = (value) => {
  if (!value) return '';
  const text = String(value);
  const date = new Date(/[zZ]|[+-]\d\d:\d\d$/.test(text) ? text : `${text}Z`);
  return Number.isNaN(date.getTime()) ? '' : dateTime.format(date);
};

export const formatInteger = (value) => (Number.isFinite(value) ? value.toLocaleString('en') : '');

/** A cell value from the source data or a transformed row, as text for display. */
export const displayValue = (value, decimals) => {
  if (value === null || value === undefined || value === '') return '';
  if (typeof value === 'number') {
    return Number.isInteger(value) && decimals === undefined
      ? String(value)
      : value.toLocaleString('en', decimals !== undefined && decimals !== null
        ? { minimumFractionDigits: decimals, maximumFractionDigits: decimals }
        : { maximumFractionDigits: 12 });
  }
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  return String(value);
};

/** A number with up to three decimals and thousand separators, for control totals. */
export const formatTotal = (value) => (Number.isFinite(value) ? value.toLocaleString('en', { maximumFractionDigits: 3 }) : '');

const dateOnly = new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });

/** A plain date (yyyy-MM-dd) as text; no time zone shifting. */
export const formatDate = (value) => {
  if (!value) return '';
  const date = new Date(`${value}T00:00:00`);
  return Number.isNaN(date.getTime()) ? '' : dateOnly.format(date);
};
