import React, { useEffect, useMemo, useState } from 'react';
import { useDispatch } from 'react-redux';
import { NavLink, useParams } from 'react-router-dom';
import { transactionTypes } from 'api';
import { errorMessage } from 'api/client';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import { Pager } from 'shared/DataTable';
import { CheckField, SelectField } from 'shared/Form';
import { Stepper, Tile } from 'shared/Tile';
import { RunStatusBadge } from 'shared/StatusBadge';
import useActiveProject, { projectCrumbs } from 'shared/hooks/useActiveProject';
import useAsync from 'shared/hooks/useAsync';
import useRoutineScope from 'shared/RoutineScope';
import useRunSelection, { SAMPLE } from 'shared/hooks/useRunSelection';
import { setSnackbarError } from 'shared/redux';
import { formatDateTime, formatInteger } from 'utils/format';
import BeforeAfter from '../transactionTypes/shared/BeforeAfter';
import TypeHeader from '../transactionTypes/shared/TypeHeader';
import { referencedColumns } from '../transactionTypes/shared/definition';
import { t } from 'i18n';

const ALL = '*';
const ALL_PAGE_SIZE = 10;
const HOLDER_ROW_LIMIT = 200;

/** Data preview: the source rows of one account holder on top, the rows they become below. */
const DataPreview = () => {
  const { projectId, typeId } = useParams();
  const dispatch = useDispatch();
  const { project } = useActiveProject(projectId);
  const scope = useRoutineScope(projectId, typeId, appRoutes.preview);
  const { type } = scope;
  const selection = useRunSelection(projectId, typeId, type?.version);
  const { runState, runs, useSample, currentRun, datasetId } = selection;
  const [holder, setHolder] = useState(undefined); // undefined = not chosen yet, ALL = everyone, otherwise the holder's key
  const [onlyProblems, setOnlyProblems] = useState(false);
  const [skip, setSkip] = useState(0);
  const [groupVersion, setGroupVersion] = useState(0);
  const [editingGroup, setEditingGroup] = useState(false);
  const [groupForm, setGroupForm] = useState({ holderColumn: '', holderLabelColumn: '' });

  const previewState = useAsync(() => {
    if (!type || !runState.data) return Promise.resolve(null);
    const base = { datasetId: datasetId || null, purpose: useSample ? 'sample' : 'live', filter: 'matched' };
    if (holder === undefined) return transactionTypes.preview(projectId, typeId, { ...base, take: 1 });
    if (holder === ALL) return transactionTypes.preview(projectId, typeId, { ...base, skip, take: ALL_PAGE_SIZE });
    return transactionTypes.preview(projectId, typeId, { ...base, holder, take: HOLDER_ROW_LIMIT });
  }, [projectId, typeId, type?.version, runState.data, datasetId, useSample, holder, skip, groupVersion]);
  const preview = previewState.data;
  const holders = useMemo(() => preview?.holders || [], [preview]);
  const used = useMemo(() => (type?.definition ? referencedColumns(type.definition) : new Set()), [type]);
  const sourceSystem = project?.sourceSystemName || '';
  const targetSystem = project?.targetSystemName || '';
  const hasDefinitionErrors = preview?.definitionIssues?.some((i) => i.severity === 'error');
  const summary = preview?.summary;
  const logicSignedOff = type?.status === 'approved';

  // Start on the first account holder that has a problem (or the first one), so there is always something to look at.
  useEffect(() => {
    if (holder !== undefined || !preview) return;
    if (holders.length === 0) setHolder(ALL);
    else setHolder((holders.find((h) => h.errors > 0) || holders[0]).key);
  }, [preview, holder, holders]);

  const listed = onlyProblems ? holders.filter((h) => h.errors > 0 || h.warnings > 0) : holders;
  const current = holders.find((h) => h.key === holder);

  const chooseData = (value) => {
    selection.choose(value);
    setHolder(undefined);
    setSkip(0);
  };

  const saveGroup = async () => {
    try {
      await transactionTypes.update(projectId, typeId, {
        name: type.name,
        description: type.description,
        dataSourceId: type.dataSourceId,
        holderColumn: groupForm.holderColumn || null,
        holderLabelColumn: groupForm.holderLabelColumn || null,
      });
      setEditingGroup(false);
      setHolder(undefined);
      setGroupVersion((v) => v + 1);
      await scope.reloadType();
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    }
  };

  const approved = Boolean(currentRun?.approvalValid);
  const hasLive = runs.length > 0;
  const steps = [
    { label: 'stepUpload', state: hasLive ? 'done' : 'current' },
    { label: 'stepTransform', state: hasLive && logicSignedOff && !hasDefinitionErrors ? 'done' : (hasLive ? 'current' : '') },
    { label: 'stepReviewShort', state: approved ? 'done' : (hasLive && logicSignedOff ? 'current' : '') },
    { label: 'stepDownload', state: approved ? 'current' : '' },
  ];

  return (
    <LayoutContainer
      heading={t('previewPageHeader')}
      breadcrumbs={projectCrumbs(project, { title: t('previewPageHeader') })}
      wide
    >
      <div className="pr-3">
        {scope.routinesLoaded && scope.routines.length === 0 && (
          <div className="panel">
            <h2>{t('noRoutinesHeader')}</h2>
            <div className="panel-help mb-1">{t('noRoutinesText')}</div>
            <NavLink className="btn btn-primary" to={appRoutes.transactionTypes(projectId)}>{t('goToTransformations')}</NavLink>
          </div>
        )}

        {type && (
          <>
            <TypeHeader projectId={projectId} type={type} routines={scope.routines} onChoose={scope.choose}>
              <NavLink className="btn btn-outline-primary mb-2" to={appRoutes.logic(projectId, typeId)}>{t('editLogic')}</NavLink>
            </TypeHeader>

            <Stepper steps={steps} />

            {runState.data && (
              <div className="panel">
                <div className="d-flex flex-wrap align-items-end">
                  <SelectField className="mr-3 w-auto" label={t('previewData')} value={selection.selectedValue} onChange={chooseData}>
                    {runs.map((r) => (
                      <option key={r.datasetId} value={r.datasetId}>
                        {`${t('purpose_live')} · ${r.datasetLabel} · ${formatDateTime(r.loadedUtc)} · ${formatInteger(r.rows)} ${t('rows').toLowerCase()}`}
                      </option>
                    ))}
                    <option value={SAMPLE}>{t('previewSampleOption')}</option>
                  </SelectField>
                  <div className="mb-3">
                    {currentRun ? <RunStatusBadge run={currentRun} /> : <span className="text-secondary">{t('previewSampleNote')}</span>}
                  </div>
                </div>
                {!hasLive && (
                  <div className="panel-help mb-0">
                    {t('noLiveDataText', { source: sourceSystem })}{' '}
                    {type.dataSourceId && <NavLink to={appRoutes.source(projectId, type.dataSourceId)}>{t('uploadLiveData')}</NavLink>}
                  </div>
                )}
              </div>
            )}

            {preview && preview.truncated && (
              <ul className="issue-list mb-2"><li className="warning">{t('previewTruncated', { count: formatInteger(summary.sourceRows) })}</li></ul>
            )}

            {preview && preview.definitionIssues.length > 0 && (
              <div className="panel">
                <h2>{hasDefinitionErrors ? t('logicNeedsFixing') : t('logicNotes')}</h2>
                <ul className="issue-list">
                  {preview.definitionIssues.map((issue, k) => (
                    <li key={k} className={issue.severity === 'error' ? 'error' : 'warning'}>{`${issue.path}: ${issue.message}`}</li>
                  ))}
                </ul>
              </div>
            )}

            {preview && !hasDefinitionErrors && (
              <>
                <div className="stat-tiles">
                  <Tile value={summary.sourceRows} label={t('tileSourceRows', { system: sourceSystem })} />
                  <Tile value={summary.transformed} label={t('tileTransformed')} tone="ok" />
                  <Tile value={summary.errors} label={t('tileErrors')} tone={summary.errors ? 'bad' : 'ok'} />
                  <Tile value={summary.warnings} label={t('tileWarnings')} tone={summary.warnings ? 'warn' : ''} />
                  <Tile value={summary.skipped} label={t('tileSkipped')} />
                  {preview.outputs.map((o) => (
                    <Tile key={o.id} value={summary.outputRows[o.id] || 0} label={t('tileOutputRows', { name: o.name, system: targetSystem })} />
                  ))}
                </div>

                <div className="panel">
                  <div className="holder-picker">
                    {holders.length > 0 && (
                      <SelectField
                        className="w-auto"
                        label={t('accountHolder')}
                        value={holder ?? ''}
                        onChange={(value) => { setHolder(value); setSkip(0); }}
                        hint={t('accountHolderHint', { count: holders.length })}
                      >
                        <option value={ALL}>{t('allHolders', { count: holders.length })}</option>
                        {listed.map((h) => (
                          <option key={h.key || '(none)'} value={h.key}>
                            {`${h.label} — ${t('holderOptionDetail', { rows: h.sourceRows, errors: h.errors })}`}
                          </option>
                        ))}
                        {current && !listed.includes(current) && <option value={current.key}>{current.label}</option>}
                      </SelectField>
                    )}
                    <CheckField label={t('onlyProblemHolders')} checked={onlyProblems} onChange={setOnlyProblems} className="mb-3" />
                  </div>
                  <div className="group-by">
                    {preview.holderColumn
                      ? t('groupedBy', { column: preview.holderColumn, label: preview.holderLabelColumn || t('notSet') })
                      : t('noHolderColumn')}
                    <button
                      type="button"
                      className="btn btn-link btn-sm"
                      onClick={() => {
                        setGroupForm({ holderColumn: preview.holderColumn || '', holderLabelColumn: preview.holderLabelColumn || '' });
                        setEditingGroup(true);
                      }}
                    >
                      {t('changeButton')}
                    </button>
                  </div>
                  {editingGroup && (
                    <div className="d-flex flex-wrap align-items-end">
                      <SelectField className="mr-2 w-auto" label={t('holderColumn')} value={groupForm.holderColumn} onChange={(v) => setGroupForm((f) => ({ ...f, holderColumn: v }))}>
                        <option value="">{t('detectAutomatically')}</option>
                        {preview.sourceColumns.map((c) => <option key={c} value={c}>{c}</option>)}
                      </SelectField>
                      <SelectField className="mr-2 w-auto" label={t('holderNameColumn')} value={groupForm.holderLabelColumn} onChange={(v) => setGroupForm((f) => ({ ...f, holderLabelColumn: v }))}>
                        <option value="">{t('detectAutomatically')}</option>
                        {preview.sourceColumns.map((c) => <option key={c} value={c}>{c}</option>)}
                      </SelectField>
                      <ActionButton title={t('saveButton')} classes="mr-2" onClickAction={saveGroup} />
                      <ActionButton title={t('cancelButton')} buttonColor="secondary" onClickAction={() => setEditingGroup(false)} />
                    </div>
                  )}
                </div>

                {holder !== undefined && (
                  <>
                    {current && (
                      <p className="holder-summary">
                        <strong>{current.label}</strong>
                        {` · ${t('transactionsCount', { count: current.sourceRows })}`}
                        {current.errors > 0 && <span className="text-danger">{` · ${t('holderErrors', { count: current.errors })}`}</span>}
                      </p>
                    )}
                    <BeforeAfter preview={preview} usedColumns={used} carriedDown={type.definition?.fillDown} sourceSystem={sourceSystem} targetSystem={targetSystem} />
                    {holder === ALL && <Pager skip={skip} take={ALL_PAGE_SIZE} total={preview.totalMatching} onChange={setSkip} />}
                  </>
                )}

                <div className="panel d-flex flex-wrap align-items-center">
                  <span className="mr-auto panel-help mb-0">{t('previewNextStep')}</span>
                  <NavLink className="btn btn-primary" to={appRoutes.reconciliation(projectId, typeId)}>{t('goToReconciliation')}</NavLink>
                </div>
              </>
            )}
          </>
        )}
      </div>
    </LayoutContainer>
  );
};

export default DataPreview;
