import React from 'react';
import { NavLink } from 'react-router-dom';
import { appRoutes } from 'app/routes';
import { SelectField } from 'shared/Form';
import { LogicStatusBadge } from 'shared/StatusBadge';
import { t } from 'i18n';

/**
 * Name, logic status and the views of one transformation routine: logic, data preview, reconciliation, change log.
 * Pass `routines` and `onChoose` on the project-level pages to let the reader switch to another routine.
 */
const TypeHeader = ({ projectId, type, routines, onChoose, children }) => (
  <>
    <div className="panel pb-2">
      <div className="d-flex flex-wrap align-items-start">
        <div className="mr-auto">
          <h2>{type.name} <LogicStatusBadge status={type.status} /></h2>
          <div className="panel-help mb-1">{type.description || t('noDescription')}</div>
          <div className="text-secondary">{`${t('dataSource')}: ${type.dataSourceName || t('notSet')} · ${t('versionLine', { version: type.version })}`}</div>
        </div>
        {routines && routines.length > 1 && (
          <SelectField className="w-auto mr-3" label={t('transformationRoutine')} value={type.id} onChange={onChoose}>
            {routines.map((r) => <option key={r.id} value={r.id}>{r.name}</option>)}
          </SelectField>
        )}
        {children}
      </div>
    </div>
    <nav className="type-tabs" aria-label={t('routineViews')}>
      <NavLink end to={appRoutes.logic(projectId, type.id)}>{t('tabLogic')}</NavLink>
      <NavLink to={appRoutes.preview(projectId, type.id)}>{t('tabPreview')}</NavLink>
      <NavLink to={appRoutes.reconciliation(projectId, type.id)}>{t('tabReconciliation')}</NavLink>
      <NavLink to={appRoutes.changeLog(projectId, type.id)}>{t('tabChangeLog')}</NavLink>
    </nav>
  </>
);

export default TypeHeader;
