import React, { useRef, useState } from 'react';
import { useDispatch } from 'react-redux';
import { useNavigate, useParams } from 'react-router-dom';
import { datasets, sources } from 'api';
import { errorMessage } from 'api/client';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import ConfirmModal from 'shared/ConfirmModal';
import DataTable, { Pager } from 'shared/DataTable';
import { SelectField, TextField } from 'shared/Form';
import useActiveProject, { projectCrumbs } from 'shared/hooks/useActiveProject';
import useAsync from 'shared/hooks/useAsync';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import { displayValue, formatDateTime, formatInteger } from 'utils/format';
import FileLayoutEditor from './FileLayoutEditor';
import SourceModal from './SourceModal';
import { t } from 'i18n';

const PAGE_SIZE = 50;

const DataGrid = ({ projectId, datasetId, columns }) => {
  const [skip, setSkip] = useState(0);
  const { data } = useAsync(() => datasets.rows(projectId, datasetId, skip, PAGE_SIZE), [projectId, datasetId, skip]);
  const rows = data?.rows || [];

  return (
    <>
      <DataTable
        dense
        caption={t('asIsData')}
        rows={rows}
        rowKey={(row, index) => skip + index}
        columns={[
          { key: '#', header: '#', className: 'row-index', render: (row, index) => skip + index + 1 },
          ...columns.map((name, c) => ({ key: name, header: name, render: (row) => displayValue(row[c]) })),
        ]}
      />
      <Pager skip={skip} take={PAGE_SIZE} total={data?.dataset?.rowCount || 0} onChange={setSkip} />
    </>
  );
};

const SourceDetail = () => {
  const { projectId, sourceId } = useParams();
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const fileInput = useRef(null);
  const { project } = useActiveProject(projectId);
  const sourceState = useAsync(() => sources.get(projectId, sourceId), [projectId, sourceId]);
  const datasetState = useAsync(() => sources.datasets(projectId, sourceId), [projectId, sourceId]);
  const [editing, setEditing] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [busy, setBusy] = useState(false);
  const [chosenId, setChosenId] = useState(null);
  const [sheet, setSheet] = useState('');
  const [sheets, setSheets] = useState([]);
  const [headerRow, setHeaderRow] = useState('');
  const [lastFile, setLastFile] = useState(null);
  const [purpose, setPurpose] = useState('live');

  const source = sourceState.data;
  const datasetList = datasetState.data || [];
  const current = datasetList.find((d) => d.id === chosenId) || datasetList[0];

  const refresh = async () => {
    setChosenId(null);
    await Promise.all([sourceState.reload(), datasetState.reload()]);
  };

  const run = async (action, successMessage) => {
    setBusy(true);
    try {
      const result = await action();
      dispatch(setSnackbarSuccess(successMessage(result)));
      await refresh();
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    } finally {
      setBusy(false);
    }
  };

  const upload = (file, chosenSheet) => run(async () => {
    const result = await sources.upload(projectId, sourceId, file, { sheet: chosenSheet || undefined, headerRow: headerRow || undefined, purpose });
    setSheets(result.sheets);
    setSheet(result.dataset.sheet || '');
    return result;
  }, (result) => t('uploadDone', { count: formatInteger(result.dataset.rowCount) }));

  const onFileChosen = (event) => {
    const file = event.target.files[0];
    event.target.value = '';
    if (!file) return;
    setLastFile(file);
    setSheets([]);
    upload(file, '');
  };

  const remove = async () => {
    setBusy(true);
    try {
      await sources.remove(projectId, sourceId);
      dispatch(setSnackbarSuccess(t('sourceDeleted')));
      navigate(appRoutes.sources(projectId));
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
      setConfirmDelete(false);
      setBusy(false);
    }
  };

  const isApi = source?.kind === 'api';

  return (
    <LayoutContainer
      heading={source?.name || t('sourcesPageHeader')}
      breadcrumbs={projectCrumbs(project, { title: t('sourcesPageHeader'), to: appRoutes.sources(projectId) }, { title: source?.name || '' })}
      wide
    >
      {source && (
        <div className="pr-3">
          <div className="panel">
            <div className="d-flex flex-wrap align-items-start">
              <div className="mr-auto">
                <h2>{isApi ? t('kindApi') : t('kindUpload')}</h2>
                <div className="panel-help mb-0">{source.description || t('noDescription')}</div>
                {isApi && <div className="mono">{`${source.apiConfig.method} ${source.apiConfig.baseUrl}${source.apiConfig.path || ''}`}</div>}
              </div>
              <div>
                <ActionButton title={t('editButton')} classes="mr-2" onClickAction={() => setEditing(true)} />
                <ActionButton title={t('deleteButton')} buttonColor="danger" onClickAction={() => setConfirmDelete(true)} />
              </div>
            </div>
          </div>

          <div className="panel">
            <h2>{isApi ? t('extractHeader') : t('uploadHeader')}</h2>
            <div className="panel-help">{isApi ? t('extractHelp', { source: project?.sourceSystemName || '' }) : t('uploadHelp')}</div>
            <fieldset className="purpose-choice">
              <legend>{t('loadAs')}</legend>
              <label>
                <input type="radio" name="purpose" value="live" checked={purpose === 'live'} onChange={() => setPurpose('live')} />
                <span><strong>{t('purposeLiveTitle')}</strong>{t('purposeLiveText')}</span>
              </label>
              <label>
                <input type="radio" name="purpose" value="sample" checked={purpose === 'sample'} onChange={() => setPurpose('sample')} />
                <span><strong>{t('purposeSampleTitle')}</strong>{t('purposeSampleText')}</span>
              </label>
            </fieldset>
            {isApi ? (
              <ActionButton
                title={t('extractNow')}
                outline={false}
                disabled={busy}
                onClickAction={() => run(() => sources.extract(projectId, sourceId, purpose), (d) => t('extractDone', { count: formatInteger(d.rowCount) }))}
              />
            ) : (
              <div className="d-flex flex-wrap align-items-end">
                <TextField className="mr-2" label={t('headerRow')} type="number" min={1} value={headerRow} onChange={setHeaderRow} style={{ maxWidth: '7rem' }} placeholder={String(source.layout?.headerRow || 1)} hint={t('headerRowUploadHint')} />
                <div>
                  <input ref={fileInput} type="file" accept=".xlsx,.xls,.csv,.txt" className="d-none" onChange={onFileChosen} aria-label={t('chooseFile')} />
                  <ActionButton title={t('chooseFile')} outline={false} disabled={busy} onClickAction={() => fileInput.current.click()} />
                </div>
                {sheets.length > 1 && lastFile && (
                  <SelectField
                    className="ml-3"
                    label={t('sheet')}
                    value={sheet}
                    onChange={(value) => { setSheet(value); upload(lastFile, value); }}
                    hint={t('sheetHint')}
                  >
                    {sheets.map((name) => <option key={name} value={name}>{name}</option>)}
                  </SelectField>
                )}
              </div>
            )}
          </div>

          <FileLayoutEditor projectId={projectId} source={source} loadedColumns={current?.columns} onSaved={refresh} />

          <div className="panel">
            <div className="d-flex flex-wrap align-items-center">
              <h2 className="mr-auto">{t('asIsData')}</h2>
              {datasetList.length > 1 && (
                <SelectField className="w-auto" aria-label={t('loadedData')} value={current?.id || ''} onChange={setChosenId}>
                  {datasetList.map((d) => <option key={d.id} value={d.id}>{`${t(`purpose_${d.purpose}`)} · ${d.label} · ${formatDateTime(d.createdUtc)} · ${formatInteger(d.rowCount)}`}</option>)}
                </SelectField>
              )}
            </div>
            {current ? (
              <>
                <div className="panel-help">
                  {t('datasetSummary', { purpose: t(`purpose_${current.purpose}`), label: current.label, rows: formatInteger(current.rowCount), when: formatDateTime(current.createdUtc), by: current.createdBy || '' })}
                </div>
                {current.warnings.length > 0 && (
                  <ul className="issue-list mb-2">
                    {current.warnings.map((w) => <li key={w} className="warning">{w}</li>)}
                  </ul>
                )}
                <DataGrid key={current.id} projectId={projectId} datasetId={current.id} columns={current.columns} />
              </>
            ) : (
              <div className="panel-help">{t('noDataYet')}</div>
            )}
          </div>
        </div>
      )}
      {editing && source && (
        <SourceModal projectId={projectId} source={source} onClose={() => setEditing(false)} onSaved={() => { setEditing(false); refresh(); }} />
      )}
      <ConfirmModal
        open={confirmDelete}
        danger
        busy={busy}
        title={t('deleteSourceHeader')}
        message={t('deleteSourceMessage', { name: source?.name })}
        confirmLabel={t('deleteButton')}
        onConfirm={remove}
        onCancel={() => setConfirmDelete(false)}
      />
    </LayoutContainer>
  );
};

export default SourceDetail;
