import { setToken } from 'auth/tokenStore';

const SIGNED_IN = 'account/SIGNED_IN';
const SIGNED_OUT = 'account/SIGNED_OUT';
const SET_ACTIVE_PROJECT = 'account/SET_ACTIVE_PROJECT';

export const signedIn = (response) => {
  setToken(response.token);
  return { type: SIGNED_IN, payload: response.user };
};

export const signOut = () => {
  setToken(null);
  return { type: SIGNED_OUT };
};

export const setActiveProject = (project) => ({ type: SET_ACTIVE_PROJECT, payload: project });

const initialState = {
  isLoggedIn: false,
  loginUser: null,
  activeProject: null,
};

const reducer = (state = initialState, action) => {
  switch (action.type) {
    case SIGNED_IN:
      return { ...initialState, isLoggedIn: true, loginUser: action.payload };
    case SIGNED_OUT:
      return initialState;
    case SET_ACTIVE_PROJECT:
      return { ...state, activeProject: action.payload };
    default:
      return state;
  }
};

export default reducer;
