import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { NavLink, useNavigate, useParams } from 'react-router-dom';
import { sources, transactionTypes } from 'api';
import { errorMessage } from 'api/client';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import ConfirmModal from 'shared/ConfirmModal';
import DataTable from 'shared/DataTable';
import { LogicStatusBadge, RunStatusBadge } from 'shared/StatusBadge';
import useActiveProject, { projectCrumbs } from 'shared/hooks/useActiveProject';
import useAsync from 'shared/hooks/useAsync';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import { formatDateTime } from 'utils/format';
import TransactionTypeModal from './TransactionTypeModal';
import { t } from 'i18n';

const TransactionTypes = () => {
  const { projectId } = useParams();
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { project } = useActiveProject(projectId);
  const typeState = useAsync(() => transactionTypes.list(projectId), [projectId]);
  const sourceState = useAsync(() => sources.list(projectId), [projectId]);
  const [adding, setAdding] = useState(false);
  const [deleting, setDeleting] = useState(null);
  const sourceList = sourceState.data || [];
  const types = typeState.data || [];

  const remove = async () => {
    try {
      await transactionTypes.remove(projectId, deleting.id);
      dispatch(setSnackbarSuccess(t('transactionTypeDeleted')));
      setDeleting(null);
      typeState.reload();
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    }
  };

  return (
    <LayoutContainer
      heading={t('transactionTypesPageHeader')}
      breadcrumbs={projectCrumbs(project, { title: t('transactionTypesPageHeader') })}
    >
      <div className="pr-3">
        <p className="text-secondary">{t('transactionTypesIntro', { source: project?.sourceSystemName || '', target: project?.targetSystemName || '' })}</p>
        {sourceList.length === 0 && !sourceState.loading && (
          <p className="text-secondary">
            {t('addSourceFirst')} <NavLink to={appRoutes.sources(projectId)}>{t('sourcesPageHeader')}</NavLink>
          </p>
        )}
        <ActionButton title={t('addButton')} disabled={sourceList.length === 0} onClickAction={() => setAdding(true)} />
        <DataTable
          caption={t('transactionTypesPageHeader')}
          rows={types}
          rowKey={(row) => row.id}
          emptyText={t('noTransactionTypes')}
          onRowClick={(row) => navigate(appRoutes.logic(projectId, row.id))}
          columns={[
            { key: 'name', header: t('transactionTypeName') },
            { key: 'description', header: t('sourceDescription') },
            { key: 'dataSourceName', header: t('dataSource'), render: (x) => x.dataSourceName || t('notSet') },
            { key: 'outputCount', header: t('targetRows'), className: 'num' },
            { key: 'version', header: t('version'), className: 'num' },
            { key: 'status', header: t('logicStatus'), render: (x) => <LogicStatusBadge status={x.status} /> },
            { key: 'run', header: t('liveDataStatus'), render: (x) => <RunStatusBadge run={x.latestRun} /> },
            { key: 'updatedUtc', header: t('lastUpdated'), render: (x) => formatDateTime(x.updatedUtc) },
            {
              key: 'actions',
              header: '',
              render: (x) => (
                <>
                  <NavLink className="mr-3" to={appRoutes.preview(projectId, x.id)} onClick={(e) => e.stopPropagation()}>{t('tabPreview')}</NavLink>
                  <button type="button" className="btn btn-link btn-sm p-0" onClick={(e) => { e.stopPropagation(); setDeleting(x); }}>{t('deleteButton')}</button>
                </>
              ),
            },
          ]}
        />
      </div>
      {adding && (
        <TransactionTypeModal
          projectId={projectId}
          sources={sourceList}
          onClose={() => setAdding(false)}
          onSaved={(saved) => navigate(appRoutes.logic(projectId, saved.id))}
        />
      )}
      <ConfirmModal
        open={Boolean(deleting)}
        danger
        title={t('deleteTransactionTypeHeader')}
        message={t('deleteTransactionTypeMessage', { name: deleting?.name })}
        confirmLabel={t('deleteButton')}
        onConfirm={remove}
        onCancel={() => setDeleting(null)}
      />
    </LayoutContainer>
  );
};

export default TransactionTypes;
