import React, { useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { sources } from 'api';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import DataTable from 'shared/DataTable';
import useActiveProject, { projectCrumbs } from 'shared/hooks/useActiveProject';
import useAsync from 'shared/hooks/useAsync';
import { formatDateTime, formatInteger } from 'utils/format';
import SourceModal from './SourceModal';
import { t } from 'i18n';

const Sources = () => {
  const { projectId } = useParams();
  const navigate = useNavigate();
  const { project } = useActiveProject(projectId);
  const { data } = useAsync(() => sources.list(projectId), [projectId]);
  const [adding, setAdding] = useState(false);

  return (
    <LayoutContainer
      heading={t('sourcesPageHeader')}
      breadcrumbs={projectCrumbs(project, { title: t('sourcesPageHeader') })}
    >
      <div className="pr-3">
        <p className="text-secondary">{t('sourcesIntro', { source: project?.sourceSystemName || '' })}</p>
        <ActionButton title={t('addButton')} onClickAction={() => setAdding(true)} />
        <DataTable
          caption={t('sourcesPageHeader')}
          rows={data || []}
          rowKey={(row) => row.id}
          emptyText={t('noSources')}
          onRowClick={(row) => navigate(appRoutes.source(projectId, row.id))}
          columns={[
            { key: 'name', header: t('sourceName') },
            { key: 'kind', header: t('sourceKind'), render: (s) => (s.kind === 'api' ? t('kindApi') : t('kindUpload')) },
            { key: 'expected', header: t('expectedLayout'), className: 'num', render: (s) => (s.expectedColumns.length ? t('columnsCount', { count: s.expectedColumns.length }) : t('notSet')) },
            { key: 'sample', header: t('sampleData'), render: (s) => (s.latestSample ? `${s.latestSample.label} (${formatInteger(s.latestSample.rowCount)})` : t('noneLoaded')) },
            { key: 'live', header: t('liveData'), render: (s) => (s.latestLive ? `${s.latestLive.label} (${formatInteger(s.latestLive.rowCount)}) · ${formatDateTime(s.latestLive.createdUtc)}` : t('noneLoaded')) },
          ]}
        />
      </div>
      {adding && (
        <SourceModal
          projectId={projectId}
          onClose={() => setAdding(false)}
          onSaved={(saved) => navigate(appRoutes.source(projectId, saved.id))}
        />
      )}
    </LayoutContainer>
  );
};

export default Sources;
