import React from 'react';
import { useSelector } from 'react-redux';
import { projects } from 'api';
import LayoutContainer from 'shared/LayoutContainer';
import MenuCard from 'shared/Cards/menuCard';
import useAsync from 'shared/hooks/useAsync';
import { appRoutes } from 'app/routes';
import { t } from 'i18n';

const Home = () => {
  const { loginUser } = useSelector(({ account }) => account);
  const { data } = useAsync(() => projects.list(), []);
  const list = data || [];

  return (
    <LayoutContainer heading={t('homePageHeader')}>
      <div id="home-config" className="home-section">
        <div className="home-title">{t('configurationHeader')}</div>
        <div className="home-grid">
          <MenuCard menuIcon="fileUploadIcon" header={t('dataSourcesPageHeader')} description={t('homeDataSources')} navigateTo={appRoutes.configSources} />
          <MenuCard menuIcon="batchJobIcon" header={t('transformationsPageHeader')} description={t('homeTransformations')} navigateTo={appRoutes.configTransformations} />
          <MenuCard menuIcon="fileIcon" header={t('lookupsPageHeader')} description={t('homeLookups')} navigateTo={appRoutes.configLookups} />
        </div>
      </div>
      <div id="home-projects" className="home-section">
        <div className="home-title">{t('projectsPageHeader')}</div>
        <div className="home-grid">
          <MenuCard menuIcon="clientIcon" header={t('allProjects')} description={t('homeAllProjects')} navigateTo={appRoutes.projects} />
          {list.slice(0, 11).map((project) => (
            <MenuCard key={project.id} menuIcon="buildingRegularIcon" header={project.name} description={`${project.sourceSystemName} → ${project.targetSystemName}`} navigateTo={appRoutes.project(project.id)} />
          ))}
        </div>
      </div>
      {loginUser?.isAdministrator && (
      <div id="home-admin" className="home-section">
        <div className="home-title">{t('usersPageHeader')}</div>
        <div className="home-grid">
          <MenuCard menuIcon="usersIcon" header={t('usersPageHeader')} description={t('homeUsers')} navigateTo={appRoutes.users} />
        </div>
      </div>
      )}
    </LayoutContainer>
  );
};

export default Home;
