import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { valueMaps } from 'api';
import { errorMessage } from 'api/client';
import ModalContainer from 'shared/ModalContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import { TextAreaField, TextField } from 'shared/Form';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import { formatEntries, parseEntries } from './entries';
import { t } from 'i18n';

const ValueMapModal = ({ projectId, map, sourceSystem, targetSystem, onClose, onSaved }) => {
  const dispatch = useDispatch();
  const [name, setName] = useState(map?.name || '');
  const [description, setDescription] = useState(map?.description || '');
  const [text, setText] = useState(formatEntries(map?.entries));
  const [errors, setErrors] = useState({});
  const [busy, setBusy] = useState(false);

  const { entries, duplicates } = parseEntries(text);

  const save = async () => {
    const found = {};
    if (!name.trim()) found.name = t('requiredField');
    if (duplicates.length) found.entries = t('valueMapDuplicates', { keys: duplicates.slice(0, 5).join(', ') });
    setErrors(found);
    if (Object.keys(found).length) return;

    setBusy(true);
    try {
      const body = { name: name.trim(), description: description.trim() || null, entries };
      if (map?.id) await valueMaps.update(projectId, map.id, body);
      else await valueMaps.create(projectId, body);
      dispatch(setSnackbarSuccess(t('valueMapSaved')));
      onSaved();
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    } finally {
      setBusy(false);
    }
  };

  return (
    <ModalContainer
      modal
      toggleModal={onClose}
      header={map?.id ? t('editValueMapHeader') : t('addValueMapHeader')}
      subHeader={t('valueMapModalIntro')}
      modalFooterContent={(
        <>
          <ActionButton title={t('cancelButton')} buttonColor="secondary" classes="mb-0" onClickAction={onClose} />
          <ActionButton title={t('saveButton')} outline={false} classes="mb-0" disabled={busy} onClickAction={save} />
        </>
      )}
    >
      <TextField label={t('valueMapName')} placeholder="Currencies" value={name} onChange={setName} error={errors.name} hint={t('valueMapNameHint')} required autoFocus />
      <TextField label={t('sourceDescription')} value={description} onChange={setDescription} />
      <TextAreaField
        label={t('valueMapEntries', { source: sourceSystem, target: targetSystem })}
        rows={10}
        className="mono"
        value={text}
        onChange={setText}
        error={errors.entries}
        placeholder={'GBP\tGBP\nEURO\tEUR'}
        hint={t('valueMapEntriesHint', { count: entries.length })}
      />
    </ModalContainer>
  );
};

export default ValueMapModal;
