import { useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { projects } from 'api';
import { setActiveProject } from 'shared/account';
import useAsync from './useAsync';
import { t } from 'i18n';
import { appRoutes } from 'app/routes';

/** Loads the project in the URL and makes it the active project (side menu and header follow it). */
const useActiveProject = (projectId) => {
  const dispatch = useDispatch();
  const state = useAsync(() => projects.get(projectId), [projectId]);

  useEffect(() => {
    if (state.data) dispatch(setActiveProject({ id: state.data.id, name: state.data.name }));
  }, [state.data, dispatch]);

  return { ...state, project: state.data };
};

/** Breadcrumb trail down to a project, followed by any extra items. */
export const projectCrumbs = (project, ...extra) => {
  const trail = [
    { title: t('homePageHeader'), isActive: false, to: appRoutes.home },
    { title: t('projectsPageHeader'), isActive: false, to: appRoutes.projects },
  ];
  if (project) trail.push({ title: project.name, isActive: extra.length === 0, to: appRoutes.project(project.id) });
  extra.forEach((item, index) => trail.push({ ...item, isActive: index === extra.length - 1 }));
  return trail;
};

export default useActiveProject;
