import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { NavLink, useNavigate, useParams } from 'react-router-dom';
import { projects, projectExport, sources, transactionTypes } from 'api';
import { blobErrorMessage, errorMessage } from 'api/client';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import ConfirmModal from 'shared/ConfirmModal';
import DataTable from 'shared/DataTable';
import { LogicStatusBadge, RunStatusBadge } from 'shared/StatusBadge';
import useActiveProject, { projectCrumbs } from 'shared/hooks/useActiveProject';
import useAsync from 'shared/hooks/useAsync';
import { setActiveProject } from 'shared/account';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import { saveBlob } from 'utils/download';
import { formatDate, formatDateTime } from 'utils/format';
import MembersPanel from './MembersPanel';
import ProjectModal from './ProjectModal';
import useProjectRole from 'shared/hooks/useProjectRole';
import { t } from 'i18n';

const daysAway = (isoDate) => {
  const days = Math.round((new Date(`${isoDate}T00:00:00`) - new Date(new Date().toDateString())) / 86400000);
  if (days === 0) return t('migrationToday');
  return days > 0 ? t('daysToGo', { count: days }) : t('daysAgo', { count: -days });
};

const ProjectOverview = () => {
  const { projectId } = useParams();
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { project, reload } = useActiveProject(projectId);
  const access = useProjectRole(project);
  const sourceState = useAsync(() => sources.list(projectId), [projectId]);
  const typeState = useAsync(() => transactionTypes.list(projectId), [projectId]);
  const [editing, setEditing] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [busy, setBusy] = useState(false);

  const sourceList = sourceState.data || [];
  const typeList = typeState.data || [];
  const withLayout = sourceList.filter((s) => s.layout?.columns?.length > 0 || s.latestDataset).length;
  const signedOff = typeList.filter((x) => x.status === 'approved').length;
  const withLive = sourceList.filter((s) => s.latestLive).length;
  const dataApproved = typeList.filter((x) => x.latestRun?.approvalValid).length;
  const allApproved = typeList.length > 0 && dataApproved === typeList.length;

  const download = async () => {
    try {
      saveBlob(await projectExport(projectId), 'migration.xlsx');
    } catch (e) {
      dispatch(setSnackbarError(await blobErrorMessage(e)));
    }
  };

  const toggleArchive = async () => {
    try {
      await projects.archive(projectId, !project.archived);
      dispatch(setSnackbarSuccess(project.archived ? t('projectRestored') : t('projectArchived')));
      reload();
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    }
  };

  const remove = async () => {
    setBusy(true);
    try {
      await projects.remove(projectId);
      dispatch(setActiveProject(null));
      dispatch(setSnackbarSuccess(t('projectDeleted')));
      navigate(appRoutes.projects);
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
      setBusy(false);
    }
  };

  return (
    <LayoutContainer heading={project?.name || t('projectOverviewPageHeader')} breadcrumbs={projectCrumbs(project)}>
      {project && (
        <div className="pr-3">
          <div className="panel">
            <div className="d-flex flex-wrap align-items-start">
              <div className="mr-auto">
                <h2>{`${project.sourceSystemName} → ${project.targetSystemName}`}</h2>
                <div className="panel-help mb-0">{project.description || t('noDescription')}</div>
                <div className="text-secondary">{`${t('lastUpdated')}: ${formatDateTime(project.updatedUtc)} · ${t('yourRole', { role: t(`role_${project.myRole}`) })}`}</div>
              </div>
              <div>
                {access.canEdit && <ActionButton title={t('editButton')} classes="mr-2" onClickAction={() => setEditing(true)} />}
                {access.isAdministrator && <ActionButton title={project.archived ? t('restoreButton') : t('archiveButton')} buttonColor="secondary" classes="mr-2" onClickAction={toggleArchive} />}
                {access.isAdministrator && <ActionButton title={t('deleteButton')} buttonColor="danger" onClickAction={() => setConfirmDelete(true)} />}
              </div>
            </div>
          </div>

          <div className="panel">
            <h2>{t('governanceHeader')}</h2>
            <div className="panel-help">{t('governanceHelp')}</div>
            <dl className="governance-grid mb-0">
              {[
                ['projectManager', project.projectManager, project.projectManagerContact],
                ['logicBuilder', project.logicBuilder],
                ['signOffOwner', project.signOffOwner, project.signOffContact],
                ['clientContact', project.clientContact],
              ].map(([label, value, contact]) => (
                <div key={label}>
                  <dt>{t(label)}</dt>
                  <dd>{value || <span className="text-secondary">{t('notSetYet')}</span>}{contact && <div className="text-secondary">{contact}</div>}</dd>
                </div>
              ))}
              <div>
                <dt>{t('migrationDate')}</dt>
                <dd>
                  {project.migrationDate ? formatDate(project.migrationDate) : <span className="text-secondary">{t('notSetYet')}</span>}
                  {project.migrationDate && <div className="text-secondary">{daysAway(project.migrationDate)}</div>}
                </dd>
              </div>
              {project.governanceNotes && <div style={{ gridColumn: '1 / -1' }}><dt>{t('governanceNotes')}</dt><dd>{project.governanceNotes}</dd></div>}
            </dl>
          </div>

          {access.isAdministrator && <MembersPanel projectId={projectId} />}

          <div className="phase-label">{t('phaseOneLabel')}</div>
          <div className="steps">
            <div className={`step ${withLayout > 0 ? 'done' : ''}`}>
              <div className="step-number">{t('stepNumber', { number: 1 })}</div>
              <div className="step-title">{t('stepSources')}</div>
              <div className="step-detail">{t('stepSourcesDetail', { count: sourceList.length, withLayout })}</div>
              <NavLink className="btn btn-outline-primary btn-sm" to={appRoutes.sources(projectId)}>{t('openButton')}</NavLink>
            </div>
            <div className={`step ${typeList.length > 0 ? 'done' : ''}`}>
              <div className="step-number">{t('stepNumber', { number: 2 })}</div>
              <div className="step-title">{t('stepMapLogic')}</div>
              <div className="step-detail">{t('stepMapLogicDetail', { count: typeList.length })}</div>
              <NavLink className="btn btn-outline-primary btn-sm" to={appRoutes.transactionTypes(projectId)}>{t('openButton')}</NavLink>
            </div>
            <div className={`step ${typeList.length > 0 && signedOff === typeList.length ? 'done' : ''}`}>
              <div className="step-number">{t('stepNumber', { number: 3 })}</div>
              <div className="step-title">{t('stepSignOff')}</div>
              <div className="step-detail">{t('stepSignOffDetail', { signedOff, count: typeList.length })}</div>
            </div>
          </div>

          <div className="phase-label">{t('phaseTwoLabel')}</div>
          <div className="steps">
            <div className={`step ${withLive > 0 ? 'done' : ''}`}>
              <div className="step-number">{t('stepNumber', { number: 4 })}</div>
              <div className="step-title">{t('stepUpload')}</div>
              <div className="step-detail">{t('stepUploadDetail', { withLive, count: sourceList.length })}</div>
              <NavLink className="btn btn-outline-primary btn-sm" to={appRoutes.preview(projectId)}>{t('openButton')}</NavLink>
            </div>
            <div className={`step ${dataApproved > 0 ? 'done' : ''}`}>
              <div className="step-number">{t('stepNumber', { number: 5 })}</div>
              <div className="step-title">{t('stepTransformReview')}</div>
              <div className="step-detail">{t('stepTransformReviewDetail', { approved: dataApproved, count: typeList.length })}</div>
              <NavLink className="btn btn-outline-primary btn-sm" to={appRoutes.reconciliation(projectId)}>{t('openButton')}</NavLink>
            </div>
            <div className={`step ${allApproved ? 'done' : ''}`}>
              <div className="step-number">{t('stepNumber', { number: 6 })}</div>
              <div className="step-title">{t('stepExport')}</div>
              <div className="step-detail">{t('stepExportDetail')}</div>
              <NavLink className="btn btn-outline-primary btn-sm mr-2" to={appRoutes.output(projectId)}>{t('openButton')}</NavLink>
              <ActionButton title={t('downloadPack')} classes="btn-sm mb-0" disabled={!allApproved} onClickAction={download} />
            </div>
          </div>

          <div className="section-label">{t('transactionTypesPageHeader')}</div>
          <DataTable
            caption={t('transactionTypesPageHeader')}
            rows={typeList}
            rowKey={(row) => row.id}
            emptyText={t('noTransactionTypes')}
            columns={[
              { key: 'name', header: t('transactionTypeName'), render: (x) => <NavLink to={appRoutes.logic(projectId, x.id)}>{x.name}</NavLink> },
              { key: 'dataSourceName', header: t('dataSource'), render: (x) => x.dataSourceName || t('notSet') },
              { key: 'outputCount', header: t('targetRows'), className: 'num' },
              { key: 'version', header: t('version'), className: 'num' },
              { key: 'status', header: t('logicStatus'), render: (x) => <LogicStatusBadge status={x.status} /> },
              { key: 'run', header: t('liveDataStatus'), render: (x) => <RunStatusBadge run={x.latestRun} /> },
              {
                key: 'actions',
                header: '',
                render: (x) => (
                  <>
                    <NavLink className="mr-3" to={appRoutes.logic(projectId, x.id)}>{t('editLogic')}</NavLink>
                    <NavLink to={appRoutes.preview(projectId, x.id)}>{t('tabPreview')}</NavLink>
                  </>
                ),
              },
            ]}
          />
        </div>
      )}
      {editing && <ProjectModal project={project} onClose={() => setEditing(false)} onSaved={() => { setEditing(false); reload(); }} />}
      <ConfirmModal
        open={confirmDelete}
        danger
        busy={busy}
        title={t('deleteProjectHeader')}
        message={t('deleteProjectMessage', { name: project?.name })}
        confirmLabel={t('deleteButton')}
        onConfirm={remove}
        onCancel={() => setConfirmDelete(false)}
      />
    </LayoutContainer>
  );
};

export default ProjectOverview;
