import React from 'react';
import { formatInteger } from 'utils/format';
import { t } from 'i18n';

export const Tile = ({ value, label, tone = '' }) => (
  <div className={`stat-tile ${tone}`}>
    <div className="value">{typeof value === 'number' ? formatInteger(value) : value}</div>
    <div className="label">{label}</div>
  </div>
);

/** The migration process as a row of numbered steps. steps: [{ label (translation key), state: 'done' | 'current' | '' }] */
export const Stepper = ({ steps }) => (
  <ol className="stepper" aria-label={t('processSteps')}>
    {steps.map((step, index) => (
      <li key={step.label} className={step.state} aria-current={step.state === 'current' ? 'step' : undefined}>
        <span className="number">{step.state === 'done' ? '✓' : index + 1}</span>
        {t(step.label)}
      </li>
    ))}
  </ol>
);
