import { useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { signOut } from 'shared/account';
import { setSnackbarError } from 'shared/redux';
import config from 'core/config';
import { t } from 'i18n';

const EVENTS = ['click', 'keydown', 'mousemove', 'scroll'];

/** Signs the user out after a period without activity. Finance data should not stay open on an unattended screen. */
const useInactivityLogout = (active) => {
  const dispatch = useDispatch();

  useEffect(() => {
    if (!active) return undefined;

    let timer;
    const reset = () => {
      clearTimeout(timer);
      timer = setTimeout(() => {
        dispatch(signOut());
        dispatch(setSnackbarError(t('signedOutInactive')));
      }, config.inactivityMinutes * 60 * 1000);
    };

    reset();
    EVENTS.forEach((name) => window.addEventListener(name, reset, { passive: true }));
    return () => {
      clearTimeout(timer);
      EVENTS.forEach((name) => window.removeEventListener(name, reset));
    };
  }, [active, dispatch]);
};

export default useInactivityLogout;
