import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { projectMembers, users } from 'api';
import { errorMessage } from 'api/client';
import ActionButton from 'shared/Buttons/ActionButton';
import DataTable from 'shared/DataTable';
import { SelectField } from 'shared/Form';
import useAsync from 'shared/hooks/useAsync';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import { t } from 'i18n';

const ROLES = ['viewer', 'editor', 'approver'];

/** Who may work on this project, and in which role. Administrators see every project, so they are not listed. */
const MembersPanel = ({ projectId }) => {
  const dispatch = useDispatch();
  const memberState = useAsync(() => projectMembers.list(projectId), [projectId]);
  const userState = useAsync(() => users.list(), []);
  const [userId, setUserId] = useState('');
  const [role, setRole] = useState('editor');
  const members = memberState.data || [];
  const candidates = (userState.data || []).filter((u) => u.isActive && !u.isAdministrator && !members.some((m) => m.userId === u.id));

  const run = async (action, message) => {
    try {
      await action();
      dispatch(setSnackbarSuccess(t(message)));
      await memberState.reload();
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    }
  };

  return (
    <div className="panel">
      <h2>{t('membersHeader')}</h2>
      <div className="panel-help">{t('membersHelp')}</div>
      <DataTable
        dense
        caption={t('membersHeader')}
        rows={members}
        rowKey={(m) => m.userId}
        emptyText={t('noMembers')}
        columns={[
          { key: 'name', header: t('userName') },
          { key: 'email', header: t('loginEmailAddress') },
          {
            key: 'role',
            header: t('memberRole'),
            render: (m) => (
              <select
                className="form-control form-control-sm"
                style={{ maxWidth: '10rem' }}
                aria-label={t('memberRole')}
                value={m.role}
                onChange={(e) => run(() => projectMembers.set(projectId, { userId: m.userId, role: e.target.value }), 'memberSaved')}
              >
                {ROLES.map((r) => <option key={r} value={r}>{t(`role_${r}`)}</option>)}
              </select>
            ),
          },
          { key: 'remove', header: '', render: (m) => <button type="button" className="btn btn-link btn-sm p-0" onClick={() => run(() => projectMembers.remove(projectId, m.userId), 'memberRemoved')}>{t('removeButton')}</button> },
        ]}
      />
      <div className="d-flex flex-wrap align-items-end mt-3">
        <SelectField className="mr-2 w-auto" label={t('addMember')} value={userId} onChange={setUserId}>
          <option value="">{t('chooseUser')}</option>
          {candidates.map((u) => <option key={u.id} value={u.id}>{`${u.name} (${u.email})`}</option>)}
        </SelectField>
        <SelectField className="mr-2 w-auto" label={t('memberRole')} value={role} onChange={setRole}>
          {ROLES.map((r) => <option key={r} value={r}>{t(`role_${r}`)}</option>)}
        </SelectField>
        <ActionButton
          title={t('addButton')}
          classes="mb-3"
          disabled={!userId}
          onClickAction={() => run(async () => { await projectMembers.set(projectId, { userId, role }); setUserId(''); }, 'memberSaved')}
        />
      </div>
      <div className="text-secondary">{t('roleExplanation')}</div>
    </div>
  );
};

export default MembersPanel;
