import React, { useState } from 'react';
import { RowStatusBadge } from 'shared/StatusBadge';
import { displayValue } from 'utils/format';
import { t } from 'i18n';

const issueClass = (issue) => (issue.severity === 'error' ? 'error' : 'warning');

const AsIs = ({ preview, used, carried, sourceSystem, active, onActive }) => (
  <section className="ba-card before" aria-label={t('asIsHeader', { system: sourceSystem })}>
    <header className="ba-head">
      <h3>{t('asIsHeader', { system: sourceSystem })}</h3>
      <span>{t('transactionsCount', { count: preview.rows.length })}</span>
    </header>
    {preview.rows.length === 0 ? (
      <div className="ba-empty">{t('noRowsToShow')}</div>
    ) : (
      <div className="ba-scroll">
        <table className="ba-table">
          <thead>
            <tr>
              <th scope="col" className="ba-index">#</th>
              {preview.sourceColumns.map((column) => (
                <th key={column} scope="col" className={used.has(column.toLowerCase()) ? '' : 'unused'} title={used.has(column.toLowerCase()) ? undefined : t('columnNotUsed')}>
                  {column}
                </th>
              ))}
              <th scope="col" />
            </tr>
          </thead>
          <tbody>
            {preview.rows.map((row) => (
              <React.Fragment key={row.sourceIndex}>
                <tr
                  className={`status-${row.status} ${active === row.sourceIndex ? 'active' : ''}`}
                  onMouseEnter={() => onActive(row.sourceIndex)}
                  onMouseLeave={() => onActive(null)}
                >
                  <td className="ba-index">{row.sourceIndex + 1}</td>
                  {preview.sourceColumns.map((column, c) => (
                    <td key={column} className={used.has(column.toLowerCase()) ? '' : 'unused'}>
                      {displayValue(row.source[c]) || (carried.has(column.toLowerCase())
                        ? <span className="carried" title={t('carriedDownTitle')}>↓</span>
                        : <span className="blank">{t('blank')}</span>)}
                    </td>
                  ))}
                  <td><RowStatusBadge status={row.status} /></td>
                </tr>
                {row.issues.length > 0 && (
                  <tr className="ba-issue-row">
                    <td colSpan={preview.sourceColumns.length + 2}>
                      <ul className="issue-list">
                        {row.issues.map((issue, k) => (
                          <li key={k} className={issueClass(issue)}>{t('rowIssue', { number: row.sourceIndex + 1, message: issue.message })}</li>
                        ))}
                      </ul>
                    </td>
                  </tr>
                )}
              </React.Fragment>
            ))}
          </tbody>
        </table>
      </div>
    )}
  </section>
);

const OutputSection = ({ schema, items, active, onActive }) => {
  const fieldIssues = items.flatMap(({ row, output }) => output.issues.map((issue) => ({ issue, row })));

  return (
    <div className="ba-output">
      <div className="ba-output-title">
        <span>{schema.name}</span>
        <span className="count">{t('rowsProduced', { count: items.length })}</span>
      </div>
      {items.length === 0 ? (
        <div className="ba-none">{t('noRowProduced')}</div>
      ) : (
        <div className="ba-scroll">
          <table className="ba-table">
            <thead>
              <tr>
                <th scope="col" className="ba-index">{t('fromRow')}</th>
                {schema.columns.map((column) => (
                  <th key={column.name} scope="col" className={column.type === 'number' ? 'num' : undefined}>{column.name}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {items.map(({ row, output }, index) => (
                <tr
                  key={index}
                  className={active === row.sourceIndex ? 'active' : ''}
                  onMouseEnter={() => onActive(row.sourceIndex)}
                  onMouseLeave={() => onActive(null)}
                >
                  <td className="ba-index">{output.repeatIndex ? `${row.sourceIndex + 1}.${output.repeatIndex}` : row.sourceIndex + 1}</td>
                  {schema.columns.map((column, c) => {
                    const cellIssues = output.issues.filter((i) => i.field === column.name);
                    const worst = cellIssues.find((i) => i.severity === 'error') || cellIssues[0];
                    const text = displayValue(output.values[c], column.decimals);
                    return (
                      <td
                        key={column.name}
                        className={`${column.type === 'number' ? 'num' : ''} ${worst ? `cell-${issueClass(worst)}` : ''}`}
                        title={cellIssues.map((i) => i.message).join('\n') || undefined}
                      >
                        {text || (worst ? '—' : '')}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
      {fieldIssues.length > 0 && (
        <ul className="issue-list mt-2">
          {fieldIssues.map(({ issue, row }, k) => (
            <li key={k} className={issueClass(issue)}>
              {t('rowIssue', { number: row.sourceIndex + 1, message: issue.field ? `${issue.field}: ${issue.message}` : issue.message })}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

/**
 * The review layout: the account holder's transactions as they are in the source system on top, and, in a
 * separate container below, every row they become in the target system. Row numbers tie the two together
 * (hover a row to highlight its counterparts).
 */
const BeforeAfter = ({ preview, usedColumns, carriedDown, sourceSystem, targetSystem }) => {
  const [active, setActive] = useState(null);
  const used = usedColumns || new Set();
  const carried = new Set((carriedDown || []).map((c) => String(c).trim().toLowerCase()));

  const transformedRows = preview.rows.filter((r) => r.status !== 'skipped');
  const produced = transformedRows.reduce((total, r) => total + r.outputs.length, 0);
  const failedBeforeOutput = transformedRows.filter((r) => r.status === 'error' && r.outputs.length === 0);

  return (
    <div className="before-after">
      <AsIs preview={preview} used={used} carried={carried} sourceSystem={sourceSystem} active={active} onActive={setActive} />

      <div className="ba-flow" aria-hidden="true">
        <span className="arrow">↓</span>
        <span>{t('transformationApplied')}</span>
      </div>

      <section className="ba-card after" aria-label={t('transformedHeader', { system: targetSystem })}>
        <header className="ba-head">
          <h3>{t('transformedHeader', { system: targetSystem })}</h3>
          <span>{t('rowsAcrossKinds', { count: produced, kinds: preview.outputs.length })}</span>
        </header>
        {transformedRows.length === 0 ? (
          <div className="ba-empty">{t('nothingToTransform')}</div>
        ) : (
          <>
            {failedBeforeOutput.length > 0 && (
              <p className="ba-note">{t('failedBeforeOutput', { rows: failedBeforeOutput.map((r) => r.sourceIndex + 1).join(', ') })}</p>
            )}
            {preview.outputs.map((schema) => (
              <OutputSection
                key={schema.id}
                schema={schema}
                active={active}
                onActive={setActive}
                items={transformedRows.flatMap((row) => row.outputs.filter((o) => o.outputId === schema.id).map((output) => ({ row, output })))}
              />
            ))}
          </>
        )}
      </section>
    </div>
  );
};

export default BeforeAfter;
