import React from 'react';
import { Badge } from 'reactstrap';
import { t } from 'i18n';

const REVIEW = {
  draft: { color: 'secondary', label: 'statusDraft' },
  readyForReview: { color: 'warning', label: 'statusReadyForReview' },
  approved: { color: 'success', label: 'statusApproved' },
};

const LOGIC = {
  draft: { color: 'secondary', label: 'logicDraft' },
  readyForReview: { color: 'warning', label: 'logicReadyForSignOff' },
  approved: { color: 'success', label: 'logicSignedOff' },
};

const ROW = {
  ok: { color: 'success', label: 'rowOk' },
  skipped: { color: 'secondary', label: 'rowSkipped' },
  error: { color: 'danger', label: 'rowError' },
};

export const ReviewStatusBadge = ({ status }) => {
  const style = REVIEW[status] || REVIEW.draft;
  return <Badge color={style.color} pill>{t(style.label)}</Badge>;
};

/** Status of the transformation logic itself (the mapping), as opposed to a run of real data. */
export const LogicStatusBadge = ({ status }) => {
  const style = LOGIC[status] || LOGIC.draft;
  return <Badge color={style.color} pill>{t(style.label)}</Badge>;
};

/** Where the latest real data stands: not loaded, waiting for review, approved, or approved for an older version of the logic. */
export const RunStatusBadge = ({ run }) => {
  if (!run) return <Badge color="light" pill>{t('runNoData')}</Badge>;
  if (run.approvalValid) return <Badge color="success" pill>{t('runApproved')}</Badge>;
  if (run.status === 'approved') return <Badge color="warning" pill>{t('runApprovalOutdated')}</Badge>;
  if (run.status === 'readyForReview') return <Badge color="warning" pill>{t('statusReadyForReview')}</Badge>;
  return <Badge color="secondary" pill>{t('runNotReviewed')}</Badge>;
};

export const RowStatusBadge = ({ status }) => {
  const style = ROW[status] || ROW.ok;
  return <Badge color={style.color} pill>{t(style.label)}</Badge>;
};
