import React from 'react';
import ModalContainer from 'shared/ModalContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import { t } from 'i18n';

const ConfirmModal = ({ open, title, message, confirmLabel = t('confirmButton'), danger, busy, onConfirm, onCancel }) => (
  <ModalContainer
    modal={open}
    toggleModal={onCancel}
    header={title}
    modalFooterContent={(
      <>
        <ActionButton title={t('cancelButton')} buttonColor="secondary" classes="mb-0" onClickAction={onCancel} />
        <ActionButton title={confirmLabel} buttonColor={danger ? 'danger' : 'primary'} outline={false} classes="mb-0" disabled={busy} onClickAction={onConfirm} />
      </>
    )}
  >
    <p>{message}</p>
  </ModalContainer>
);

export default ConfirmModal;
