import React, { useEffect } from 'react';
import { Alert } from 'reactstrap';
import { useDispatch, useSelector } from 'react-redux';
import { clearSnackbar } from 'shared/redux';

const DISPLAY_MILLISECONDS = 4000;

const Snackbar = () => {
  const dispatch = useDispatch();
  const { showSnackbar, snackbarColor, snackbarMessage } = useSelector(({ application }) => application);

  useEffect(() => {
    if (!showSnackbar) return undefined;
    const timer = setTimeout(() => dispatch(clearSnackbar()), DISPLAY_MILLISECONDS);
    return () => clearTimeout(timer);
  }, [showSnackbar, snackbarMessage, dispatch]);

  return (
    <Alert isOpen={Boolean(showSnackbar)} color={snackbarColor || 'info'} role="status" toggle={() => dispatch(clearSnackbar())}>
      {snackbarMessage}
    </Alert>
  );
};

export default Snackbar;
