import { requestKey } from './key.mjs';

/**
 * Demo mode: an axios adapter that answers from responses recorded against the real API, so the interface behaves as it
 * does for real but needs no server. Anything that would change data is refused with an explanation.
 */
const READ_ONLY_MESSAGE = 'This is a read-only demo, so changes are not saved. Get in touch to see it with your own data.';

let fixtures = null;
const load = () => {
  if (!fixtures) {
    fixtures = fetch(`${process.env.PUBLIC_URL || ''}/demo/fixtures.json`).then((r) => r.json());
  }
  return fixtures;
};

const respond = (config, status, data, headers = {}) => ({ data, status, statusText: String(status), headers, config, request: {} });

const reject = (config, status, title) => {
  const response = respond(config, status, { title, status });
  const error = new Error(title);
  error.config = config;
  error.response = response;
  error.isAxiosError = true;
  return Promise.reject(error);
};

const isoDate = (offsetDays) => {
  const d = new Date();
  d.setDate(d.getDate() + offsetDays);
  return d.toISOString().slice(0, 10);
};

/** Keeps the example project's migration date in the future, whenever the demo is opened. */
const freshen = (value) => {
  if (Array.isArray(value)) return value.map(freshen);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, k === 'migrationDate' && v ? isoDate(60) : freshen(v)]));
  }
  return value;
};

const decode = (base64) => Uint8Array.from(window.atob(base64), (c) => c.charCodeAt(0));

const demoAdapter = async (config) => {
  const method = (config.method || 'get').toUpperCase();
  const url = config.url || '';
  let body = config.data;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (e) {
      body = null;
    }
  }

  if (method === 'POST' && /\/auth\/login$/.test(url)) {
    return respond(config, 200, { token: 'demo', user: { id: 'demo', name: 'Demo user', email: (body && body.email) || 'demo@example.com', isAdministrator: true, isActive: true } });
  }

  const data = await load();
  const key = requestKey(method, url, config.params, body);

  if (config.responseType === 'blob') {
    const file = data.files[key];
    if (!file) return reject(config, 409, 'This download is not part of the demo.');
    const blob = new Blob([decode(file.base64)], { type: file.contentType });
    return respond(config, 200, blob, { 'content-disposition': `attachment; filename="${file.filename}"` });
  }

  const recorded = data.responses[key];
  if (recorded) return respond(config, recorded.status, freshen(recorded.data));
  if (method !== 'GET' && !/\/(preview|validate|reconciliation)$/.test(url.split('?')[0])) return reject(config, 409, READ_ONLY_MESSAGE);
  if (method !== 'GET') return reject(config, 409, 'The demo shows the saved example, so changes to the logic are not recalculated. Get in touch to try your own.');
  return reject(config, 404, 'That is not part of the demo.');
};

export default demoAdapter;
