import axios from 'axios';
import config from 'core/config';
import { getToken } from 'auth/tokenStore';
import demoAdapter from 'demo/adapter';

const client = axios.create({
  baseURL: config.apiBaseUrl,
  headers: {
    'Content-Type': 'application/json',
    'Accept': 'application/json',
  },
});

if (process.env.REACT_APP_DEMO === 'true') client.defaults.adapter = demoAdapter;

/**
 * Connects the client to the redux store: shows the loading indicator while requests run and signs the
 * user out when the API says the session is no longer valid.
 */
export const attachStore = (store, { onUnauthorised, onLoadingChange }) => {
  client.interceptors.request.use((request) => {
    const token = getToken();
    if (token) request.headers.Authorization = `Bearer ${token}`;
    if (!request.silent) store.dispatch(onLoadingChange(1));
    return request;
  });

  client.interceptors.response.use(
      (response) => {
        if (!response.config.silent) store.dispatch(onLoadingChange(-1));
        return response;
      },
      (error) => {
        if (!error.config?.silent) store.dispatch(onLoadingChange(-1));
        const isLogin = error.config?.url?.includes('/auth/login');
        if (error.response?.status === 401 && !isLogin) store.dispatch(onUnauthorised());
        return Promise.reject(error);
      },
  );
};

/** A readable message from a failed request (ProblemDetails title, validation errors, or a network problem). */
export const errorMessage = (error) => {
  const data = error?.response?.data;
  if (data instanceof Blob) return 'The file could not be created.';
  if (data?.errors) {
    const first = Object.values(data.errors).flat()[0];
    if (first) return first;
  }
  if (data?.title) return data.title;
  if (error?.response?.status === 429) return 'Too many attempts. Please wait a minute and try again.';
  if (error?.response) return 'Something went wrong. Please try again.';
  if (error?.code === 'ERR_CANCELED') return '';
  return 'The server could not be reached.';
};

/** Same as errorMessage, but for a failed download whose body arrives as a Blob. */
export const blobErrorMessage = async (error) => {
  if (error?.response?.data instanceof Blob) {
    try {
      const problem = JSON.parse(await error.response.data.text());
      if (problem.title) return problem.title;
    } catch (e) {
      // fall through
    }
  }
  return errorMessage(error);
};

export default client;
