// Application-wide UI state: the loading indicator and the snackbar message.
const UPDATE_LOADING_COUNT = 'application/UPDATE_LOADING_COUNT';
const SET_SNACKBAR = 'application/SET_SNACKBAR';
const CLEAR_SNACKBAR = 'application/CLEAR_SNACKBAR';

export const updateLoadingCount = (change) => ({ type: UPDATE_LOADING_COUNT, payload: change });

export const showSnackbar = (color, message) => ({ type: SET_SNACKBAR, payload: { color, message } });
export const setSnackbarSuccess = (message) => showSnackbar('success', message);
export const setSnackbarError = (message) => showSnackbar('danger', message);
export const clearSnackbar = () => ({ type: CLEAR_SNACKBAR });

const initialState = {
  loadingCount: 0,
  isLoading: false,
  showSnackbar: false,
  snackbarColor: null,
  snackbarMessage: null,
};

const reducer = (state = initialState, action) => {
  switch (action.type) {
    case UPDATE_LOADING_COUNT: {
      const loadingCount = Math.max(0, state.loadingCount + action.payload);
      return { ...state, loadingCount, isLoading: loadingCount > 0 };
    }
    case SET_SNACKBAR:
      return { ...state, showSnackbar: true, snackbarColor: action.payload.color, snackbarMessage: action.payload.message };
    case CLEAR_SNACKBAR:
      return { ...state, showSnackbar: false, snackbarColor: null, snackbarMessage: null };
    default:
      return state;
  }
};

export default reducer;
