import React from 'react';
import { useNavigate } from 'react-router-dom';
import { configuration } from 'api';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import DataTable from 'shared/DataTable';
import { LogicStatusBadge } from 'shared/StatusBadge';
import useAsync from 'shared/hooks/useAsync';
import { formatDateTime } from 'utils/format';
import { t } from 'i18n';

const crumbs = [
  { title: t('homePageHeader'), isActive: false, to: appRoutes.home },
  { title: t('configurationHeader'), isActive: false },
  { title: t('transformationsPageHeader'), isActive: true },
];

/** Every transformation routine across projects. Open one to edit it; copy it into another project from that project's list. */
const Transformations = () => {
  const navigate = useNavigate();
  const { data } = useAsync(() => configuration.routines(), []);

  return (
    <LayoutContainer heading={t('transformationsPageHeader')} breadcrumbs={crumbs} wide>
      <div className="pr-3">
        <p className="text-secondary">{t('transformationsIntro')}</p>
        <DataTable
          caption={t('transformationsPageHeader')}
          rows={data || []}
          rowKey={(r) => r.id}
          emptyText={t('noTransactionTypes')}
          onRowClick={(r) => navigate(appRoutes.logic(r.projectId, r.id))}
          columns={[
            { key: 'name', header: t('transformationRoutine') },
            { key: 'projectName', header: t('project') },
            { key: 'dataSourceName', header: t('dataSource'), render: (r) => r.dataSourceName || t('notSet') },
            { key: 'outputCount', header: t('targetRows'), className: 'num' },
            { key: 'version', header: t('version'), className: 'num' },
            { key: 'status', header: t('logicStatus'), render: (r) => <LogicStatusBadge status={r.status} /> },
            { key: 'updatedUtc', header: t('lastUpdated'), render: (r) => formatDateTime(r.updatedUtc) },
          ]}
        />
      </div>
    </LayoutContainer>
  );
};

export default Transformations;
