import React from 'react';
import { useExpressionContext } from './ExpressionContext';

/** A single-line expression box with its validation messages underneath. */
const ExpressionInput = ({ value, onChange, issues = [], placeholder, label, id, multiline }) => {
  const context = useExpressionContext();
  const hasError = issues.some((i) => i.severity === 'error');
  const Tag = multiline ? 'textarea' : 'input';

  return (
    <div className="expr">
      {label && <label htmlFor={id}>{label}</label>}
      <Tag
        id={id}
        type={multiline ? undefined : 'text'}
        rows={multiline ? 2 : undefined}
        className={`form-control expr-input ${hasError ? 'a-error-input' : ''}`}
        value={value || ''}
        placeholder={placeholder}
        spellCheck={false}
        autoComplete="off"
        onFocus={(e) => context && context.register(e.target, onChange)}
        onChange={(e) => {
          if (context) context.register(e.target, onChange);
          onChange(e.target.value);
        }}
      />
      {issues.map((issue, index) => (
        <span key={index} className={`expr-issue ${issue.severity === 'error' ? 'error' : 'warning'}`} role={issue.severity === 'error' ? 'alert' : undefined}>
          {issue.message}
        </span>
      ))}
    </div>
  );
};

export default ExpressionInput;
