import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { NavLink, useParams } from 'react-router-dom';
import { transactionTypes } from 'api';
import { errorMessage } from 'api/client';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import DataTable from 'shared/DataTable';
import { CheckField, SelectField, TextAreaField } from 'shared/Form';
import { Tile } from 'shared/Tile';
import { RunStatusBadge } from 'shared/StatusBadge';
import useActiveProject, { projectCrumbs } from 'shared/hooks/useActiveProject';
import useAsync from 'shared/hooks/useAsync';
import useRoutineScope from 'shared/RoutineScope';
import useRunSelection, { SAMPLE } from 'shared/hooks/useRunSelection';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import { formatDateTime, formatInteger, formatTotal } from 'utils/format';
import TypeHeader from '../transactionTypes/shared/TypeHeader';
import useProjectRole from 'shared/hooks/useProjectRole';
import { t } from 'i18n';

const Verdict = ({ passed }) => (
  <span className={`verdict ${passed ? 'ok' : 'bad'}`}>{passed ? t('balanced') : t('outOfBalance')}</span>
);

/** Reconciliation: do the totals taken from the source equal the totals of the rows produced, overall and for each account holder? */
const Reconciliation = () => {
  const { projectId, typeId } = useParams();
  const dispatch = useDispatch();
  const { project } = useActiveProject(projectId);
  const access = useProjectRole(project);
  const scope = useRoutineScope(projectId, typeId, appRoutes.reconciliation);
  const { type } = scope;
  const selection = useRunSelection(projectId, typeId, type?.version);
  const { runState, runs, useSample, currentRun, datasetId } = selection;
  const [onlyOut, setOnlyOut] = useState(false);
  const [notes, setNotes] = useState(null);
  const [busy, setBusy] = useState(false);

  const recState = useAsync(() => {
    if (!type || !runState.data) return Promise.resolve(null);
    return transactionTypes.reconciliation(projectId, typeId, { datasetId: datasetId || null, purpose: useSample ? 'sample' : 'live' });
  }, [projectId, typeId, type?.version, runState.data, datasetId, useSample]);
  const rec = recState.data;
  const controls = rec?.controls || [];
  const holders = rec?.holders || [];
  const summary = rec?.summary;
  const hasDefinitionErrors = rec?.definitionIssues?.some((i) => i.severity === 'error');
  const logicSignedOff = type?.status === 'approved';
  const approved = Boolean(currentRun?.approvalValid);
  const blocked = !summary || hasDefinitionErrors || summary.errors > 0 || summary.controlsFailed > 0 || controls.length === 0;
  const listedHolders = onlyOut ? holders.filter((h) => !h.passed) : holders;

  const review = async (status) => {
    setBusy(true);
    try {
      await transactionTypes.reviewRun(projectId, typeId, datasetId, { status, notes: (notes ?? currentRun.notes ?? '') || null });
      dispatch(setSnackbarSuccess(t(`runDone_${status}`)));
      setNotes(null);
      await runState.reload();
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    } finally {
      setBusy(false);
    }
  };

  const blockedText = () => {
    if (!logicSignedOff) return t('approveNeedsLogic');
    if (hasDefinitionErrors) return t('logicNeedsFixing');
    if (summary.errors > 0) return t('signOffBlocked', { count: formatInteger(summary.errors) });
    if (summary.controlsFailed > 0) return t('approveBlockedControls', { count: summary.controlsFailed });
    if (controls.length === 0) return t('approveNoControls');
    return t('approveDataReady');
  };

  return (
    <LayoutContainer heading={t('reconciliationPageHeader')} breadcrumbs={projectCrumbs(project, { title: t('reconciliationPageHeader') })} wide>
      <div className="pr-3">
        {scope.routinesLoaded && scope.routines.length === 0 && (
          <div className="panel">
            <h2>{t('noRoutinesHeader')}</h2>
            <div className="panel-help mb-1">{t('noRoutinesText')}</div>
            <NavLink className="btn btn-primary" to={appRoutes.transactionTypes(projectId)}>{t('goToTransformations')}</NavLink>
          </div>
        )}

        {type && (
          <>
            <TypeHeader projectId={projectId} type={type} routines={scope.routines} onChoose={scope.choose} />

            {runState.data && (
              <div className="panel">
                <div className="d-flex flex-wrap align-items-end">
                  <SelectField className="mr-3 w-auto" label={t('previewData')} value={selection.selectedValue} onChange={(v) => { selection.choose(v); setNotes(null); }}>
                    {runs.map((r) => (
                      <option key={r.datasetId} value={r.datasetId}>
                        {`${t('purpose_live')} · ${r.datasetLabel} · ${formatDateTime(r.loadedUtc)} · ${formatInteger(r.rows)} ${t('rows').toLowerCase()}`}
                      </option>
                    ))}
                    <option value={SAMPLE}>{t('previewSampleOption')}</option>
                  </SelectField>
                  <div className="mb-3">
                    {currentRun ? <RunStatusBadge run={currentRun} /> : <span className="text-secondary">{t('reconcileSampleNote')}</span>}
                  </div>
                </div>
              </div>
            )}

            {rec && (
              <>
                {rec.definitionIssues.length > 0 && (
                  <ul className="issue-list mb-2">
                    {rec.definitionIssues.map((issue, k) => (
                      <li key={k} className={issue.severity === 'error' ? 'error' : 'warning'}>{`${issue.path}: ${issue.message}`}</li>
                    ))}
                  </ul>
                )}

                <div className="stat-tiles">
                  <Tile value={summary.sourceRows} label={t('tileSourceRows', { system: project?.sourceSystemName || '' })} />
                  <Tile value={summary.errors} label={t('tileErrors')} tone={summary.errors ? 'bad' : 'ok'} />
                  <Tile value={controls.length - summary.controlsFailed} label={t('tileControlsPassed')} tone="ok" />
                  <Tile value={summary.controlsFailed} label={t('tileControlsFailed')} tone={summary.controlsFailed ? 'bad' : 'ok'} />
                  <Tile value={holders.filter((h) => !h.passed).length} label={t('tileHoldersOut')} tone={holders.some((h) => !h.passed) ? 'bad' : 'ok'} />
                </div>

                <div className="panel">
                  <h2>{t('controlTotalsHeader')}</h2>
                  <div className="panel-help">{t('controlTotalsHelp', { source: project?.sourceSystemName || '', target: project?.targetSystemName || '' })}</div>
                  {controls.length === 0 ? (
                    <div className="notice-inline">
                      {t('noControls')} <NavLink to={appRoutes.logic(projectId, typeId)}>{t('addControlsLink')}</NavLink>
                    </div>
                  ) : (
                    <DataTable
                      caption={t('controlTotalsHeader')}
                      rows={controls}
                      rowKey={(c) => c.id}
                      columns={[
                        { key: 'name', header: t('controlName') },
                        { key: 'field', header: t('controlTargetColumn'), render: (c) => c.field },
                        { key: 'sourceTotal', header: t('sourceTotal'), className: 'num', render: (c) => formatTotal(c.sourceTotal) },
                        { key: 'targetTotal', header: t('targetTotal'), className: 'num', render: (c) => formatTotal(c.targetTotal) },
                        { key: 'difference', header: t('difference'), className: 'num', render: (c) => formatTotal(c.difference) },
                        { key: 'tolerance', header: t('tolerance'), className: 'num', render: (c) => formatTotal(c.tolerance) },
                        { key: 'passed', header: '', render: (c) => <Verdict passed={c.passed} /> },
                      ]}
                    />
                  )}
                </div>

                {controls.length > 0 && holders.length > 0 && (
                  <div className="panel">
                    <div className="d-flex flex-wrap align-items-start">
                      <div className="mr-auto">
                        <h2>{t('perHolderHeader')}</h2>
                        <div className="panel-help">{t('perHolderHelp', { column: rec.holderColumn || '' })}</div>
                      </div>
                      <CheckField label={t('onlyOutOfBalance')} checked={onlyOut} onChange={setOnlyOut} />
                    </div>
                    <DataTable
                      dense
                      caption={t('perHolderHeader')}
                      rows={listedHolders}
                      rowKey={(h) => h.key || '(none)'}
                      emptyText={t('allHoldersBalance')}
                      rowClassName={(h) => (h.passed ? undefined : 'row-bad')}
                      columns={[
                        { key: 'label', header: t('accountHolder') },
                        { key: 'sourceRows', header: t('rows'), className: 'num' },
                        ...controls.map((c, i) => ({
                          key: c.id,
                          header: c.name,
                          className: 'num',
                          render: (h) => {
                            const x = h.controls[i];
                            return x.passed
                              ? `${formatTotal(x.sourceTotal)} = ${formatTotal(x.targetTotal)}`
                              : <span className="text-danger">{`${formatTotal(x.sourceTotal)} ≠ ${formatTotal(x.targetTotal)}`}</span>;
                          },
                        })),
                        { key: 'passed', header: '', render: (h) => (h.errors > 0 ? <span className="verdict bad">{t('holderErrors', { count: h.errors })}</span> : <Verdict passed={h.passed} />) },
                      ]}
                    />
                  </div>
                )}

                {currentRun && (
                  <div className="panel">
                    <h2>{t('approveDataHeader')}</h2>
                    <div className="panel-help">{blockedText()}</div>
                    <TextAreaField label={t('reviewNotes')} rows={2} value={notes ?? currentRun.notes ?? ''} onChange={setNotes} placeholder={t('reviewNotesPlaceholder')} />
                    {currentRun.status === 'draft' && (
                      <ActionButton title={t('sendForReview')} disabled={busy || !logicSignedOff || !access.canApprove} onClickAction={() => review('readyForReview')} />
                    )}
                    {!approved && (
                      <ActionButton title={t('approveButton')} outline={false} buttonColor="success" classes="ml-2" disabled={busy || !logicSignedOff || blocked || !access.canApprove} onClickAction={() => review('approved')} />
                    )}
                    {currentRun.status !== 'draft' && (
                      <ActionButton title={t('backToDraft')} buttonColor="secondary" classes="ml-2" disabled={busy || !access.canApprove} onClickAction={() => review('draft')} />
                    )}
                    {approved && (
                      <p className="mt-3 mb-0">
                        {t('approvedLine', { by: currentRun.approvedBy || '', when: formatDateTime(currentRun.approvedUtc), version: currentRun.logicVersion })}{' '}
                        <NavLink to={appRoutes.output(projectId)}>{t('goToOutput')}</NavLink>
                      </p>
                    )}
                  </div>
                )}
              </>
            )}
          </>
        )}
      </div>
    </LayoutContainer>
  );
};

export default Reconciliation;
