import React from 'react';
import ActionButton from 'shared/Buttons/ActionButton';
import ExpressionInput from './ExpressionInput';
import RowTools from './RowTools';
import { issuesAt, moveItem, newControl, removeAt, replaceAt } from '../shared/definition';
import { t } from 'i18n';

/** Reconciliation controls: a total taken from each source row that must equal the total of an output column. */
const ControlsSection = ({ controls, outputs, issues, onChange, sourceSystem, targetSystem }) => {
  const numberFields = (outputId) => (outputs.find((o) => o.id === outputId)?.fields || []).filter((f) => f.type === 'number' && f.target.trim());

  return (
    <div className="panel logic-section">
      <h2>{t('controlsHeader')}</h2>
      <div className="panel-help">{t('controlsHelp', { source: sourceSystem, target: targetSystem })}</div>
      {controls.length === 0 && <div className="text-secondary mb-2">{t('noControlsDefined')}</div>}
      {controls.map((control, index) => {
        const path = `controls[${index}]`;
        const change = (patch) => onChange(replaceAt(controls, index, { ...control, ...patch }));
        const own = issuesAt(issues, path, true).filter((i) => !i.path.endsWith('sourceExpression'));
        return (
          <div key={control.id} className="control-row mb-3">
            <div className="d-flex align-items-start flex-wrap">
              <input
                type="text"
                className="form-control form-control-sm mr-2 mb-2"
                style={{ maxWidth: '22rem' }}
                aria-label={t('controlName')}
                placeholder={t('controlNamePlaceholder')}
                value={control.name}
                onChange={(e) => change({ name: e.target.value })}
              />
              <select
                className="form-control form-control-sm mr-2 mb-2"
                style={{ maxWidth: '13rem' }}
                aria-label={t('controlOutput')}
                value={control.outputId}
                onChange={(e) => change({ outputId: e.target.value, field: '' })}
              >
                <option value="">{t('controlChooseOutput')}</option>
                {outputs.map((o) => <option key={o.id} value={o.id}>{o.name || t('unnamedOutput')}</option>)}
              </select>
              <select
                className="form-control form-control-sm mr-2 mb-2"
                style={{ maxWidth: '13rem' }}
                aria-label={t('controlTargetColumn')}
                value={control.field}
                onChange={(e) => change({ field: e.target.value })}
                disabled={!control.outputId}
              >
                <option value="">{t('controlChooseColumn')}</option>
                {numberFields(control.outputId).map((f) => <option key={f.target} value={f.target}>{f.target}</option>)}
              </select>
              <div className="input-group input-group-sm mr-2 mb-2" style={{ maxWidth: '10rem' }}>
                <div className="input-group-prepend"><span className="input-group-text">±</span></div>
                <input
                  type="number"
                  min="0"
                  step="any"
                  className="form-control"
                  aria-label={t('tolerance')}
                  value={control.tolerance}
                  onChange={(e) => change({ tolerance: e.target.value })}
                />
              </div>
              <RowTools
                index={index}
                count={controls.length}
                onMove={(delta) => onChange(moveItem(controls, index, delta))}
                onRemove={() => onChange(removeAt(controls, index))}
              />
            </div>
            <ExpressionInput
              id={`control-${index}`}
              label={t('controlSourceValue', { system: sourceSystem })}
              value={control.sourceExpression}
              placeholder={t('controlSourcePlaceholder')}
              onChange={(value) => change({ sourceExpression: value })}
              issues={issuesAt(issues, `${path}.sourceExpression`)}
            />
            {own.map((i, k) => <span key={k} className="expr-issue error">{i.message}</span>)}
          </div>
        );
      })}
      <ActionButton title={t('addControl')} classes="btn-sm mb-0" disabled={outputs.length === 0} onClickAction={() => onChange([...controls, newControl()])} />
      {outputs.length === 0 && <span className="ml-2 text-secondary">{t('controlNeedsOutput')}</span>}
    </div>
  );
};

export default ControlsSection;
