import React from 'react';
import { useNavigate } from 'react-router-dom';
import { configuration } from 'api';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import DataTable from 'shared/DataTable';
import useAsync from 'shared/hooks/useAsync';
import { formatDateTime } from 'utils/format';
import { t } from 'i18n';

const crumbs = [
  { title: t('homePageHeader'), isActive: false, to: appRoutes.home },
  { title: t('configurationHeader'), isActive: false },
  { title: t('lookupsPageHeader'), isActive: true },
];

/** Every lookup table (value map) across projects. */
const Lookups = () => {
  const navigate = useNavigate();
  const { data } = useAsync(() => configuration.lookups(), []);

  return (
    <LayoutContainer heading={t('lookupsPageHeader')} breadcrumbs={crumbs} wide>
      <div className="pr-3">
        <p className="text-secondary">{t('lookupsIntro')}</p>
        <DataTable
          caption={t('lookupsPageHeader')}
          rows={data || []}
          rowKey={(l) => l.id}
          emptyText={t('noValueMaps')}
          onRowClick={(l) => navigate(appRoutes.valueMaps(l.projectId))}
          columns={[
            { key: 'name', header: t('valueMapName') },
            { key: 'projectName', header: t('project') },
            { key: 'description', header: t('sourceDescription'), render: (l) => l.description || '' },
            { key: 'entryCount', header: t('entries'), className: 'num' },
            { key: 'updatedUtc', header: t('lastUpdated'), render: (l) => formatDateTime(l.updatedUtc) },
          ]}
        />
      </div>
    </LayoutContainer>
  );
};

export default Lookups;
