import React from 'react';
import { useParams } from 'react-router-dom';
import { transactionTypes } from 'api';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import useActiveProject, { projectCrumbs } from 'shared/hooks/useActiveProject';
import useAsync from 'shared/hooks/useAsync';
import { formatDateTime } from 'utils/format';
import TypeHeader from '../shared/TypeHeader';
import { t } from 'i18n';

const ChangeLog = () => {
  const { projectId, typeId } = useParams();
  const { project } = useActiveProject(projectId);
  const typeState = useAsync(() => transactionTypes.get(projectId, typeId), [projectId, typeId]);
  const logState = useAsync(() => transactionTypes.changeLog(projectId, typeId), [projectId, typeId]);
  const type = typeState.data;
  const entries = logState.data || [];

  return (
    <LayoutContainer
      heading={t('changeLogHeader', { name: type?.name || '' })}
      breadcrumbs={projectCrumbs(
          project,
          { title: t('transactionTypesPageHeader'), to: appRoutes.transactionTypes(projectId) },
          { title: type?.name || '' },
      )}
      wide
    >
      {type && (
        <div className="pr-3">
          <TypeHeader projectId={projectId} type={type} />
          <div className="panel">
            <h2>{t('changeLogTitle')}</h2>
            <div className="panel-help">{t('changeLogHelp')}</div>
            {entries.length === 0 && <div className="text-secondary">{t('changeLogEmpty')}</div>}
            <ol className="changelog">
              {entries.map((entry) => (
                <li key={entry.id} className={`kind-${entry.kind}`}>
                  <div className="entry-head">
                    <strong className="mr-2">{t(`changeKind_${entry.kind}`)}</strong>
                    {entry.version ? <span className="mr-2">{t('changeVersion', { version: entry.version })}</span> : null}
                    <span className="text-secondary">{entry.createdBy}</span>
                    <span className="when">{formatDateTime(entry.createdUtc)}</span>
                  </div>
                  <ul className="entry-lines">
                    {entry.lines.map((line, index) => <li key={index}>{line}</li>)}
                  </ul>
                  {entry.comment && <div className="entry-comment">{`“${entry.comment}”`}</div>}
                </li>
              ))}
            </ol>
          </div>
        </div>
      )}
    </LayoutContainer>
  );
};

export default ChangeLog;
