import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { configuration, transactionTypes } from 'api';
import { errorMessage } from 'api/client';
import ModalContainer from 'shared/ModalContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import { SelectField, TextAreaField, TextField } from 'shared/Form';
import useAsync from 'shared/hooks/useAsync';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import { t } from 'i18n';

/** Creates a transaction type (optionally starting from another one's logic) or edits its details. */
const TransactionTypeModal = ({ projectId, type, sources, onClose, onSaved }) => {
  const dispatch = useDispatch();
  const editing = Boolean(type?.id);
  const candidates = useAsync(() => (editing ? Promise.resolve([]) : configuration.routines()), [editing]);
  const existing = candidates.data || [];
  const [form, setForm] = useState({
    name: type?.name || '',
    description: type?.description || '',
    dataSourceId: type?.dataSourceId || (sources.length === 1 ? sources[0].id : ''),
    copyFromId: '',
  });
  const [errors, setErrors] = useState({});
  const [busy, setBusy] = useState(false);
  const set = (field) => (value) => setForm((f) => ({ ...f, [field]: value }));

  const save = async () => {
    const found = {};
    if (!form.name.trim()) found.name = t('requiredField');
    if (!form.dataSourceId) found.dataSourceId = t('chooseSource');
    setErrors(found);
    if (Object.keys(found).length) return;

    setBusy(true);
    try {
      const copy = existing.find((x) => x.id === form.copyFromId);
      const body = {
        name: form.name.trim(),
        description: form.description.trim() || null,
        dataSourceId: form.dataSourceId,
        copyFromId: copy?.id || null,
        copyFromProjectId: copy && copy.projectId !== projectId ? copy.projectId : null,
      };
      const saved = editing ? await transactionTypes.update(projectId, type.id, body) : await transactionTypes.create(projectId, body);
      dispatch(setSnackbarSuccess(t('transactionTypeSaved')));
      onSaved(saved);
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    } finally {
      setBusy(false);
    }
  };

  return (
    <ModalContainer
      modal
      toggleModal={onClose}
      header={editing ? t('editTransactionTypeHeader') : t('addTransactionTypeHeader')}
      subHeader={t('transactionTypeModalIntro')}
      modalFooterContent={(
        <>
          <ActionButton title={t('cancelButton')} buttonColor="secondary" classes="mb-0" onClickAction={onClose} />
          <ActionButton title={t('saveButton')} outline={false} classes="mb-0" disabled={busy} onClickAction={save} />
        </>
      )}
    >
      <TextField label={t('transactionTypeName')} placeholder={t('transactionTypeNamePlaceholder')} value={form.name} onChange={set('name')} error={errors.name} required autoFocus />
      <TextAreaField label={t('sourceDescription')} rows={2} value={form.description} onChange={set('description')} />
      <SelectField label={t('dataSource')} value={form.dataSourceId} onChange={set('dataSourceId')} error={errors.dataSourceId} hint={t('dataSourceHint')} required>
        <option value="">{t('chooseSource')}</option>
        {sources.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
      </SelectField>
      {!editing && existing.length > 0 && (
        <SelectField label={t('copyLogicFrom')} value={form.copyFromId} onChange={set('copyFromId')} hint={t('copyLogicHint')}>
          <option value="">{t('startEmpty')}</option>
          {existing.map((x) => <option key={x.id} value={x.id}>{x.projectId === projectId ? x.name : `${x.name} (${x.projectName})`}</option>)}
        </SelectField>
      )}
    </ModalContainer>
  );
};

export default TransactionTypeModal;
