import React from 'react';
import { useSelector } from 'react-redux';
import { BrowserRouter, Navigate, Route, Routes } from 'react-router-dom';
import { appRoutes } from './routes';
import ProtectedRoute from './ProtectedRoute';
import useInactivityLogout from './useInactivityLogout';
import NotFound from 'shared/NotFound';
import Login from 'pages/accessManagement/login';
import Users from 'pages/accessManagement/users';
import Home from 'pages';
import Projects from 'pages/projects';
import ProjectOverview from 'pages/projects/overview';
import Sources from 'pages/sources';
import SourceDetail from 'pages/sources/detail';
import TransactionTypes from 'pages/transactionTypes';
import LogicBuilder from 'pages/transactionTypes/logic';
import DataPreview from 'pages/preview';
import Reconciliation from 'pages/reconciliation';
import TargetOutput from 'pages/output';
import ConfigSources from 'pages/configuration/DataSources';
import ConfigTransformations from 'pages/configuration/Transformations';
import ConfigLookups from 'pages/configuration/Lookups';
import ChangeLog from 'pages/transactionTypes/changelog';
import ValueMaps from 'pages/valueMaps';

const App = () => {
  const { isLoggedIn } = useSelector(({ account }) => account);
  useInactivityLogout(isLoggedIn);

  return (
    <BrowserRouter>
      <Routes>
        <Route path={appRoutes.login} element={isLoggedIn ? <Navigate to={appRoutes.home} replace /> : <Login />} />
        <Route element={<ProtectedRoute />}>
          <Route path={appRoutes.home} element={<Home />} />
          <Route path={appRoutes.users} element={<Users />} />
          <Route path={appRoutes.projects} element={<Projects />} />
          <Route path="/projects/:projectId" element={<ProjectOverview />} />
          <Route path="/projects/:projectId/sources" element={<Sources />} />
          <Route path="/projects/:projectId/sources/:sourceId" element={<SourceDetail />} />
          <Route path="/projects/:projectId/transaction-types" element={<TransactionTypes />} />
          <Route path="/projects/:projectId/transaction-types/:typeId" element={<LogicBuilder />} />
          <Route path="/projects/:projectId/transaction-types/:typeId/changelog" element={<ChangeLog />} />
          <Route path="/projects/:projectId/value-maps" element={<ValueMaps />} />
          <Route path="/projects/:projectId/data-preview" element={<DataPreview />} />
          <Route path="/projects/:projectId/data-preview/:typeId" element={<DataPreview />} />
          <Route path="/projects/:projectId/reconciliation" element={<Reconciliation />} />
          <Route path="/projects/:projectId/reconciliation/:typeId" element={<Reconciliation />} />
          <Route path="/projects/:projectId/target-output" element={<TargetOutput />} />
          <Route path={appRoutes.configSources} element={<ConfigSources />} />
          <Route path={appRoutes.configTransformations} element={<ConfigTransformations />} />
          <Route path={appRoutes.configLookups} element={<ConfigLookups />} />
        </Route>
        <Route path="*" element={<NotFound />} />
      </Routes>
    </BrowserRouter>
  );
};

export default App;
