/** Helpers for the file layout editor. A layout is { sheet, headerRow, strict, columns: [{ name, type, format, required, description }] }. */

export const COLUMN_TYPES = ['text', 'number', 'date'];

export const emptyColumn = () => ({ name: '', type: 'text', format: '', required: false, description: '' });

/** A layout ready to edit: no nulls, at least a header row of 1. */
export const toForm = (layout) => ({
  sheet: layout?.sheet || '',
  headerRow: layout?.headerRow || 1,
  strict: Boolean(layout?.strict),
  columns: (layout?.columns || []).map((c) => ({
    name: c.name,
    type: c.type || 'text',
    format: c.format || '',
    required: Boolean(c.required),
    description: c.description || '',
  })),
});

/** The layout to send: blank columns dropped, formats only on date columns. */
export const toRequest = (form) => ({
  sheet: form.sheet.trim() || null,
  headerRow: Math.max(1, Number(form.headerRow) || 1),
  strict: form.strict,
  columns: form.columns
      .filter((c) => c.name.trim())
      .map((c) => ({
        name: c.name.trim(),
        type: c.type,
        format: c.type === 'date' && c.format.trim() ? c.format.trim() : null,
        required: c.required,
        description: c.description.trim() || null,
      })),
});

/** Names that appear more than once (ignoring case), which the server would silently drop. */
export const duplicateNames = (form) => {
  const seen = new Set();
  const duplicates = new Set();
  form.columns.forEach((c) => {
    const key = c.name.trim().toLowerCase();
    if (!key) return;
    if (seen.has(key)) duplicates.add(c.name.trim());
    seen.add(key);
  });
  return [...duplicates];
};

export const sameLayout = (a, b) => JSON.stringify(toRequest(a)) === JSON.stringify(toRequest(b));
