/** One "key, value" pair per line. Pasting two Excel columns works (tab separated); commas and = are accepted too. */
export const parseEntries = (text) => {
  const entries = [];
  const duplicates = [];
  const seen = new Set();

  (text || '').split(/\r?\n/).forEach((line) => {
    if (!line.trim()) return;
    const separator = ['\t', ',', '='].find((s) => line.includes(s));
    const at = separator ? line.indexOf(separator) : -1;
    const key = (at < 0 ? line : line.slice(0, at)).trim();
    const value = at < 0 ? '' : line.slice(at + 1).trim();
    if (!key) return;
    if (seen.has(key.toLowerCase())) {
      duplicates.push(key);
      return;
    }
    seen.add(key.toLowerCase());
    entries.push({ key, value });
  });

  return { entries, duplicates };
};

export const formatEntries = (entries) => (entries || []).map((e) => `${e.key}\t${e.value ?? ''}`).join('\n');
