import React from 'react';
import ActionButton from 'shared/Buttons/ActionButton';
import { t } from 'i18n';

/**
 * A plain table styled to match the application.
 * columns: [{ key, header, render?(row, index), className?, width? }]
 */
const DataTable = ({ columns, rows, rowKey = (row, index) => index, onRowClick, emptyText = t('noRows'), caption, dense, rowClassName }) => (
  <div className="dm-table-wrapper">
    <table className={`dm-table ${dense ? 'dense' : ''} ${onRowClick ? 'clickable' : ''}`}>
      {caption && <caption className="sr-only">{caption}</caption>}
      <thead>
        <tr>
          {columns.map((column) => (
            <th key={column.key} scope="col" className={column.className} style={column.width ? { width: column.width } : undefined}>{column.header}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.length === 0 && (
          <tr>
            <td colSpan={columns.length} className="dm-table-empty">{emptyText}</td>
          </tr>
        )}
        {rows.map((row, index) => (
          <tr
            key={rowKey(row, index)}
            className={rowClassName ? rowClassName(row) : undefined}
            onClick={onRowClick ? () => onRowClick(row) : undefined}
            onKeyDown={onRowClick ? (e) => e.key === 'Enter' && onRowClick(row) : undefined}
            tabIndex={onRowClick ? 0 : undefined}
          >
            {columns.map((column) => (
              <td key={column.key} className={column.className}>
                {column.render ? column.render(row, index) : row[column.key]}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  </div>
);

export const Pager = ({ skip, take, total, onChange }) => {
  if (total <= take) return null;
  const first = total === 0 ? 0 : skip + 1;
  const last = Math.min(skip + take, total);

  return (
    <div className="dm-pager">
      <ActionButton classes="mb-0 mr-2" title={t('previous')} disabled={skip === 0} onClickAction={() => onChange(Math.max(0, skip - take))} />
      <ActionButton classes="mb-0 mr-3" title={t('next')} disabled={skip + take >= total} onClickAction={() => onChange(skip + take)} />
      <span className="text-secondary">{t('pagerRange', { first: first.toLocaleString(), last: last.toLocaleString(), total: total.toLocaleString() })}</span>
    </div>
  );
};

export default DataTable;
