// How a request is matched to a recorded response. Shared by the demo adapter (in the browser) and the recorder (in node),
// so both sides always agree.

const pathOf = (url) => String(url).replace(/^https?:\/\/[^/]+/, '').split('?')[0];

const paramsText = (params) => Object.keys(params || {})
    .filter((k) => params[k] !== undefined && params[k] !== null && params[k] !== '')
    .sort()
    .map((k) => `${k}=${params[k]}`)
    .join('&');

/** Reads that are POSTs (they run the logic) are matched on the parts that change the answer, not on the whole body. */
const bodyText = (path, body) => {
  const b = body || {};
  if (/\/transaction-types\/[^/]+\/(preview|reconciliation)$/.test(path)) {
    const purpose = String(b.purpose || 'live').toLowerCase() === 'sample' ? 'sample' : 'live';
    const dataset = purpose === 'sample' ? '' : (b.datasetId || '');
    return [purpose, dataset, b.holder ?? '', b.filter || 'matched', b.skip || 0].join('|');
  }
  return '';
};

export const requestKey = (method, url, params, body) => {
  const path = pathOf(url);
  return `${String(method).toUpperCase()} ${path}?${paramsText(params)}#${bodyText(path, body)}`;
};
