import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { users as usersApi } from 'api';
import { errorMessage } from 'api/client';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import DataTable from 'shared/DataTable';
import ModalContainer from 'shared/ModalContainer';
import { CheckField, TextField } from 'shared/Form';
import useAsync from 'shared/hooks/useAsync';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import { t } from 'i18n';

const blank = { name: '', email: '', password: '', isActive: true, isAdministrator: false };

const UserModal = ({ user, onClose, onSaved }) => {
  const dispatch = useDispatch();
  const creating = !user.id;
  const [form, setForm] = useState({ ...blank, ...user, password: '' });
  const [errors, setErrors] = useState({});
  const [busy, setBusy] = useState(false);
  const set = (field) => (value) => setForm((f) => ({ ...f, [field]: value }));

  const save = async () => {
    const found = {};
    if (!form.name.trim()) found.name = t('requiredField');
    if (creating && !/^\S+@\S+\.\S+$/.test(form.email.trim())) found.email = t('invalidEmail');
    if ((creating || form.password) && form.password.length < 12) found.password = t('passwordTooShort');
    setErrors(found);
    if (Object.keys(found).length) return;

    setBusy(true);
    try {
      if (creating) {
        await usersApi.create({ name: form.name.trim(), email: form.email.trim(), password: form.password, isAdministrator: form.isAdministrator });
      } else {
        await usersApi.update(user.id, { name: form.name.trim(), isActive: form.isActive, isAdministrator: form.isAdministrator });
        if (form.password) await usersApi.resetPassword(user.id, form.password);
      }
      dispatch(setSnackbarSuccess(t('userSaved')));
      onSaved();
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    } finally {
      setBusy(false);
    }
  };

  return (
    <ModalContainer
      modal
      toggleModal={onClose}
      header={creating ? t('addUserHeader') : t('editUserHeader')}
      modalFooterContent={(
        <>
          <ActionButton title={t('cancelButton')} buttonColor="secondary" classes="mb-0" onClickAction={onClose} />
          <ActionButton title={t('saveButton')} outline={false} classes="mb-0" disabled={busy} onClickAction={save} />
        </>
      )}
    >
      <TextField label={t('userName')} value={form.name} onChange={set('name')} error={errors.name} required />
      <TextField label={t('loginEmailAddress')} type="email" value={form.email} onChange={set('email')} error={errors.email} disabled={!creating} required={creating} />
      <TextField
        label={creating ? t('loginPassword') : t('userNewPassword')}
        type="password"
        value={form.password}
        onChange={set('password')}
        error={errors.password}
        hint={t('passwordRules')}
        required={creating}
      />
      <CheckField label={t('userIsAdministrator')} checked={form.isAdministrator} onChange={set('isAdministrator')} />
      <div className="field-hint mb-2">{t('userIsAdministratorHint')}</div>
      {!creating && <CheckField label={t('userIsActive')} checked={form.isActive} onChange={set('isActive')} />}
    </ModalContainer>
  );
};

const Users = () => {
  const { loginUser } = useSelector(({ account }) => account);
  const { data, reload } = useAsync(() => usersApi.list(), []);
  const [editing, setEditing] = useState(null);

  return (
    <LayoutContainer
      heading={t('usersPageHeader')}
      breadcrumbs={[
        { title: t('homePageHeader'), isActive: false, to: appRoutes.home },
        { title: t('usersPageHeader'), isActive: true },
      ]}
    >
      <div className="pr-3">
        <p className="text-secondary">{t('usersIntro')}</p>
        <ActionButton title={t('addButton')} onClickAction={() => setEditing({})} />
        <DataTable
          caption={t('usersPageHeader')}
          rows={data || []}
          rowKey={(row) => row.id}
          onRowClick={setEditing}
          columns={[
            { key: 'name', header: t('userName'), render: (u) => `${u.name}${u.id === loginUser?.id ? ` ${t('userYou')}` : ''}` },
            { key: 'email', header: t('loginEmailAddress') },
            { key: 'isAdministrator', header: t('userAccess'), render: (u) => (u.isAdministrator ? t('userAdministrator') : t('userProjectMember')) },
            { key: 'isActive', header: t('userStatus'), render: (u) => (u.isActive ? t('userActive') : t('userInactive')) },
          ]}
        />
      </div>
      {editing && <UserModal user={editing} onClose={() => setEditing(null)} onSaved={() => { setEditing(null); reload(); }} />}
    </LayoutContainer>
  );
};

export default Users;
