import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { auth } from 'api';
import { errorMessage } from 'api/client';
import { appRoutes } from 'app/routes';
import { signedIn } from 'shared/account';
import ActionButton from 'shared/Buttons/ActionButton';
import { TextField } from 'shared/Form';
import Snackbar from 'shared/Snackbar';
import Brand from 'shared/Brand';
import config from 'core/config';
import { t } from 'i18n';

const Login = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [email, setEmail] = useState(config.demo ? 'demo@example.com' : '');
  const [password, setPassword] = useState(config.demo ? 'demo-password' : '');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);

  const submit = async (event) => {
    event.preventDefault();
    if (!email.trim() || !password) {
      setError(t('loginMissingDetails'));
      return;
    }
    setBusy(true);
    setError('');
    try {
      dispatch(signedIn(await auth.login(email.trim(), password)));
      navigate(appRoutes.home);
    } catch (e) {
      setError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="login-modal">
      <div className="card">
        <div className="card-title">
          <div className="m-4"><Brand stacked /></div>
        </div>
        <form onSubmit={submit} noValidate>
          <div className="card-body">
            <TextField
              type="email"
              name="email"
              label={t('loginEmailAddress')}
              placeholder={t('loginEmailAddressPlaceholder')}
              value={email}
              onChange={setEmail}
              autoFocus
              required
            />
            <TextField
              type="password"
              name="password"
              label={t('loginPassword')}
              placeholder={t('loginPasswordPlaceholder')}
              value={password}
              onChange={setPassword}
              error={error}
              required
            />
          </div>
          {config.demo && <p className="text-secondary px-4 mb-0 text-center">{t('demoLoginNote')}</p>}
          <div className="card-footer">
            <div className="text-align-center">
              <ActionButton type="submit" outline={false} buttonColor="primary" title={t('loginButton')} disabled={busy} />
            </div>
          </div>
        </form>
      </div>
      <Snackbar />
    </div>
  );
};

export default Login;
