import React from 'react';
import icon from 'assets/images/brand-icon.png';
import cycle from 'assets/images/brand-cycle.png';
import { t } from 'i18n';

/** The application icon, used in the navigation header. */
export const Logo = ({ size = '2.2rem' }) => (
  <img src={icon} alt="" style={{ height: size, width: size }} className="brand-logo" />
);

/**
 * The application mark. In the header it is the icon followed by the product name; on the sign-in page (stacked)
 * it is the full cycle illustration, which carries the name itself.
 */
const Brand = ({ stacked }) => (stacked ? (
  <img src={cycle} alt={t('appName')} className="brand-cycle" />
) : (
  <span className="brand">
    <Logo />
    <span className="brand-text">
      <span className="brand-name">{t('appName')}</span>
      <span className="brand-tagline">{t('appTagline')}</span>
    </span>
  </span>
));

export default Brand;
