import React from 'react';
import { Button } from 'reactstrap';
import { icons } from 'assets/images';

const ActionButton = ({
  buttonColor = 'primary',
  buttonIcon,
  buttonIconClasses = 'mr-1',
  buttonIconTitle,
  buttonWidth = 14,
  classes = '',
  title,
  outline = true,
  disabled,
  type = 'button',
  onClickAction,
}) => (
  <Button color={buttonColor} className={`mb-2 ${classes}`} outline={outline} disabled={disabled} type={type} onClick={onClickAction}>
    {buttonIcon && <img src={icons[buttonIcon]} width={buttonWidth} className={buttonIconClasses} title={buttonIconTitle} alt="" />}
    {title}
  </Button>
);

export default ActionButton;
