import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { Input } from 'reactstrap';
import { projects as projectsApi } from 'api';
import { appRoutes } from 'app/routes';
import { t } from 'i18n';

const ProjectSwitcher = () => {
  const navigate = useNavigate();
  const { activeProject } = useSelector(({ account }) => account);
  const [projects, setProjects] = useState([]);

  useEffect(() => {
    let cancelled = false;
    projectsApi.list()
        .then((list) => !cancelled && setProjects(list))
        .catch(() => undefined); // the switcher is a convenience; page-level errors are shown by the pages themselves
    return () => {
      cancelled = true;
    };
  }, [activeProject?.id]);

  return (
    <div className="client-switcher">
      <Input
        type="select"
        bsSize="sm"
        aria-label={t('projectSwitcher')}
        value={activeProject?.id || ''}
        onChange={(e) => e.target.value && navigate(appRoutes.project(e.target.value))}
      >
        <option value="">{t('projectSwitcherPlaceholder')}</option>
        {projects.map((project) => (
          <option key={project.id} value={project.id}>{project.name}</option>
        ))}
      </Input>
    </div>
  );
};

export default ProjectSwitcher;
