import React from 'react';
import ActionButton from 'shared/Buttons/ActionButton';
import ExpressionInput from './ExpressionInput';
import RowTools from './RowTools';
import { issuesAt, moveItem, newVariable, removeAt, replaceAt } from '../shared/definition';
import { t } from 'i18n';

const VariablesSection = ({ variables, onChange, issues }) => (
  <div className="panel logic-section">
    <h2>{t('variablesHeader')}</h2>
    <div className="panel-help">{t('variablesHelp')}</div>
    {variables.length === 0 && <div className="text-secondary mb-2">{t('noVariables')}</div>}
    {variables.map((variable, index) => {
      const path = `variables[${index}]`;
      const nameIssues = issuesAt(issues, `${path}.name`);
      return (
        <div key={index} className="d-flex align-items-start mb-2">
          <div style={{ width: '11rem' }} className="mr-2">
            <div className="input-group input-group-sm">
              <div className="input-group-prepend"><span className="input-group-text">$</span></div>
              <input
                type="text"
                className={`form-control mono ${nameIssues.length ? 'a-error-input' : ''}`}
                aria-label={t('variableName')}
                placeholder={t('variableNamePlaceholder')}
                value={variable.name}
                onChange={(e) => onChange(replaceAt(variables, index, { ...variable, name: e.target.value }))}
              />
            </div>
            {nameIssues.map((i, k) => <span key={k} className="expr-issue error">{i.message}</span>)}
          </div>
          <div className="flex-grow-1">
            <ExpressionInput
              id={`variable-${index}`}
              value={variable.expression}
              placeholder={t('variableExpressionPlaceholder')}
              onChange={(value) => onChange(replaceAt(variables, index, { ...variable, expression: value }))}
              issues={issuesAt(issues, `${path}.expression`).concat(issuesAt(issues, path))}
            />
          </div>
          <RowTools
            index={index}
            count={variables.length}
            onMove={(delta) => onChange(moveItem(variables, index, delta))}
            onRemove={() => onChange(removeAt(variables, index))}
          />
        </div>
      );
    })}
    <ActionButton title={t('addVariable')} classes="btn-sm mb-0" onClickAction={() => onChange([...variables, newVariable()])} />
  </div>
);

export default VariablesSection;
