import React, { useMemo } from 'react';
import { buildMapping } from '../shared/definition';
import { t } from 'i18n';

/**
 * The column mapping at a glance: each source column and every destination column (in any table) it feeds.
 * A source column can feed many destination columns; columns used nowhere are flagged.
 */
const MappingOverview = ({ definition, columns, sourceSystem, targetSystem }) => {
  const mapping = useMemo(() => buildMapping(definition), [definition]);
  const names = useMemo(() => {
    const extra = [...mapping.keys()].filter((k) => !columns.some((c) => c.toLowerCase() === k));
    return [...columns, ...extra];
  }, [columns, mapping]);
  const unused = names.filter((c) => !mapping.has(c.toLowerCase())).length;

  if (names.length === 0) return null;

  return (
    <div className="panel logic-section mapping-overview">
      <h2>{t('mappingHeader')}</h2>
      <div className="panel-help">{t('mappingHelp', { source: sourceSystem, target: targetSystem })}</div>
      <table className="fields-table">
        <thead>
          <tr>
            <th scope="col" style={{ width: '22%' }}>{t('mappingSource', { system: sourceSystem })}</th>
            <th scope="col">{t('mappingDestinations', { system: targetSystem })}</th>
          </tr>
        </thead>
        <tbody>
          {names.map((column) => {
            const targets = mapping.get(column.toLowerCase()) || [];
            return (
              <tr key={column} className={targets.length === 0 ? 'unmapped' : ''}>
                <td className="mono">{column}</td>
                <td>
                  {targets.length === 0 && <span className="text-secondary">{t('mappingNotUsed')}</span>}
                  {targets.map((m, i) => (
                    <span key={i} className={`map-chip ${m.direct ? 'direct' : 'derived'}`} title={m.direct ? t('mappingDirect') : t('mappingDerived')}>
                      {`${m.table || t('unnamedOutput')} › ${m.target}`}
                    </span>
                  ))}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      {unused > 0 && <div className="text-secondary mt-2">{t('mappingUnused', { count: unused })}</div>}
    </div>
  );
};

export default MappingOverview;
