import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useDispatch } from 'react-redux';
import { NavLink, useParams } from 'react-router-dom';
import { expression as expressionApi, sources, transactionTypes, valueMaps } from 'api';
import { errorMessage } from 'api/client';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import { TextAreaField } from 'shared/Form';
import useActiveProject, { projectCrumbs } from 'shared/hooks/useActiveProject';
import useAsync from 'shared/hooks/useAsync';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import { formatDateTime, formatInteger } from 'utils/format';
import BeforeAfter from '../shared/BeforeAfter';
import TransactionTypeModal from '../TransactionTypeModal';
import TypeHeader from '../shared/TypeHeader';
import { emptyDefinition, issuesAt, moveItem, newOutput, normaliseDefinition, referencedColumns, removeAt, replaceAt, sameDefinition } from '../shared/definition';
import { ExpressionProvider } from './ExpressionContext';
import ExpressionInput from './ExpressionInput';
import HelpPanel from './HelpPanel';
import ControlsSection from './ControlsSection';
import MappingOverview from './MappingOverview';
import OutputCard from './OutputCard';
import VariablesSection from './VariablesSection';
import useProjectRole from 'shared/hooks/useProjectRole';
import { t } from 'i18n';

const VALIDATE_DELAY = 500;
const PREVIEW_DELAY = 900;

/** Runs `task` shortly after `deps` stop changing; a newer change cancels an older pending run. */
const useDebouncedEffect = (task, deps, delay) => {
  const taskRef = useRef(task);
  taskRef.current = task;
  useEffect(() => {
    const timer = setTimeout(() => taskRef.current(), delay);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
};

const LogicBuilder = () => {
  const { projectId, typeId } = useParams();
  const dispatch = useDispatch();
  const { project } = useActiveProject(projectId);
  const access = useProjectRole(project);
  const typeState = useAsync(() => transactionTypes.get(projectId, typeId), [projectId, typeId]);
  const functionState = useAsync(() => expressionApi.functions(), []);
  const mapState = useAsync(() => valueMaps.list(projectId), [projectId]);
  const type = typeState.data;

  const [draft, setDraft] = useState(null);
  const [baseline, setBaseline] = useState(null);
  const [version, setVersion] = useState(null);
  const [comment, setComment] = useState('');
  const [issues, setIssues] = useState([]);
  const [knownColumns, setKnownColumns] = useState([]);
  const [signOffNotes, setSignOffNotes] = useState('');
  const [sampleMessage, setSampleMessage] = useState('');
  const [sample, setSample] = useState(null);
  const [sampleBusy, setSampleBusy] = useState(false);
  const [saving, setSaving] = useState(false);
  const [editingDetails, setEditingDetails] = useState(false);
  const [sources_, setSources] = useState([]);

  // Take the saved logic as the starting point whenever the page (re)loads it.
  useEffect(() => {
    if (type) {
      const definition = { ...emptyDefinition(), ...type.definition };
      setDraft(definition);
      setBaseline(definition);
      setVersion(type.version);
    }
    // Only when a different transaction type or a newly saved version arrives, so editing its details does not discard unsaved logic.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [type?.id, type?.version]);

  useEffect(() => {
    sources.list(projectId).then(setSources).catch(() => undefined);
  }, [projectId]);

  const dirty = Boolean(draft && baseline && !sameDefinition(draft, baseline));

  useEffect(() => {
    if (!dirty) return undefined;
    const warn = (event) => {
      event.preventDefault();
      event.returnValue = '';
    };
    window.addEventListener('beforeunload', warn);
    return () => window.removeEventListener('beforeunload', warn);
  }, [dirty]);

  const normalised = useMemo(() => (draft ? normaliseDefinition(draft) : null), [draft]);

  useDebouncedEffect(() => {
    if (!normalised) return;
    transactionTypes.validate(projectId, typeId, { definition: normalised, purpose: 'sample' }, { silent: true })
        .then((result) => {
          setIssues(result.issues);
          setKnownColumns(result.sourceColumns);
        })
        .catch(() => undefined);
  }, [normalised], VALIDATE_DELAY);

  useDebouncedEffect(() => {
    if (!normalised || !type?.dataSourceId) return;
    setSampleBusy(true);
    transactionTypes.preview(projectId, typeId, { definition: normalised, purpose: 'sample', filter: 'matched', skip: 0, take: 3 }, { silent: true })
        .then((result) => {
          setSample(result);
          setSampleMessage('');
        })
        .catch((e) => {
          setSample(null);
          setSampleMessage(errorMessage(e));
        })
        .finally(() => setSampleBusy(false));
  }, [normalised, type?.dataSourceId], PREVIEW_DELAY);

  const update = useCallback((patch) => setDraft((d) => ({ ...d, ...patch })), []);

  const save = async () => {
    setSaving(true);
    try {
      const saved = await transactionTypes.saveDefinition(projectId, typeId, { definition: normalised, comment: comment.trim() || null, expectedVersion: version });
      dispatch(setSnackbarSuccess(t(saved.version === version ? 'logicUnchanged' : 'logicSaved', { version: saved.version })));
      setVersion(saved.version);
      setBaseline(draft);
      setComment('');
      typeState.reload();
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    } finally {
      setSaving(false);
    }
  };

  const signOff = async (status) => {
    setSaving(true);
    try {
      await transactionTypes.signOff(projectId, typeId, { status, notes: signOffNotes.trim() || null });
      dispatch(setSnackbarSuccess(t(`signOffDone_${status}`)));
      setSignOffNotes('');
      typeState.reload();
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    } finally {
      setSaving(false);
    }
  };

  const columns = knownColumns.length > 0 ? knownColumns : sample?.sourceColumns || [];
  const used = useMemo(() => (draft ? referencedColumns(draft) : new Set()), [draft]);
  const errorCount = issues.filter((i) => i.severity === 'error').length;
  const sourceSystem = project?.sourceSystemName || '';
  const targetSystem = project?.targetSystemName || '';
  const repeating = Boolean(draft?.outputs.some((o) => o.repeatCount));

  return (
    <LayoutContainer
      heading={type?.name || t('transactionTypesPageHeader')}
      breadcrumbs={projectCrumbs(project, { title: t('transactionTypesPageHeader'), to: appRoutes.transactionTypes(projectId) }, { title: type?.name || '' })}
      wide
    >
      {type && draft && (
        <ExpressionProvider>
          <div className="pr-3">
            <TypeHeader projectId={projectId} type={type}>
              <ActionButton title={t('editDetails')} buttonColor="secondary" onClickAction={() => setEditingDetails(true)} />
            </TypeHeader>

            <div className="panel">
              <h2>{t('signOffLogicHeader')}</h2>
              <div className="panel-help">{t('signOffLogicHelp', { target: targetSystem })}</div>
              {dirty && <div className="text-secondary mb-2">{t('saveBeforeSignOff')}</div>}
              {type.status === 'approved' && (
                <div className="text-secondary mb-2">{t('logicSignedOffLine', { by: type.approvedBy || '', when: formatDateTime(type.approvedUtc), version: type.approvedVersion })}</div>
              )}
              {type.status !== 'approved' && (
                <TextAreaField label={t('signOffNotes')} rows={2} value={signOffNotes} onChange={setSignOffNotes} placeholder={t('signOffNotesPlaceholder')} />
              )}
              {type.status === 'draft' && (
                <ActionButton title={t('sendForSignOff')} disabled={!access.canEdit || dirty || saving || errorCount > 0} onClickAction={() => signOff('readyForReview')} />
              )}
              {type.status !== 'approved' && (
                <ActionButton title={t('signOffButton')} outline={false} buttonColor="success" classes="ml-2" disabled={!access.canApprove || dirty || saving || errorCount > 0} onClickAction={() => signOff('approved')} />
              )}
              {type.status !== 'draft' && (
                <ActionButton title={t('backToDraft')} buttonColor="secondary" classes="ml-2" disabled={!access.canApprove || saving} onClickAction={() => signOff('draft')} />
              )}
              {type.status === 'approved' && (
                <NavLink className="btn btn-outline-primary ml-2 mb-2" to={appRoutes.preview(projectId, typeId)}>{t('goToRun')}</NavLink>
              )}
            </div>

            <p className="text-secondary">{t('builderIntro', { source: sourceSystem, target: targetSystem })}</p>

            <div className="builder">
              <div>
                <div className="panel logic-section prepare-rows">
                  <h2>{t('prepareHeader')}</h2>
                  <div className="panel-help">{t('prepareHelp', { system: sourceSystem })}</div>

                  <div className="help-title-inline">{t('carryDownLabel')}</div>
                  <div className="fill-chips">
                    {Array.from(new Set([...columns, ...draft.fillDown])).map((column) => {
                      const on = draft.fillDown.some((c) => c.toLowerCase() === column.toLowerCase());
                      return (
                        <button
                          key={column}
                          type="button"
                          className={`fill-chip ${on ? 'on' : ''}`}
                          aria-pressed={on}
                          onClick={() => update({ fillDown: on ? draft.fillDown.filter((c) => c.toLowerCase() !== column.toLowerCase()) : [...draft.fillDown, column] })}
                        >
                          {column}
                        </button>
                      );
                    })}
                    {columns.length === 0 && draft.fillDown.length === 0 && <span className="text-secondary">{t('helpNoColumns')}</span>}
                  </div>
                  {issuesAt(issues, 'fillDown', true).map((i, k) => <span key={k} className="expr-issue error">{i.message}</span>)}

                  <ExpressionInput
                    id="group-by"
                    label={t('groupByLabel')}
                    value={draft.groupBy}
                    placeholder={t('groupByPlaceholder')}
                    onChange={(value) => update({ groupBy: value })}
                    issues={issuesAt(issues, 'groupBy')}
                  />
                  <div className="field-hint">{t('groupByHint')}</div>
                </div>

                <div className="panel logic-section">
                  <h2>{t('filterHeader')}</h2>
                  <div className="panel-help">{t('filterHelp', { system: sourceSystem })}</div>
                  <ExpressionInput
                    id="filter"
                    value={draft.filter}
                    placeholder={t('filterPlaceholder')}
                    onChange={(value) => update({ filter: value })}
                    issues={issuesAt(issues, 'filter')}
                  />
                  {sample && !sampleBusy && sample.definitionIssues.every((i) => i.severity !== 'error') && (
                    <div className="text-secondary">
                      {t('filterMatches', { matched: formatInteger(sample.summary.transformed + sample.summary.errors), total: formatInteger(sample.summary.sourceRows) })}
                    </div>
                  )}
                </div>

                <VariablesSection variables={draft.variables} issues={issues} onChange={(variables) => update({ variables })} />

                <div className="panel logic-section">
                  <div className="section-head">
                    <h2 className="mb-0">{t('outputsHeader', { system: targetSystem })}</h2>
                  </div>
                  <div className="panel-help">{t('outputsHelp', { source: sourceSystem, target: targetSystem })}</div>
                  {issuesAt(issues, 'outputs').map((i, k) => <span key={k} className="expr-issue error mb-2">{i.message}</span>)}
                  {draft.outputs.map((output, index) => (
                    <OutputCard
                      key={output.id}
                      output={output}
                      index={index}
                      count={draft.outputs.length}
                      targetSystem={targetSystem}
                      sourceSystem={sourceSystem}
                      columns={columns}
                      issues={issues}
                      onChange={(value) => update({ outputs: replaceAt(draft.outputs, index, value) })}
                      onMove={(delta) => update({ outputs: moveItem(draft.outputs, index, delta) })}
                      onRemove={() => update({ outputs: removeAt(draft.outputs, index) })}
                    />
                  ))}
                  <ActionButton title={t('addOutput', { system: targetSystem })} onClickAction={() => update({ outputs: [...draft.outputs, newOutput()] })} />
                </div>

                <MappingOverview definition={draft} columns={columns} sourceSystem={sourceSystem} targetSystem={targetSystem} />

                <ControlsSection
                  controls={draft.controls || []}
                  outputs={draft.outputs}
                  issues={issues}
                  sourceSystem={sourceSystem}
                  targetSystem={targetSystem}
                  onChange={(controls) => update({ controls })}
                />

                <div className="panel logic-section">
                  <h2>{t('samplePreviewHeader')}</h2>
                  <div className="panel-help">{sample ? t('samplePreviewHelpWith', { label: sample.dataset.label, purpose: t(`purpose_${sample.dataset.purpose}`) }) : t('samplePreviewHelp')}</div>
                  {!sample && sampleMessage ? (
                    <div className="text-secondary">
                      {sampleMessage}{' '}
                      {type.dataSourceId && <NavLink to={appRoutes.source(projectId, type.dataSourceId)}>{t('loadSampleData')}</NavLink>}
                    </div>
                  ) : sample && sample.definitionIssues.some((i) => i.severity === 'error') ? (
                    <div className="text-secondary">{t('sampleFixIssues')}</div>
                  ) : sample ? (
                    <BeforeAfter preview={sample} usedColumns={used} carriedDown={draft.fillDown} sourceSystem={sourceSystem} targetSystem={targetSystem} />
                  ) : (
                    <div className="text-secondary">{t('loading')}</div>
                  )}
                </div>
              </div>

              <HelpPanel
                columns={columns}
                variables={draft.variables}
                valueMapNames={(mapState.data || []).map((m) => m.name)}
                functions={functionState.data || []}
                repeating={repeating}
                sourceSystem={sourceSystem}
              />
            </div>

            <div className="save-bar">
              <div className="mr-3">
                {dirty ? <span className="dirty">{t('unsavedChanges')}</span> : <span className="saved">{t('allSaved')}</span>}
                {errorCount > 0 && <span className="a-error-type ml-3">{t('problemsCount', { count: errorCount })}</span>}
              </div>
              <input
                type="text"
                className="form-control form-control-sm mr-2"
                style={{ maxWidth: '24rem' }}
                aria-label={t('changeComment')}
                placeholder={t('changeCommentPlaceholder')}
                value={comment}
                onChange={(e) => setComment(e.target.value)}
              />
              <ActionButton title={t('saveLogic')} outline={false} classes="mb-0" disabled={!access.canEdit || !dirty || saving} onClickAction={save} />
              {dirty && <ActionButton title={t('discardChanges')} buttonColor="secondary" classes="mb-0 ml-2" onClickAction={() => setDraft(baseline)} />}
            </div>
          </div>
        </ExpressionProvider>
      )}
      {editingDetails && type && (
        <TransactionTypeModal
          projectId={projectId}
          type={type}
          sources={sources_}
          onClose={() => setEditingDetails(false)}
          onSaved={() => { setEditingDetails(false); typeState.reload(); }}
        />
      )}
    </LayoutContainer>
  );
};

export default LogicBuilder;
