import { createStore, applyMiddleware, combineReducers } from 'redux';
import { persistStore, persistReducer } from 'redux-persist';
import thunk from 'redux-thunk';
import storageSession from 'redux-persist/lib/storage/session';
import application, { updateLoadingCount } from 'shared/redux';
import account, { signOut } from 'shared/account';
import { attachStore } from 'api/client';
import { hasValidToken } from 'auth/tokenStore';

const rootReducer = combineReducers({ application, account });

const persistConfig = {
  key: 'root',
  storage: storageSession,
  whitelist: ['account'],
};

const store = createStore(persistReducer(persistConfig, rootReducer), applyMiddleware(thunk));

attachStore(store, {
  onLoadingChange: updateLoadingCount,
  onUnauthorised: signOut,
});

export const persistor = persistStore(store, null, () => {
  // A restored session is only good while its token is; otherwise start signed out.
  if (store.getState().account.isLoggedIn && !hasValidToken()) {
    store.dispatch(signOut());
  }
});

export default store;
