import React from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { configuration, projects } from 'api';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import DataTable from 'shared/DataTable';
import useAsync from 'shared/hooks/useAsync';
import { formatDateTime, formatInteger } from 'utils/format';
import { t } from 'i18n';

const crumbs = [
  { title: t('homePageHeader'), isActive: false, to: appRoutes.home },
  { title: t('configurationHeader'), isActive: false },
  { title: t('dataSourcesPageHeader'), isActive: true },
];

/** Data in and data out for every project: where the data comes from, and where the finished files go. */
const DataSources = () => {
  const navigate = useNavigate();
  const sourceState = useAsync(() => configuration.sources(), []);
  const projectState = useAsync(() => projects.list(), []);

  return (
    <LayoutContainer heading={t('dataSourcesPageHeader')} breadcrumbs={crumbs} wide>
      <div className="pr-3">
        <p className="text-secondary">{t('dataSourcesIntro')}</p>
        <div className="panel">
          <h2>{t('dataInHeader')}</h2>
          <div className="panel-help">{t('dataInHelp')}</div>
          <DataTable
            caption={t('dataInHeader')}
            rows={sourceState.data || []}
            rowKey={(s) => s.id}
            emptyText={t('noSources')}
            onRowClick={(s) => navigate(appRoutes.source(s.projectId, s.id))}
            columns={[
              { key: 'name', header: t('sourceName') },
              { key: 'projectName', header: t('project') },
              { key: 'kind', header: t('sourceKind'), render: (s) => (s.kind === 'api' ? t('kindApi') : t('kindUpload')) },
              { key: 'columnCount', header: t('columnsHeader'), className: 'num', render: (s) => (s.columnCount ? formatInteger(s.columnCount) : t('notSet')) },
              { key: 'lastLoadedUtc', header: t('lastLoad'), render: (s) => (s.lastLoadedUtc ? `${formatDateTime(s.lastLoadedUtc)} · ${t('rowsCount', { count: formatInteger(s.lastLoadRows) })}` : t('noDataYet')) },
            ]}
          />
        </div>
        <div className="panel">
          <h2>{t('dataOutHeader')}</h2>
          <div className="panel-help">{t('dataOutHelp')}</div>
          <DataTable
            caption={t('dataOutHeader')}
            rows={projectState.data || []}
            rowKey={(p) => p.id}
            emptyText={t('noProjects')}
            onRowClick={(p) => navigate(appRoutes.output(p.id))}
            columns={[
              { key: 'targetSystemName', header: t('targetSystem') },
              { key: 'name', header: t('project') },
              { key: 'transactionTypeCount', header: t('transformationsCount'), className: 'num' },
              { key: 'fileNamePattern', header: t('fileNamePattern'), render: (p) => <span className="mono">{p.fileNamePattern}</span> },
              { key: 'open', header: '', render: (p) => <NavLink to={appRoutes.output(p.id)} onClick={(e) => e.stopPropagation()}>{t('openOutput')}</NavLink> },
            ]}
          />
        </div>
      </div>
    </LayoutContainer>
  );
};

export default DataSources;
