import { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { transactionTypes } from 'api';
import useAsync from 'shared/hooks/useAsync';

/**
 * For the project pages that work on one transformation routine at a time (data preview, reconciliation): loads the
 * project's routines, sends the page to the first one when none is chosen, and loads the chosen one in full.
 */
const useRoutineScope = (projectId, typeId, routeFor) => {
  const navigate = useNavigate();
  const listState = useAsync(() => transactionTypes.list(projectId), [projectId]);
  const typeState = useAsync(() => (typeId ? transactionTypes.get(projectId, typeId) : Promise.resolve(null)), [projectId, typeId]);
  const list = listState.data;

  useEffect(() => {
    if (!typeId && list && list.length > 0) navigate(routeFor(projectId, list[0].id), { replace: true });
  }, [typeId, list, projectId, navigate, routeFor]);

  return {
    routines: list || [],
    routinesLoaded: Boolean(list),
    type: typeState.data,
    reloadType: typeState.reload,
    choose: (id) => navigate(routeFor(projectId, id)),
  };
};

export default useRoutineScope;
