import React from 'react';
import ActionButton from 'shared/Buttons/ActionButton';
import ExpressionInput from './ExpressionInput';
import RowTools from './RowTools';
import { columnReference, directColumn, issuesAt, moveItem, newField, removeAt, replaceAt, withAllSourceColumns } from '../shared/definition';
import { t } from 'i18n';

const TYPES = ['text', 'number', 'date', 'boolean'];

const OutputCard = ({ output, index, count, targetSystem, sourceSystem, columns = [], issues, onChange, onMove, onRemove }) => {
  const path = `outputs[${index}]`;
  const set = (patch) => onChange({ ...output, ...patch });
  const setField = (fieldIndex, patch) => set({ fields: replaceAt(output.fields, fieldIndex, { ...output.fields[fieldIndex], ...patch }) });

  const toggleKey = (target) => {
    const key = output.uniqueKey || [];
    set({ uniqueKey: key.includes(target) ? key.filter((k) => k !== target) : [...key, target] });
  };

  const structural = issuesAt(issues, path).concat(issuesAt(issues, `${path}.id`), issuesAt(issues, `${path}.fields`), issuesAt(issues, `${path}.uniqueKey`));
  const nameIssues = issuesAt(issues, `${path}.name`);

  return (
    <section className="output-card" aria-label={output.name || t('unnamedOutput')}>
      <div className="output-head">
        <div className="form-group flex-grow-1">
          <label htmlFor={`output-name-${output.id}`}>{t('outputName', { system: targetSystem })}</label>
          <input
            id={`output-name-${output.id}`}
            type="text"
            className={`form-control ${nameIssues.length ? 'a-error-input' : ''}`}
            placeholder={t('outputNamePlaceholder')}
            value={output.name}
            onChange={(e) => set({ name: e.target.value })}
          />
          {nameIssues.map((i, k) => <span key={k} className="expr-issue error">{i.message}</span>)}
        </div>
        <div className="form-group flex-grow-1">
          <label htmlFor={`output-desc-${output.id}`}>{t('outputDescription')}</label>
          <input
            id={`output-desc-${output.id}`}
            type="text"
            className="form-control"
            value={output.description || ''}
            onChange={(e) => set({ description: e.target.value })}
          />
        </div>
        <RowTools index={index} count={count} onMove={onMove} onRemove={onRemove} />
      </div>

      <div className="d-flex">
        <div className="flex-grow-1 mr-3">
          <ExpressionInput
            id={`output-condition-${output.id}`}
            label={t('outputCondition')}
            placeholder={t('outputConditionPlaceholder')}
            value={output.condition}
            onChange={(value) => set({ condition: value })}
            issues={issuesAt(issues, `${path}.condition`)}
          />
        </div>
        <div className="flex-grow-1">
          <ExpressionInput
            id={`output-repeat-${output.id}`}
            label={t('outputRepeat')}
            placeholder={t('outputRepeatPlaceholder')}
            value={output.repeatCount}
            onChange={(value) => set({ repeatCount: value })}
            issues={issuesAt(issues, `${path}.repeatCount`)}
          />
        </div>
      </div>

      <table className="fields-table">
        <thead>
          <tr>
            <th scope="col" style={{ width: '16%' }}>{t('fieldTarget', { system: targetSystem })}</th>
            <th scope="col" style={{ width: '13rem' }}>{t('fieldSourceColumn', { system: sourceSystem })}</th>
            <th scope="col">{t('fieldExpression')}</th>
            <th scope="col" style={{ width: '9rem' }}>{t('fieldType')}</th>
            <th scope="col" style={{ width: '4rem' }}>{t('fieldRequired')}</th>
            <th scope="col" style={{ width: '1%' }} />
          </tr>
        </thead>
        <tbody>
          {output.fields.map((field, f) => {
            const fieldPath = `${path}.fields[${f}]`;
            const targetIssues = issuesAt(issues, `${fieldPath}.target`);
            return (
              <tr key={f}>
                <td>
                  <input
                    type="text"
                    className={`form-control form-control-sm ${targetIssues.length ? 'a-error-input' : ''}`}
                    aria-label={t('fieldTargetLabel')}
                    placeholder={t('fieldTargetPlaceholder')}
                    value={field.target}
                    onChange={(e) => setField(f, { target: e.target.value })}
                  />
                  {targetIssues.map((i, k) => <span key={k} className="expr-issue error">{i.message}</span>)}
                </td>
                <td>
                  <select
                    className="form-control form-control-sm"
                    aria-label={t('fieldSourceColumn', { system: sourceSystem })}
                    value={directColumn(field.expression) || ''}
                    onChange={(e) => {
                      if (!e.target.value) return;
                      setField(f, { expression: columnReference(e.target.value), target: field.target.trim() ? field.target : e.target.value });
                    }}
                  >
                    <option value="">{directColumn(field.expression) || !field.expression.trim() ? t('fieldChooseColumn') : t('fieldDerived')}</option>
                    {Array.from(new Set([...columns, directColumn(field.expression)].filter(Boolean))).map((c) => <option key={c} value={c}>{c}</option>)}
                  </select>
                </td>
                <td>
                  <ExpressionInput
                    id={`${output.id}-field-${f}`}
                    value={field.expression}
                    placeholder={t('fieldExpressionPlaceholder')}
                    onChange={(value) => setField(f, { expression: value })}
                    issues={issuesAt(issues, `${fieldPath}.expression`)}
                  />
                </td>
                <td>
                  <select
                    className="form-control form-control-sm"
                    aria-label={t('fieldType')}
                    value={field.type}
                    onChange={(e) => setField(f, { type: e.target.value })}
                  >
                    {TYPES.map((type) => <option key={type} value={type}>{t(`type_${type}`)}</option>)}
                  </select>
                  {field.type === 'number' && (
                    <input
                      type="number"
                      min={0}
                      max={12}
                      className="form-control form-control-sm mt-1"
                      aria-label={t('fieldDecimals')}
                      placeholder={t('fieldDecimalsPlaceholder')}
                      value={field.decimals ?? ''}
                      onChange={(e) => setField(f, { decimals: e.target.value === '' ? null : Number(e.target.value) })}
                    />
                  )}
                  {field.type === 'date' && (
                    <input
                      type="text"
                      className="form-control form-control-sm mt-1 mono"
                      aria-label={t('fieldDateFormat')}
                      placeholder="yyyy-MM-dd"
                      value={field.format ?? ''}
                      onChange={(e) => setField(f, { format: e.target.value })}
                    />
                  )}
                  {issuesAt(issues, `${fieldPath}.format`).concat(issuesAt(issues, `${fieldPath}.decimals`)).map((i, k) => (
                    <span key={k} className="expr-issue error">{i.message}</span>
                  ))}
                </td>
                <td className="text-center">
                  <input type="checkbox" aria-label={t('fieldRequired')} checked={Boolean(field.required)} onChange={(e) => setField(f, { required: e.target.checked })} />
                </td>
                <td>
                  <RowTools
                    index={f}
                    count={output.fields.length}
                    onMove={(delta) => set({ fields: moveItem(output.fields, f, delta) })}
                    onRemove={() => set({ fields: removeAt(output.fields, f), uniqueKey: (output.uniqueKey || []).filter((k) => k !== field.target) })}
                  />
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>

      <div className="d-flex align-items-center flex-wrap mt-2">
        <ActionButton title={t('addField')} classes="btn-sm mb-0 mr-2" onClickAction={() => set({ fields: [...output.fields, newField()] })} />
        <ActionButton title={t('addAllSourceColumns')} classes="btn-sm mb-0 mr-4" disabled={columns.length === 0} onClickAction={() => set(withAllSourceColumns(output, columns))} />
        <div className="text-secondary mr-2">{t('uniqueKey')}</div>
        {output.fields.filter((f) => f.target.trim()).map((f) => (
          <label key={f.target} className="mr-3 mb-0 font-size-11">
            <input type="checkbox" className="mr-1" checked={(output.uniqueKey || []).includes(f.target)} onChange={() => toggleKey(f.target)} />
            {f.target}
          </label>
        ))}
      </div>
      {structural.map((i, k) => <span key={k} className={`expr-issue ${i.severity === 'error' ? 'error' : 'warning'}`}>{i.message}</span>)}
    </section>
  );
};

export default OutputCard;
