import React from 'react';
import { Input } from 'reactstrap';

let nextId = 0;
const useFieldId = (id) => {
  const ref = React.useRef(id);
  if (!ref.current) {
    nextId += 1;
    ref.current = `field-${nextId}`;
  }
  return ref.current;
};

/** Label, control and message in the application's standard layout. */
export const FormField = ({ id, label, required, hint, error, className = '', children }) => (
  <div className={`form-group w-100 ${className}`}>
    {label && (
      <label htmlFor={id}>
        {label}
        {required && <span className="text-blue"> *</span>}
      </label>
    )}
    {children}
    {hint && !error && <span className="field-hint">{hint}</span>}
    {error && <span className="a-error-type" role="alert">{error}</span>}
  </div>
);

export const TextField = ({ id, label, required, hint, error, className, inputClass = '', onChange, ...rest }) => {
  const fieldId = useFieldId(id);
  return (
    <FormField id={fieldId} label={label} required={required} hint={hint} error={error} className={className}>
      <Input
        id={fieldId}
        autoComplete="off"
        className={`${error ? 'a-error-input' : ''} ${inputClass}`}
        onChange={(e) => onChange && onChange(e.target.value)}
        {...rest}
      />
    </FormField>
  );
};

export const TextAreaField = (props) => <TextField type="textarea" rows={3} {...props} />;

export const SelectField = ({ id, label, required, hint, error, className, onChange, children, ...rest }) => {
  const fieldId = useFieldId(id);
  return (
    <FormField id={fieldId} label={label} required={required} hint={hint} error={error} className={className}>
      <Input id={fieldId} type="select" className={error ? 'a-error-input' : ''} onChange={(e) => onChange && onChange(e.target.value)} {...rest}>
        {children}
      </Input>
    </FormField>
  );
};

export const CheckField = ({ id, label, checked, onChange, disabled, className = '' }) => {
  const fieldId = useFieldId(id);
  return (
    <div className={`form-group form-check ${className}`}>
      <input
        id={fieldId}
        type="checkbox"
        className="form-check-input"
        checked={Boolean(checked)}
        disabled={disabled}
        onChange={(e) => onChange && onChange(e.target.checked)}
      />
      <label className="form-check-label" htmlFor={fieldId}>{label}</label>
    </div>
  );
};
