import React, { createContext, useCallback, useContext, useMemo, useRef } from 'react';

const ExpressionContext = createContext(null);

/**
 * Remembers which expression box was used last, so that clicking a column, variable or function in the
 * help panel inserts it at the cursor of that box.
 */
export const ExpressionProvider = ({ children }) => {
  const active = useRef(null);

  const register = useCallback((element, onChange) => {
    active.current = { element, onChange };
  }, []);

  const insert = useCallback((text) => {
    const current = active.current;
    if (!current || !document.body.contains(current.element)) return false;

    const { element, onChange } = current;
    const start = element.selectionStart ?? element.value.length;
    const end = element.selectionEnd ?? element.value.length;
    const next = element.value.slice(0, start) + text + element.value.slice(end);

    // Put the cursor after the inserted text (inside the brackets for a function call). The DOM is updated
    // straight away, before React re-renders, so typing that follows immediately lands in the right place.
    const caret = start + text.length - (text.endsWith(')') && text.includes('(') ? 1 : 0);
    element.value = next;
    element.focus();
    element.setSelectionRange(caret, caret);
    onChange(next);
    return true;
  }, []);

  const value = useMemo(() => ({ register, insert }), [register, insert]);
  return <ExpressionContext.Provider value={value}>{children}</ExpressionContext.Provider>;
};

export const useExpressionContext = () => useContext(ExpressionContext);
