import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { sourceLayout, sources } from 'api';
import { errorMessage } from 'api/client';
import ModalContainer from 'shared/ModalContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import { SelectField, TextAreaField, TextField } from 'shared/Form';
import DataTable from 'shared/DataTable';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import { apiFormFromConfig, parseColumnList, toSourceRequest } from './apiConfig';
import { displayValue } from 'utils/format';
import { t } from 'i18n';

const SourceModal = ({ projectId, source, onClose, onSaved }) => {
  const dispatch = useDispatch();
  const editing = Boolean(source?.id);
  const [form, setForm] = useState({
    name: source?.name || '',
    description: source?.description || '',
    kind: source?.kind || 'upload',
    api: apiFormFromConfig(source?.apiConfig),
    expected: (source?.expectedColumns || []).join('\n'),
  });
  const [errors, setErrors] = useState({});
  const [busy, setBusy] = useState(false);
  const [sample, setSample] = useState(null);
  const [layoutFile, setLayoutFile] = useState(null);
  const secretsSet = source?.secretsSet || {};
  const isApi = form.kind === 'api';

  const set = (field) => (value) => setForm((f) => ({ ...f, [field]: value }));
  const setApi = (field) => (value) => setForm((f) => ({ ...f, api: { ...f.api, [field]: value } }));
  const savedHint = (flag) => (flag ? t('secretSavedHint') : undefined);
  const savedPlaceholder = (flag) => (flag ? '••••••••' : '');

  const validate = () => {
    const found = {};
    if (!form.name.trim()) found.name = t('requiredField');
    if (isApi && !form.api.baseUrl.trim()) found.baseUrl = t('requiredField');
    setErrors(found);
    return Object.keys(found).length === 0;
  };

  const save = async () => {
    if (!validate()) return;
    setBusy(true);
    try {
      const body = toSourceRequest(form);
      let saved = editing ? await sources.update(projectId, source.id, body) : await sources.create(projectId, body);
      if (layoutFile && !isApi) {
        const inferred = await sourceLayout.infer(projectId, saved.id, layoutFile);
        const { expectedColumns, ...rest } = body;
        saved = await sources.update(projectId, saved.id, { ...rest, layout: inferred.layout });
        dispatch(setSnackbarSuccess(t('layoutDerivedOnCreate', { file: layoutFile.name, columns: inferred.layout.columns.length })));
      } else {
        dispatch(setSnackbarSuccess(t('sourceSaved')));
      }
      onSaved(saved);
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    } finally {
      setBusy(false);
    }
  };

  const test = async () => {
    if (!validate()) return;
    setBusy(true);
    setSample(null);
    try {
      setSample(await sources.test(projectId, source.id, toSourceRequest(form)));
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    } finally {
      setBusy(false);
    }
  };

  const api = form.api;

  return (
    <ModalContainer
      modal
      size="lg"
      toggleModal={onClose}
      header={editing ? t('editSourceHeader') : t('addSourceHeader')}
      subHeader={t('sourceModalIntro')}
      modalFooterContent={(
        <>
          {editing && isApi && <ActionButton title={t('testConnection')} buttonColor="secondary" classes="mb-0 mr-auto" disabled={busy} onClickAction={test} />}
          <ActionButton title={t('cancelButton')} buttonColor="secondary" classes="mb-0" onClickAction={onClose} />
          <ActionButton title={t('saveButton')} outline={false} classes="mb-0" disabled={busy} onClickAction={save} />
        </>
      )}
    >
      <TextField label={t('sourceName')} placeholder={t('sourceNamePlaceholder')} value={form.name} onChange={set('name')} error={errors.name} required autoFocus />
      <TextAreaField label={t('sourceDescription')} rows={2} value={form.description} onChange={set('description')} />
      <SelectField label={t('sourceKind')} value={form.kind} onChange={set('kind')} disabled={editing && Boolean(source.latestDataset)} hint={t('sourceKindHint')}>
        <option value="upload">{t('kindUpload')}</option>
        <option value="api">{t('kindApi')}</option>
      </SelectField>

      {!isApi && (
        <div className="form-group">
          <label htmlFor="layout-file">{t('deriveFromFile')}</label>
          <input id="layout-file" type="file" accept=".xlsx,.xls,.csv,.txt" className="form-control-file d-block" onChange={(e) => setLayoutFile(e.target.files[0] || null)} />
          <span className="field-hint">{t('deriveFromFileHint')}</span>
        </div>
      )}

      <TextAreaField
        label={t('expectedColumns')}
        rows={4}
        className="mono"
        value={form.expected}
        onChange={set('expected')}
        placeholder={'Txn Ref\nTxn Type\nEmployee ID'}
        hint={t('expectedColumnsHint', { count: parseColumnList(form.expected).length })}
      />

      {isApi && (
        <>
          <div className="section-label">{t('apiConnection')}</div>
          <div className="d-flex">
            <TextField className="mr-2" label={t('apiBaseUrl')} placeholder="https://core.example.com/api" value={api.baseUrl} onChange={setApi('baseUrl')} error={errors.baseUrl} required />
            <TextField label={t('apiPath')} placeholder="/v1/transactions" value={api.path} onChange={setApi('path')} />
          </div>
          <div className="d-flex">
            <SelectField className="mr-2" label={t('apiMethod')} value={api.method} onChange={setApi('method')}>
              <option value="GET">GET</option>
              <option value="POST">POST</option>
            </SelectField>
            <TextField label={t('apiRowsPath')} placeholder="data.items" value={api.rowsPath} onChange={setApi('rowsPath')} hint={t('apiRowsPathHint')} />
          </div>
          {api.method === 'POST' && <TextAreaField label={t('apiBody')} value={api.body} onChange={setApi('body')} className="mono" />}
          <div className="d-flex">
            <TextAreaField className="mr-2" label={t('apiQuery')} rows={3} value={api.query} onChange={setApi('query')} placeholder="status=active" hint={t('apiOnePerLine')} />
            <TextAreaField label={t('apiHeaders')} rows={3} value={api.headers} onChange={setApi('headers')} placeholder="Accept-Language: en" hint={t('apiOnePerLine')} />
          </div>

          <div className="section-label">{t('apiAuthentication')}</div>
          <SelectField label={t('apiAuthType')} value={api.authType} onChange={setApi('authType')}>
            <option value="none">{t('authNone')}</option>
            <option value="bearer">{t('authBearer')}</option>
            <option value="apiKey">{t('authApiKey')}</option>
            <option value="basic">{t('authBasic')}</option>
          </SelectField>
          {api.authType === 'bearer' && (
            <TextField label={t('authToken')} type="password" value={api.token} onChange={setApi('token')} placeholder={savedPlaceholder(secretsSet.token)} hint={savedHint(secretsSet.token)} />
          )}
          {api.authType === 'apiKey' && (
            <div className="d-flex">
              <TextField className="mr-2" label={t('authApiKeyHeader')} value={api.apiKeyHeader} onChange={setApi('apiKeyHeader')} />
              <TextField label={t('authApiKeyValue')} type="password" value={api.apiKey} onChange={setApi('apiKey')} placeholder={savedPlaceholder(secretsSet.apiKey)} hint={savedHint(secretsSet.apiKey)} />
            </div>
          )}
          {api.authType === 'basic' && (
            <div className="d-flex">
              <TextField className="mr-2" label={t('authUsername')} value={api.username} onChange={setApi('username')} placeholder={savedPlaceholder(secretsSet.username)} hint={savedHint(secretsSet.username)} />
              <TextField label={t('loginPassword')} type="password" value={api.password} onChange={setApi('password')} placeholder={savedPlaceholder(secretsSet.password)} hint={savedHint(secretsSet.password)} />
            </div>
          )}

          <div className="section-label">{t('apiPaging')}</div>
          <div className="d-flex">
            <SelectField className="mr-2" label={t('apiPagingType')} value={api.pagingType} onChange={setApi('pagingType')}>
              <option value="none">{t('pagingNone')}</option>
              <option value="page">{t('pagingPage')}</option>
              <option value="offset">{t('pagingOffset')}</option>
            </SelectField>
            {api.pagingType !== 'none' && (
              <TextField label={t('apiPageSize')} type="number" min={1} value={api.pageSize} onChange={setApi('pageSize')} />
            )}
          </div>

          {sample && (
            <>
              <div className="section-label">{t('connectionSample', { count: sample.rows.length })}</div>
              <DataTable
                dense
                rows={sample.rows}
                rowKey={(row, index) => index}
                columns={sample.columns.map((column, index) => ({ key: column, header: column, render: (row) => displayValue(row[index]) }))}
              />
            </>
          )}
        </>
      )}
    </ModalContainer>
  );
};

export default SourceModal;
