import React, { useEffect, useState } from 'react';
import { useDispatch } from 'react-redux';
import { NavLink, useParams } from 'react-router-dom';
import { projectExport, projects, targetOutput, transactionTypes } from 'api';
import { blobErrorMessage, errorMessage } from 'api/client';
import { appRoutes } from 'app/routes';
import LayoutContainer from 'shared/LayoutContainer';
import ActionButton from 'shared/Buttons/ActionButton';
import DataTable from 'shared/DataTable';
import { SelectField, TextField } from 'shared/Form';
import { LogicStatusBadge, RunStatusBadge } from 'shared/StatusBadge';
import useActiveProject, { projectCrumbs } from 'shared/hooks/useActiveProject';
import useAsync from 'shared/hooks/useAsync';
import { setSnackbarError, setSnackbarSuccess } from 'shared/redux';
import { saveBlob } from 'utils/download';
import { formatInteger } from 'utils/format';
import { t } from 'i18n';

const DELIMITERS = [[',', 'delimiterComma'], [';', 'delimiterSemicolon'], ['\t', 'delimiterTab'], ['|', 'delimiterPipe']];

/** Target system output: the files the migration produces, what each is waiting for, and how they are named and formatted. */
const TargetOutput = () => {
  const { projectId } = useParams();
  const dispatch = useDispatch();
  const { project, reload: reloadProject } = useActiveProject(projectId);
  const state = useAsync(() => targetOutput.outputs(projectId), [projectId]);
  const routines = state.data || [];
  const [settings, setSettings] = useState({ csvDelimiter: ',', fileNamePattern: '' });
  const [saving, setSaving] = useState(false);
  const target = project?.targetSystemName || '';

  useEffect(() => {
    if (project) setSettings({ csvDelimiter: project.csvDelimiter, fileNamePattern: project.fileNamePattern });
  }, [project]);

  const dirty = project && (settings.csvDelimiter !== project.csvDelimiter || settings.fileNamePattern !== project.fileNamePattern);
  const allReady = routines.length > 0 && routines.every((r) => r.ready);

  const saveSettings = async () => {
    setSaving(true);
    try {
      await projects.update(projectId, { ...project, ...settings });
      dispatch(setSnackbarSuccess(t('outputSettingsSaved')));
      await reloadProject();
    } catch (e) {
      dispatch(setSnackbarError(errorMessage(e)));
    } finally {
      setSaving(false);
    }
  };

  const download = async (routine, format, outputId) => {
    try {
      const params = { format };
      if (outputId) params.output = outputId;
      saveBlob(await transactionTypes.export(projectId, routine.id, params), `${routine.name}.${format}`);
    } catch (e) {
      dispatch(setSnackbarError(await blobErrorMessage(e)));
    }
  };

  const downloadPack = async () => {
    try {
      saveBlob(await projectExport(projectId), 'migration.xlsx');
    } catch (e) {
      dispatch(setSnackbarError(await blobErrorMessage(e)));
    }
  };

  return (
    <LayoutContainer heading={t('outputPageHeader', { system: target })} breadcrumbs={projectCrumbs(project, { title: t('outputPageHeader', { system: target }) })} wide>
      <div className="pr-3">
        <div className="panel">
          <h2>{t('outputFilesHeader')}</h2>
          <div className="panel-help">{t('outputFilesHelp', { system: target })}</div>
          <DataTable
            caption={t('outputFilesHeader')}
            rows={routines}
            rowKey={(r) => r.id}
            emptyText={t('noRoutinesText')}
            columns={[
              { key: 'name', header: t('transformationRoutine'), render: (r) => <NavLink to={appRoutes.logic(projectId, r.id)}>{r.name}</NavLink> },
              { key: 'logic', header: t('logicStatus'), render: (r) => <LogicStatusBadge status={r.logicStatus} /> },
              { key: 'run', header: t('liveDataStatus'), render: (r) => <RunStatusBadge run={r.run} /> },
              {
                key: 'files',
                header: t('outputFiles'),
                render: (r) => (r.outputs.length === 0 ? t('notSet') : r.outputs.map((o) => (
                  <div key={o.id}>{r.ready ? `${o.name} · ${t('rowsCount', { count: formatInteger(o.rows) })}` : o.name}</div>
                ))),
              },
              {
                key: 'download',
                header: '',
                render: (r) => (r.ready ? (
                  <>
                    <ActionButton title={t('exportExcel')} classes="btn-sm mr-2 mb-0" onClickAction={() => download(r, 'xlsx')} />
                    {r.outputs.map((o) => (
                      <ActionButton key={o.id} title={r.outputs.length > 1 ? t('exportCsvNamed', { name: o.name }) : t('exportCsv')} buttonColor="secondary" classes="btn-sm mr-2 mb-0" onClickAction={() => download(r, 'csv', o.id)} />
                    ))}
                  </>
                ) : (
                  <span className="text-secondary">
                    {r.blocker} <NavLink to={appRoutes.reconciliation(projectId, r.id)}>{t('goToReconciliation')}</NavLink>
                  </span>
                )),
              },
            ]}
          />
          <div className="mt-3">
            <ActionButton title={t('downloadPack')} outline={false} disabled={!allReady} onClickAction={downloadPack} />
            <span className="ml-3 text-secondary">{allReady ? t('packReady') : t('packLocked')}</span>
          </div>
        </div>

        <div className="panel">
          <h2>{t('outputSettingsHeader')}</h2>
          <div className="panel-help">{t('outputSettingsHelp', { system: target })}</div>
          <div className="d-flex flex-wrap align-items-start">
            <SelectField className="mr-3 w-auto" label={t('csvDelimiter')} value={settings.csvDelimiter} onChange={(v) => setSettings((s) => ({ ...s, csvDelimiter: v }))}>
              {DELIMITERS.map(([value, label]) => <option key={label} value={value}>{t(label)}</option>)}
            </SelectField>
            <TextField
              className="mr-3"
              label={t('fileNamePattern')}
              value={settings.fileNamePattern}
              onChange={(v) => setSettings((s) => ({ ...s, fileNamePattern: v }))}
              hint={t('fileNamePatternHint')}
              style={{ minWidth: '22rem' }}
            />
          </div>
          <ActionButton title={t('saveButton')} outline={false} disabled={saving || !dirty} onClickAction={saveSettings} />
        </div>
      </div>
    </LayoutContainer>
  );
};

export default TargetOutput;
