// Helpers that turn the API source form into the shape the back end stores, and back again.

export const parseLines = (text, separator) => {
  const result = {};
  (text || '').split('\n').forEach((line) => {
    const at = line.indexOf(separator);
    if (at <= 0) return;
    const key = line.slice(0, at).trim();
    if (key) result[key] = line.slice(at + 1).trim();
  });
  return result;
};

export const formatLines = (map, separator) =>
  Object.entries(map || {}).map(([key, value]) => `${key}${separator === ':' ? ': ' : separator}${value}`).join('\n');

/** A column list typed one per line or pasted as a header row (tab or comma separated). */
export const parseColumnList = (text) => {
  const seen = new Set();
  return (text || '').split(/[\r\n\t,]+/).map((c) => c.trim()).filter((c) => {
    if (!c || seen.has(c.toLowerCase())) return false;
    seen.add(c.toLowerCase());
    return true;
  });
};

export const blankApiForm = () => ({
  baseUrl: '',
  path: '',
  method: 'GET',
  body: '',
  authType: 'none',
  apiKeyHeader: 'X-Api-Key',
  rowsPath: '',
  headers: '',
  query: '',
  pagingType: 'none',
  pageSize: 100,
  token: '',
  apiKey: '',
  username: '',
  password: '',
});

export const apiFormFromConfig = (config) => {
  if (!config) return blankApiForm();
  const paging = config.paging || {};
  return {
    ...blankApiForm(),
    baseUrl: config.baseUrl || '',
    path: config.path || '',
    method: config.method || 'GET',
    body: config.body || '',
    authType: config.authType || 'none',
    apiKeyHeader: config.apiKeyHeader || 'X-Api-Key',
    rowsPath: config.rowsPath || '',
    headers: formatLines(config.headers, ':'),
    query: formatLines(config.query, '='),
    pagingType: paging.type || 'none',
    pageSize: paging.pageSize || 100,
  };
};

/** The request body for creating or updating an API source. Blank secret fields are omitted so stored values are kept. */
export const toSourceRequest = ({ name, description, kind, api, expected }) => {
  const expectedColumns = parseColumnList(expected);
  if (kind !== 'upload') {
    const secrets = {};
    ['token', 'apiKey', 'username', 'password'].forEach((field) => {
      if (api[field]) secrets[field] = api[field];
    });
    return {
      name: name.trim(),
      description: description.trim() || null,
      kind,
      apiConfig: {
        baseUrl: api.baseUrl.trim(),
        path: api.path.trim(),
        method: api.method,
        body: api.method === 'POST' && api.body.trim() ? api.body : null,
        authType: api.authType,
        apiKeyHeader: api.apiKeyHeader.trim() || 'X-Api-Key',
        rowsPath: api.rowsPath.trim() || null,
        headers: parseLines(api.headers, ':'),
        query: parseLines(api.query, '='),
        paging: { type: api.pagingType, pageSize: Number(api.pageSize) || 100 },
      },
      secrets,
      expectedColumns,
    };
  }
  return { name: name.trim(), description: description.trim() || null, kind, expectedColumns };
};
